import "C"

import (
	"errors"
	"strings"
	"sync"
	"time"
	"unsafe"
)

// SQLite result codes used here.
const (
	sqliteOK   = 0
	sqliteRow  = 100
	sqliteDone = 101
)

// DB is a minimal SQLite connection wrapper.
type DB struct {
	db *C.sqlite3
}

// Stmt is a prepared statement.
type Stmt struct {
	db       *DB
	s        *C.sqlite3_stmt
	decltype []string
}

func openSQLite(dsn string) (*DB, error) {
	name := dsn
	if strings.HasPrefix(name, "file:") {
		// URI filenames are handled by SQLite itself.
	}
	cname := C.CString(name)
	defer C.free(unsafe.Pointer(cname))
	var db *C.sqlite3
	flags := C.SQLITE_OPEN_READWRITE | C.SQLITE_OPEN_CREATE | C.SQLITE_OPEN_FULLMUTEX | C.SQLITE_OPEN_URI
	rc := C.sqlite3_open_v2(cname, &db, C.int(flags), nil)
	if rc != sqliteOK {
		msg := "unable to open database file"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close_v2(db)
		}
		return nil, errors.New(msg)
	}
	C.sqlite3_extended_result_codes(db, 1)
	d := &DB{db: db}
	return d, nil
}

func (d *DB) Close() {
	if d.db != nil {
		C.sqlite3_close_v2(d.db)
		d.db = nil
	}
}

func (d *DB) errmsg() error {
	return errors.New(C.GoString(C.sqlite3_errmsg(d.db)))
}

// Exec executes all statements in sql.
func (d *DB) Exec(sql string) error {
	rest := sql
	for {
		st, tail, err := d.Prepare(rest)
		if err != nil {
			return err
		}
		if st == nil {
			return nil
		}
		for {
			has, err := st.Step()
			if err != nil {
				st.Finalize()
				return err
			}
			if !has {
				break
			}
		}
		st.Finalize()
		if strings.TrimSpace(tail) == "" {
			return nil
		}
		rest = tail
	}
}

// Prepare compiles the first statement in sql. stmt is nil when the sql has no statement.
func (d *DB) Prepare(sql string) (*Stmt, string, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var s *C.sqlite3_stmt
	var tail *C.char
	rc := C.sqlite3_prepare_v2(d.db, csql, C.int(len(sql)), &s, &tail)
	if rc != sqliteOK {
		return nil, "", d.errmsg()
	}
	t := ""
	if tail != nil {
		off := uintptr(unsafe.Pointer(tail)) - uintptr(unsafe.Pointer(csql))
		if int(off) < len(sql) {
			t = sql[off:]
		}
	}
	if s == nil {
		return nil, t, nil
	}
	st := &Stmt{db: d, s: s}
	n := int(C.sqlite3_column_count(s))
	st.decltype = make([]string, n)
	for i := 0; i < n; i++ {
		p := C.sqlite3_column_decltype(s, C.int(i))
		if p != nil {
			st.decltype[i] = C.GoString(p)
		}
	}
	return st, t, nil
}

func (s *Stmt) Finalize() {
	if s.s != nil {
		C.sqlite3_finalize(s.s)
		s.s = nil
	}
}

func (s *Stmt) Reset() {
	C.sqlite3_reset(s.s)
	C.sqlite3_clear_bindings(s.s)
}

func (s *Stmt) ParamCount() int {
	return int(C.sqlite3_bind_parameter_count(s.s))
}

func (s *Stmt) Bind(i int, v any) error {
	var rc C.int
	switch t := v.(type) {
	case nil:
		rc = C.sqlite3_bind_null(s.s, C.int(i))
	case string:
		if len(t) == 0 {
			rc = C.trd_bind_text(s.s, C.int(i), (*C.char)(unsafe.Pointer(&[]byte{0}[0])), 0)
		} else {
			b := []byte(t)
			rc = C.trd_bind_text(s.s, C.int(i), (*C.char)(unsafe.Pointer(&b[0])), C.int(len(b)))
		}
	case []byte:
		if len(t) == 0 {
			rc = C.trd_bind_blob(s.s, C.int(i), nil, 0)
		} else {
			rc = C.trd_bind_blob(s.s, C.int(i), unsafe.Pointer(&t[0]), C.int(len(t)))
		}
	case int:
		rc = C.sqlite3_bind_int64(s.s, C.int(i), C.sqlite3_int64(t))
	case int64:
		rc = C.sqlite3_bind_int64(s.s, C.int(i), C.sqlite3_int64(t))
	case float64:
		rc = C.sqlite3_bind_double(s.s, C.int(i), C.double(t))
	case bool:
		x := 0
		if t {
			x = 1
		}
		rc = C.sqlite3_bind_int64(s.s, C.int(i), C.sqlite3_int64(x))
	default:
		str := toString(v)
		b := []byte(str)
		if len(b) == 0 {
			b = []byte{0}
			rc = C.trd_bind_text(s.s, C.int(i), (*C.char)(unsafe.Pointer(&b[0])), 0)
		} else {
			rc = C.trd_bind_text(s.s, C.int(i), (*C.char)(unsafe.Pointer(&b[0])), C.int(len(b)))
		}
	}
	if rc != sqliteOK {
		return s.db.errmsg()
	}
	return nil
}

// Step advances; returns true when a row is available.
func (s *Stmt) Step() (bool, error) {
	rc := C.sqlite3_step(s.s)
	switch rc {
	case sqliteRow:
		return true, nil
	case sqliteDone:
		return false, nil
	default:
		return false, s.db.errmsg()
	}
}

func (s *Stmt) ColumnCount() int {
	return int(C.sqlite3_column_count(s.s))
}

func (s *Stmt) ColumnName(i int) string {
	return C.GoString(C.sqlite3_column_name(s.s, C.int(i)))
}

// DeclType returns the declared type (as written).
func (s *Stmt) DeclType(i int) string {
	return s.decltype[i]
}

var sqliteTimestampFormats = []string{
	"2006-01-02 15:04:05.999999999-07:00",
	"2006-01-02T15:04:05.999999999-07:00",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02T15:04:05.999999999",
	"2006-01-02 15:04:05",
	"2006-01-02T15:04:05",
	"2006-01-02 15:04",
	"2006-01-02T15:04",
	"2006-01-02",
}

// Column returns the value of column i converted like go-sqlite3.
func (s *Stmt) Column(i int) any {
	dt := strings.ToLower(s.decltype[i])
	switch C.sqlite3_column_type(s.s, C.int(i)) {
	case C.SQLITE_INTEGER:
		val := int64(C.sqlite3_column_int64(s.s, C.int(i)))
		switch dt {
		case "timestamp", "datetime", "date":
			var t time.Time
			if val > 1e12 || val < -1e12 {
				t = time.Unix(0, val*int64(time.Millisecond))
			} else {
				t = time.Unix(val, 0)
			}
			return t.UTC()
		case "boolean":
			return val > 0
		}
		return val
	case C.SQLITE_FLOAT:
		return float64(C.sqlite3_column_double(s.s, C.int(i)))
	case C.SQLITE_BLOB:
		p := C.sqlite3_column_blob(s.s, C.int(i))
		n := int(C.sqlite3_column_bytes(s.s, C.int(i)))
		if p == nil || n == 0 {
			return []byte{}
		}
		return C.GoBytes(p, C.int(n))
	case C.SQLITE_NULL:
		return nil
	case C.SQLITE_TEXT:
		p := C.sqlite3_column_text(s.s, C.int(i))
		n := int(C.sqlite3_column_bytes(s.s, C.int(i)))
		str := C.GoStringN((*C.char)(unsafe.Pointer(p)), C.int(n))
		switch dt {
		case "timestamp", "datetime", "date":
			str = strings.TrimSuffix(str, "Z")
			for _, f := range sqliteTimestampFormats {
				if t, err := time.ParseInLocation(f, str, time.UTC); err == nil {
					return t
				}
			}
			return time.Time{}
		}
		return str
	}
	return nil
}

// ---- user defined functions ----

type sqlValue = any

type scalarFunc func(args []sqlValue) (sqlValue, error)

type aggFunc struct {
	newState func() aggState
}

type aggState interface {
	Step(args []sqlValue)
	Final() (sqlValue, error)
}

var (
	funcMu      sync.Mutex
	scalarFuncs = map[int64]scalarFunc{}
	aggFuncs    = map[int64]aggFunc{}
	aggStates   = map[int64]aggState{}
	funcNextID  int64 = 1
	aggNextID   int64 = 1
)

func valueToGo(v *C.sqlite3_value) sqlValue {
	switch C.sqlite3_value_type(v) {
	case C.SQLITE_INTEGER:
		return int64(C.sqlite3_value_int64(v))
	case C.SQLITE_FLOAT:
		return float64(C.sqlite3_value_double(v))
	case C.SQLITE_BLOB:
		n := int(C.sqlite3_value_bytes(v))
		p := C.sqlite3_value_blob(v)
		if p == nil || n == 0 {
			return []byte{}
		}
		return C.GoBytes(p, C.int(n))
	case C.SQLITE_TEXT:
		n := int(C.sqlite3_value_bytes(v))
		p := C.sqlite3_value_text(v)
		return C.GoStringN((*C.char)(unsafe.Pointer(p)), C.int(n))
	}
	return nil
}

func argsToGo(argc C.int, argv **C.sqlite3_value) []sqlValue {
	args := make([]sqlValue, int(argc))
	for i := 0; i < int(argc); i++ {
		args[i] = valueToGo(C.trd_arg(argv, C.int(i)))
	}
	return args
}

func setResult(ctx *C.sqlite3_context, v sqlValue, err error) {
	if err != nil {
		msg := C.CString(err.Error())
		C.sqlite3_result_error(ctx, msg, -1)
		C.free(unsafe.Pointer(msg))
		return
	}
	switch t := v.(type) {
	case nil:
		C.sqlite3_result_null(ctx)
	case int64:
		C.sqlite3_result_int64(ctx, C.sqlite3_int64(t))
	case int:
		C.sqlite3_result_int64(ctx, C.sqlite3_int64(t))
	case bool:
		if t {
			C.sqlite3_result_int64(ctx, 1)
		} else {
			C.sqlite3_result_int64(ctx, 0)
		}
	case float64:
		C.sqlite3_result_double(ctx, C.double(t))
	case string:
		if len(t) == 0 {
			b := []byte{0}
			C.trd_result_text(ctx, (*C.char)(unsafe.Pointer(&b[0])), 0)
		} else {
			b := []byte(t)
			C.trd_result_text(ctx, (*C.char)(unsafe.Pointer(&b[0])), C.int(len(b)))
		}
	case []byte:
		if len(t) == 0 {
			C.sqlite3_result_zeroblob(ctx, 0)
		} else {
			C.trd_result_blob(ctx, unsafe.Pointer(&t[0]), C.int(len(t)))
		}
	default:
		s := toString(v)
		b := []byte(s + "\x00")
		C.trd_result_text(ctx, (*C.char)(unsafe.Pointer(&b[0])), C.int(len(s)))
	}
}

//export goScalarFunc
func goScalarFunc(ctx *C.sqlite3_context, argc C.int, argv **C.sqlite3_value) {
	id := int64(C.trd_user_data(ctx))
	funcMu.Lock()
	f := scalarFuncs[id]
	funcMu.Unlock()
	args := argsToGo(argc, argv)
	v, err := f(args)
	setResult(ctx, v, err)
}

func aggStateFor(ctx *C.sqlite3_context, create bool) aggState {
	p := C.trd_agg_ctx(ctx)
	if p == nil {
		return nil
	}
	funcMu.Lock()
	defer funcMu.Unlock()
	if *p == 0 {
		if !create {
			return nil
		}
		id := int64(C.trd_user_data(ctx))
		st := aggFuncs[id].newState()
		sid := aggNextID
		aggNextID++
		aggStates[sid] = st
		*p = C.longlong(sid)
		return st
	}
	return aggStates[int64(*p)]
}

//export goAggStep
func goAggStep(ctx *C.sqlite3_context, argc C.int, argv **C.sqlite3_value) {
	st := aggStateFor(ctx, true)
	if st == nil {
		return
	}
	st.Step(argsToGo(argc, argv))
}

//export goAggFinal
func goAggFinal(ctx *C.sqlite3_context) {
	p := C.trd_agg_ctx(ctx)
	var st aggState
	funcMu.Lock()
	if p != nil && *p != 0 {
		st = aggStates[int64(*p)]
		delete(aggStates, int64(*p))
	}
	funcMu.Unlock()
	if st == nil {
		id := int64(C.trd_user_data(ctx))
		funcMu.Lock()
		st = aggFuncs[id].newState()
		funcMu.Unlock()
	}
	v, err := st.Final()
	setResult(ctx, v, err)
}

const (
	fnDeterministic = 0x000000800
)

func (d *DB) RegisterScalar(name string, nargs int, deterministic bool, f scalarFunc) error {
	funcMu.Lock()
	id := funcNextID
	funcNextID++
	scalarFuncs[id] = f
	funcMu.Unlock()
	cname := C.CString(name)
	defer C.free(unsafe.Pointer(cname))
	flags := 0
	if deterministic {
		flags = fnDeterministic
	}
	rc := C.trd_create_scalar(d.db, cname, C.int(nargs), C.int(flags), C.long(id))
	if rc != sqliteOK {
		return d.errmsg()
	}
	return nil
}

func (d *DB) RegisterAggregate(name string, nargs int, newState func() aggState) error {
	funcMu.Lock()
	id := funcNextID
	funcNextID++
	aggFuncs[id] = aggFunc{newState: newState}
	funcMu.Unlock()
	cname := C.CString(name)
	defer C.free(unsafe.Pointer(cname))
	rc := C.trd_create_agg(d.db, cname, C.int(nargs), C.int(fnDeterministic), C.long(id))
	if rc != sqliteOK {
		return d.errmsg()
	}
	return nil
}
EOF
echo ok"}

