var debugMode bool

func debugf(format string, args ...any) {
	if debugMode {
		log.Printf(format, args...)
	}
}

func debugln(args ...any) {
	if debugMode {
		log.Println(args...)
	}
}

// nullValue implements flag.Value for -inull/-onull.
type nullValue struct {
	set bool
	val string
}

func (n *nullValue) String() string { return n.val }
func (n *nullValue) Set(s string) error {
	n.set = true
	n.val = s
	return nil
}

type cliFlags struct {
	analyze      string
	analyzeQuiet string
	config       string
	db           string
	dblist       bool
	debug        bool
	driver       string
	dsn          string
	help         bool
	queryFile    string
	tableFile    string
	version      bool

	iCSV, iG, iJSON, iLTSV, iTBLN, iTEXT, iWIDTH, iYAML bool

	inDelimiter string
	inHeader    bool
	inJQ        string
	inLimit     int
	inNull      nullValue
	inNum       bool
	inPreRead   int
	inSkip      int

	oAT, oCSV, oJSON, oJSONL, oLTSV, oMD, oRAW, oTBLN, oVF, oYAML bool

	outAllQuote     bool
	outCRLF         bool
	outDelimiter    string
	outHeader       bool
	outNoWrap       bool
	outNull         nullValue
	outQuote        string
	outFile         string
	outWithoutGuess bool
	outCompression  string
}

func printUsage() {
	fmt.Fprint(os.Stderr, usageText)
}

func main() {
	os.Exit(run(os.Args))
}

func run(args []string) int {
	log.SetOutput(os.Stderr)
	f := &cliFlags{}
	fs := flag.NewFlagSet(args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = printUsage

	fs.StringVar(&f.analyzeQuiet, "A", "", "")
	fs.StringVar(&f.analyze, "a", "", "")
	fs.StringVar(&f.config, "config", "", "")
	fs.StringVar(&f.db, "db", "", "")
	fs.BoolVar(&f.dblist, "dblist", false, "")
	fs.BoolVar(&f.debug, "debug", false, "")
	fs.StringVar(&f.driver, "driver", "", "")
	fs.StringVar(&f.dsn, "dsn", "", "")
	fs.BoolVar(&f.help, "help", false, "")
	fs.StringVar(&f.queryFile, "q", "", "")
	fs.StringVar(&f.tableFile, "t", "", "")
	fs.BoolVar(&f.version, "version", false, "")

	fs.BoolVar(&f.iCSV, "icsv", false, "")
	fs.BoolVar(&f.iG, "ig", true, "")
	fs.BoolVar(&f.iJSON, "ijson", false, "")
	fs.BoolVar(&f.iLTSV, "iltsv", false, "")
	fs.BoolVar(&f.iTBLN, "itbln", false, "")
	fs.BoolVar(&f.iTEXT, "itext", false, "")
	fs.BoolVar(&f.iWIDTH, "iwidth", false, "")
	fs.BoolVar(&f.iYAML, "iyaml", false, "")

	fs.StringVar(&f.inDelimiter, "id", ",", "")
	fs.BoolVar(&f.inHeader, "ih", false, "")
	fs.StringVar(&f.inJQ, "ijq", "", "")
	fs.IntVar(&f.inLimit, "ilr", 0, "")
	fs.Var(&f.inNull, "inull", "")
	fs.BoolVar(&f.inNum, "inum", false, "")
	fs.IntVar(&f.inPreRead, "ir", 1, "")
	fs.IntVar(&f.inSkip, "is", 0, "")

	fs.BoolVar(&f.oAT, "oat", false, "")
	fs.BoolVar(&f.oCSV, "ocsv", false, "")
	fs.BoolVar(&f.oJSON, "ojson", false, "")
	fs.BoolVar(&f.oJSONL, "ojsonl", false, "")
	fs.BoolVar(&f.oLTSV, "oltsv", false, "")
	fs.BoolVar(&f.oMD, "omd", false, "")
	fs.BoolVar(&f.oRAW, "oraw", false, "")
	fs.BoolVar(&f.oTBLN, "otbln", false, "")
	fs.BoolVar(&f.oVF, "ovf", false, "")
	fs.BoolVar(&f.oYAML, "oyaml", false, "")

	fs.BoolVar(&f.outAllQuote, "oaq", false, "")
	fs.BoolVar(&f.outCRLF, "ocrlf", false, "")
	fs.StringVar(&f.outDelimiter, "od", ",", "")
	fs.BoolVar(&f.outHeader, "oh", false, "")
	fs.BoolVar(&f.outNoWrap, "onowrap", false, "")
	fs.Var(&f.outNull, "onull", "")
	fs.StringVar(&f.outQuote, "oq", "\"", "")
	fs.StringVar(&f.outFile, "out", "", "")
	fs.BoolVar(&f.outWithoutGuess, "out-without-guess", false, "")
	fs.StringVar(&f.outCompression, "oz", "", "")

	if err := fs.Parse(args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}

	if f.version {
		fmt.Printf("trdsql version %s\n", "devel")
		return 0
	}

	debugMode = f.debug

	cfg, err := loadConfig(f.config)
	if err != nil {
		log.Printf("ERROR: %s", err)
		return 1
	}

	if f.help {
		printUsage()
		return 2
	}

	if f.dblist {
		if cfg != nil {
			for name, d := range cfg.Database {
				fmt.Printf("%s:%s\n", name, d.Driver)
			}
		}
		return 0
	}

	driver := "sqlite3"
	dsn := ""
	if cfg != nil {
		dbName := cfg.Db
		if f.db != "" {
			dbName = f.db
		}
		if dbName != "" {
			if _, ok := cfg.Database[dbName]; !ok {
				log.Printf("ERROR: db[%s] does not found", dbName)
			}
		}
		for name, d := range cfg.Database {
			mark := " "
			if name == dbName {
				mark = ">"
				driver = d.Driver
				dsn = d.Dsn
			}
			debugf("%s[driver: %s:%s:%s]", mark, name, d.Driver, d.Dsn)
		}
	}
	if f.driver != "" {
		driver = f.driver
		dsn = f.dsn
	} else if f.dsn != "" {
		dsn = f.dsn
	}

	readOpts := buildReadOpts(f)

	if f.analyze != "" || f.analyzeQuiet != "" {
		fileName := f.analyze
		quiet := false
		if f.analyzeQuiet != "" {
			fileName = f.analyzeQuiet
			quiet = true
		}
		if err := analyzeFile(fileName, readOpts, args, quiet); err != nil {
			log.Printf("ERROR: %s", err)
			return 1
		}
		return 0
	}

	query := ""
	if f.tableFile != "" {
		query = "SELECT * FROM " + f.tableFile
	} else if f.queryFile != "" {
		b, err := os.ReadFile(f.queryFile)
		if err != nil {
			log.Printf("ERROR: %s", err)
			return 1
		}
		query = string(b)
	} else {
		query = strings.Join(fs.Args(), " ")
	}
	if strings.TrimSpace(query) == "" {
		printUsage()
		return 2
	}

	debugf("driver: %s, dsn: %s", driver, dsn)

	writeOpts, out, closer, err := buildWriteOpts(f)
	if err != nil {
		log.Printf("ERROR: %s", err)
		return 1
	}
	rc := execute(driver, dsn, query, readOpts, writeOpts, out)
	if cerr := closer(); cerr != nil && rc == 0 {
		log.Printf("ERROR: %s", cerr)
		rc = 1
	}
	return rc
}

func buildReadOpts(f *cliFlags) *ReadOpts {
	ro := &ReadOpts{
		InFormat:    fmtGUESS,
		InPreRead:   f.inPreRead,
		InSkip:      f.inSkip,
		InLimitRead: f.inLimit,
		InJQuery:    f.inJQ,
		InHeader:    f.inHeader,
		InDelimiter: f.inDelimiter,
		InNeedNULL:  f.inNull.set,
		InNULL:      f.inNull.val,
		InRowNumber: f.inNum,
	}
	switch {
	case f.iCSV:
		ro.InFormat = fmtCSV
	case f.iLTSV:
		ro.InFormat = fmtLTSV
	case f.iJSON:
		ro.InFormat = fmtJSON
	case f.iYAML:
		ro.InFormat = fmtYAML
	case f.iTBLN:
		ro.InFormat = fmtTBLN
	case f.iWIDTH:
		ro.InFormat = fmtWIDTH
	case f.iTEXT:
		ro.InFormat = fmtTEXT
	}
