package main

import (
	"strings"
)

// sqlFields splits a query into tokens.
func sqlFields(query string) []string {
	var parsed []string
	var buf strings.Builder
	singleQ, doubleQ, backQ := false, false, false
	flush := func() {
		if buf.Len() > 0 {
			parsed = append(parsed, buf.String())
			buf.Reset()
		}
	}
	for _, r := range query {
		inQuote := singleQ || doubleQ || backQ
		switch r {
		case ' ', '\t', '\r', '\n', ',', ';', '(', ')', '=':
			if !inQuote {
				flush()
				parsed = append(parsed, string(r))
				continue
			}
		case '\'':
			if !doubleQ && !backQ {
				singleQ = !singleQ
			}
		case '"':
			if !singleQ && !backQ {
				doubleQ = !doubleQ
			}
		case '`':
			if !singleQ && !doubleQ {
				backQ = !backQ
			}
		}
		buf.WriteRune(r)
	}
	flush()
	return parsed
}

func isSpaceToken(w string) bool {
	switch w {
	case " ", "\t", "\r", "\n":
		return true
	}
	return false
}

func isTableKeyword(w string) bool {
	switch strings.ToUpper(w) {
	case "FROM", "*FROM", "JOIN", "TABLE", "INTO", "UPDATE":
		return true
	}
	return false
}

func isResetKeyword(w string) bool {
	switch strings.ToUpper(w) {
	case "WHERE", "GROUP", "HAVING", "WINDOW", "UNION", "ORDER", "LIMIT", "OFFSET", "FETCH", "FOR",
		"LEFT", "RIGHT", "CROSS", "INNER", "FULL", "LATERAL":
		return true
	}
	return false
}

// tableIndexes returns the token indexes which are table names.
func tableIndexes(tokens []string) []int {
	var idx []int
	tableFlag := false
	frontFlag := false
	for i, w := range tokens {
		switch {
		case isSpaceToken(w):
			continue
		case isTableKeyword(w):
			tableFlag = true
			frontFlag = true
		case isResetKeyword(w):
			tableFlag = false
			frontFlag = false
		case w == ",":
			frontFlag = true
		default:
			if tableFlag && frontFlag {
				idx = append(idx, i)
			}
			frontFlag = false
		}
	}
	return idx
}

// quotedName quotes the name with backquotes.
func quotedName(name string) string {
	if len(name) >= 2 && name[0] == '`' && name[len(name)-1] == '`' {
		return name
	}
	return "`" + name + "`"
}

// trimQuote removes surrounding double or back quotes.
func trimQuote(s string) string {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '`' && s[len(s)-1] == '`') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

// trimJQQuote removes surrounding quotes of the jq expression.
func trimJQQuote(s string) string {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '`' && s[len(s)-1] == '`') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func debugTokens(tokens []string) {
	if !debugMode {
		return
	}
	var sb strings.Builder
	for _, t := range tokens {
		sb.WriteString("[")
		sb.WriteString(t)
		sb.WriteString("]")
	}
	debugln(sb.String())
}

// splitStatements splits tokens into statements separated by ';'.
func splitStatements(tokens []string) []string {
	var stmts []string
	var sb strings.Builder
	for _, t := range tokens {
		if t == ";" {
			stmts = append(stmts, sb.String())
			sb.Reset()
			continue
		}
		sb.WriteString(t)
	}
	stmts = append(stmts, sb.String())
	// drop trailing empty statements
	for len(stmts) > 1 && strings.TrimSpace(stmts[len(stmts)-1]) == "" {
		stmts = stmts[:len(stmts)-1]
	}
	return stmts
}
EOF
echo ok"}

