	return "`" + name + "`"
}

// trimQuote removes surrounding double or back quotes.
func trimQuote(s string) string {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '`' && s[len(s)-1] == '`') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

// trimJQQuote removes surrounding quotes of the jq expression.
func trimJQQuote(s string) string {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '`' && s[len(s)-1] == '`') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func debugTokens(tokens []string) {
	if !debugMode {
		return
	}
	var sb strings.Builder
	for _, t := range tokens {
		sb.WriteString("[")
		sb.WriteString(t)
		sb.WriteString("]")
	}
	debugln(sb.String())
}

// splitStatements splits tokens into statements separated by ';'.
func splitStatements(tokens []string) []string {
	var stmts []string
	var sb strings.Builder
	for _, t := range tokens {
		if t == ";" {
			stmts = append(stmts, sb.String())
			sb.Reset()
			continue
		}
		sb.WriteString(t)
	}
	stmts = append(stmts, sb.String())
	// drop trailing empty statements
	for len(stmts) > 1 && strings.TrimSpace(stmts[len(stmts)-1]) == "" {
		stmts = stmts[:len(stmts)-1]
	}
	return stmts
}
