		return bzip2.NewReader(br), nil
	case len(head) >= 4 && bytes.Equal(head[:4], []byte{0x28, 0xb5, 0x2f, 0xfd}):
		return newZstdReader(br)
	case len(head) >= 4 && bytes.Equal(head[:4], []byte{0x04, 0x22, 0x4d, 0x18}):
		return newLz4Reader(br)
	case len(head) >= 6 && bytes.Equal(head[:6], []byte{0xfd, '7', 'z', 'X', 'Z', 0x00}):
		return newXzReader(br)
	}
	return br, nil
}

// multiFileReader reads files sequentially, appending a newline after each file.
type multiFileReader struct {
	files []string
	cur   io.Reader
	curF  *os.File
	nl    bool
	err   error
}

func (m *multiFileReader) Read(p []byte) (int, error) {
	for {
		if m.err != nil {
			return 0, m.err
		}
		if m.cur == nil {
			if m.nl {
				m.nl = false
				if len(p) == 0 {
					return 0, nil
				}
				p[0] = '\n'
				return 1, nil
			}
			if len(m.files) == 0 {
				return 0, io.EOF
			}
			name := m.files[0]
			m.files = m.files[1:]
			debugf("Open: [%s]", name)
			f, err := os.Open(name)
			if err != nil {
				m.err = err
				return 0, err
			}
			r, err := decompressReader(f)
			if err != nil {
				f.Close()
				m.err = err
				return 0, err
			}
			m.cur = r
			m.curF = f
		}
		n, err := m.cur.Read(p)
		if err == io.EOF {
			debugf("Close: [%s]", m.curF.Name())
			m.curF.Close()
			m.cur = nil
			m.curF = nil
			m.nl = true
			if n > 0 {
				return n, nil
			}
			continue
		}
		return n, err
	}
}

func (m *multiFileReader) Close() error {
	if m.curF != nil {
		m.curF.Close()
	}
	return nil
}

