		if err != nil {
			return nil, nil, err
		}
		return r, nopCloser{}, nil
	}
	if !hasGlobMeta(fileName) {
		f, err := os.Open(fileName)
		if err != nil {
			return nil, nil, err
		}
		r, err := decompressReader(f)
		if err != nil {
			f.Close()
			return nil, nil, err
		}
		return r, f, nil
	}
	files, err := filepath.Glob(fileName)
	if err != nil {
		return nil, nil, err
	}
	if len(files) == 0 {
		return nil, nil, fmt.Errorf("no match found: %v", files)
	}
	m := &multiFileReader{files: files}
	return m, m, nil
}

