package main

import (
	"bufio"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"log"
	"strconv"
	"strings"
)

// ReadOpts holds input options.
type ReadOpts struct {
	InFormat    Format
	InPreRead   int
	InSkip      int
	InLimitRead int
	InJQuery    string
	InHeader    bool
	InDelimiter string
	InNeedNULL  bool
	InNULL      string
	InRowNumber bool
}

// Reader is the interface of the input readers.
type Reader interface {
	Names() ([]string, error)
	Types() ([]string, error)
	PreReadRow() [][]any
	ReadRow(row []any) ([]any, error)
}

var errInvalidNames = errors.New("invalid names")
var errInvalidTypes = errors.New("invalid types")
var errInvalidColumn = errors.New("invalid column")

func delimiter(sep string) (rune, error) {
	if sep == "" {
		return 0, nil
	}
	s, err := strconv.Unquote(`'` + sep + `'`)
	if err != nil {
		return ',', fmt.Errorf("can not get separator: %w:\"%s\"", err, sep)
	}
	r := []rune(s)
	return r[0], nil
}

func textTypes(n int) []string {
	t := make([]string, n)
	for i := range t {
		t[i] = "text"
	}
	return t
}

func nullConv(opts *ReadOpts, v any) any {
	if !opts.InNeedNULL {
		return v
	}
	if s, ok := v.(string); ok && s == opts.InNULL {
		return nil
	}
	return v
}

func newReader(format Format, r io.Reader, opts *ReadOpts, jq string) (Reader, error) {
	switch format {
	case fmtCSV:
		d, err := delimiter(opts.InDelimiter)
		if err != nil {
			return nil, err
		}
		return newCSVReader(r, opts, d)
	case fmtTSV:
		return newCSVReader(r, opts, '\t')
	case fmtPSV:
		return newCSVReader(r, opts, '|')
	case fmtLTSV:
		return newLTSVReader(r, opts)
	case fmtJSON:
		return newJSONReader(r, opts, jq)
	case fmtYAML:
		return newYAMLReader(r, opts, jq)
	case fmtTBLN:
		return newTBLNReader(r, opts)
	case fmtWIDTH:
		return newWidthReader(r, opts)
	case fmtTEXT:
		return newTextReader(r, opts)
	}
	d, err := delimiter(opts.InDelimiter)
	if err != nil {
		return nil, err
	}
	return newCSVReader(r, opts, d)
}

func preReadLimit(opts *ReadOpts) int {
	n := opts.InPreRead
	if opts.InLimitRead > 0 && opts.InLimitRead < n {
		n = opts.InLimitRead
	}
	return n
}

// ---- CSV ----

type csvReader struct {
	r       *csv.Reader
	names   []string
	types   []string
	preRead [][]any
	opts    *ReadOpts
}

func newCSVReader(rd io.Reader, opts *ReadOpts, delim rune) (*csvReader, error) {
	cr := csv.NewReader(rd)
	cr.LazyQuotes = true
	cr.FieldsPerRecord = -1
	cr.Comma = delim
	cr.ReuseRecord = false
	r := &csvReader{r: cr, opts: opts}

	for i := 0; i < opts.InSkip; i++ {
		if _, err := cr.Read(); err != nil {
			if isCSVDelimErr(err) {
				return nil, err
			}
			log.Printf("ERROR: skip error %s", err)
			break
		}
	}

	if opts.InHeader {
		rec, err := cr.Read()
		if err != nil {
			if isCSVDelimErr(err) {
				return nil, err
			}
			if !errors.Is(err, io.EOF) {
				return nil, err
			}
			return nil, errNoRows
		}
		r.names = make([]string, len(rec))
		for i, n := range rec {
			if n == "" {
				n = "c" + strconv.Itoa(i+1)
			}
			r.names[i] = n
		}
	}

	limit := preReadLimit(opts)
	maxCols := 0
	var recs [][]string
	for i := 0; i < limit; i++ {
		rec, err := cr.Read()
		if err != nil {
			if isCSVDelimErr(err) {
				return nil, err
			}
			break
		}
		recs = append(recs, rec)
		if len(rec) > maxCols {
			maxCols = len(rec)
		}
	}
	if !opts.InHeader {
		if maxCols == 0 {
			return nil, errNoRows
		}
		r.names = make([]string, maxCols)
		for i := range r.names {
			r.names[i] = "c" + strconv.Itoa(i+1)
		}
	}
	r.types = textTypes(len(r.names))
	for _, rec := range recs {
		r.preRead = append(r.preRead, r.toRow(rec, nil))
	}
	return r, nil
}

func isCSVDelimErr(err error) bool {
	return err != nil && strings.Contains(err.Error(), "invalid field or comment delimiter")
}

func (r *csvReader) toRow(rec []string, row []any) []any {
	n := len(r.names)
	if cap(row) < n {
		row = make([]any, n)
	}
	row = row[:n]
	for i := 0; i < n; i++ {
		if i < len(rec) {
			row[i] = nullConv(r.opts, rec[i])
		} else {
			row[i] = nil
		}
	}
	return row
}

func (r *csvReader) Names() ([]string, error) { return r.names, nil }
func (r *csvReader) Types() ([]string, error) { return r.types, nil }
func (r *csvReader) PreReadRow() [][]any      { return r.preRead }
func (r *csvReader) ReadRow(row []any) ([]any, error) {
	rec, err := r.r.Read()
	if err != nil {
		return nil, err
	}
	return r.toRow(rec, row), nil
}

// ---- line reading helper ----

type lineReader struct {
	r *bufio.Reader
}

func newLineReader(r io.Reader) *lineReader {
	return &lineReader{r: bufio.NewReaderSize(r, 64*1024)}
}

// readLine returns a line without the trailing newline (and CR).
func (l *lineReader) readLine() (string, error) {
	line, err := l.r.ReadString('\n')
	if err != nil {
		if err == io.EOF && len(line) > 0 {
			return strings.TrimSuffix(line, "\r"), nil
		}
		return "", err
	}
	line = strings.TrimSuffix(line, "\n")
	line = strings.TrimSuffix(line, "\r")
	return line, nil
}

// ---- LTSV ----

type ltsvReader struct {
	lr      *lineReader
	names   []string
	types   []string
	preRead [][]any
	opts    *ReadOpts
}

func newLTSVReader(rd io.Reader, opts *ReadOpts) (*ltsvReader, error) {
	r := &ltsvReader{lr: newLineReader(rd), opts: opts}
	seen := map[string]bool{}
	var recs []*orderedRec
	limit := preReadLimit(opts)
	for i := 0; i < limit; i++ {
		rec, err := r.readRecord()
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}
		for _, k := range rec.keys {
			if !seen[k] {
				seen[k] = true
				r.names = append(r.names, k)
			}
		}
		recs = append(recs, rec)
	}
	if len(r.names) == 0 {
		return nil, errInvalidNames
	}
	r.types = textTypes(len(r.names))
	for _, rec := range recs {
		r.preRead = append(r.preRead, r.toRow(rec, nil))
	}
	return r, nil
}

type orderedRec struct {
	keys []string
	vals map[string]string
}

func (r *ltsvReader) readRecord() (*orderedRec, error) {
	var line string
	var err error
	for {
		line, err = r.lr.readLine()
		if err != nil {
			return nil, err
		}
		if strings.TrimSpace(line) != "" {
			break
		}
	}
	rec := &orderedRec{vals: map[string]string{}}
	for _, col := range strings.Split(line, "\t") {
		kv := strings.SplitN(col, ":", 2)
		if len(kv) != 2 {
			return nil, errInvalidColumn
		}
		if _, ok := rec.vals[kv[0]]; !ok {
			rec.keys = append(rec.keys, kv[0])
		}
		rec.vals[kv[0]] = kv[1]
	}
	return rec, nil
}

func (r *ltsvReader) toRow(rec *orderedRec, row []any) []any {
	n := len(r.names)
	if cap(row) < n {
		row = make([]any, n)
	}
	row = row[:n]
	for i, name := range r.names {
		row[i] = nullConv(r.opts, rec.vals[name])
	}
	return row
}

func (r *ltsvReader) Names() ([]string, error) { return r.names, nil }
func (r *ltsvReader) Types() ([]string, error) { return r.types, nil }
func (r *ltsvReader) PreReadRow() [][]any      { return r.preRead }
func (r *ltsvReader) ReadRow(row []any) ([]any, error) {
	rec, err := r.readRecord()
	if err != nil {
		return nil, err
	}
	return r.toRow(rec, row), nil
}

// ---- TEXT ----

type textReader struct {
	lr      *lineReader
	preRead [][]any
}

func newTextReader(rd io.Reader, opts *ReadOpts) (*textReader, error) {
	r := &textReader{lr: newLineReader(rd)}
	limit := preReadLimit(opts)
	for i := 0; i < limit; i++ {
		line, err := r.lr.readLine()
		if err != nil {
			break
		}
		r.preRead = append(r.preRead, []any{line})
	}
	return r, nil
}

func (r *textReader) Names() ([]string, error) { return []string{"text"}, nil }
func (r *textReader) Types() ([]string, error) { return []string{"text"}, nil }
func (r *textReader) PreReadRow() [][]any      { return r.preRead }
func (r *textReader) ReadRow(row []any) ([]any, error) {
	line, err := r.lr.readLine()
	if err != nil {
		return nil, err
	}
	return []any{line}, nil
}

// ---- TBLN ----

type tblnReader struct {
	lr      *lineReader
	names   []string
	types   []string
	preRead [][]any
	opts    *ReadOpts
}

func tblnSplitRow(body string) []string {
	if len(body) >= 2 && body[:2] == "| " {
		body = body[2:]
	}
	if len(body) >= 2 && body[len(body)-2:] == " |" {
		body = body[:len(body)-2]
	}
	rec := strings.Split(body, " | ")
	for i, c := range rec {
		if strings.Contains(c, "|") {
			rec[i] = strings.ReplaceAll(c, "||", "|")
		}
	}
	return rec
}

func newTBLNReader(rd io.Reader, opts *ReadOpts) (*tblnReader, error) {
	r := &tblnReader{lr: newLineReader(rd), opts: opts}
	limit := preReadLimit(opts)
	var recs [][]string
	for len(recs) < limit {
		rec, err := r.readRecord(true)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}
		if len(r.names) == 0 {
			r.names = make([]string, len(rec))
			for i := range rec {
				r.names[i] = "c" + strconv.Itoa(i+1)
			}
		}
		if len(rec) != len(r.names) {
			return nil, fmt.Errorf("invalid column num (%d!=%d) %v", len(r.names), len(rec), rec)
		}
		recs = append(recs, rec)
	}
	if len(r.names) == 0 {
		return nil, errInvalidNames
	}
	if len(r.types) == 0 {
		if len(recs) == 0 {
			return nil, errInvalidTypes
		}
		r.types = textTypes(len(r.names))
	}
	for _, rec := range recs {
		r.preRead = append(r.preRead, r.toRow(rec, nil))
	}
	return r, nil
}

func (r *tblnReader) readRecord(header bool) ([]string, error) {
	for {
		line, err := r.lr.readLine()
		if err != nil {
			return nil, err
		}
		if strings.HasPrefix(line, ";") {
			if header {
				r.parseExtra(line)
			}
			continue
		}
		if strings.HasPrefix(line, "|") {
			return tblnSplitRow(line), nil
		}
	}
}

func (r *tblnReader) parseExtra(line string) {
	body := strings.TrimPrefix(line, ";")
	body = strings.TrimLeft(body, " ")
	i := strings.Index(body, ":")
	if i < 0 {
		return
	}
	key := body[:i]
	val := strings.TrimLeft(body[i+1:], " ")
	switch key {
	case "name":
		r.names = tblnSplitRow(val)
	case "type":
		r.types = tblnSplitRow(val)
	}
}

func (r *tblnReader) toRow(rec []string, row []any) []any {
	n := len(r.names)
	if cap(row) < n {
		row = make([]any, n)
	}
	row = row[:n]
	for i := 0; i < n; i++ {
		if i < len(rec) && rec[i] != "" {
			row[i] = nullConv(r.opts, rec[i])
		} else {
			row[i] = nil
		}
