package main

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"io"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

// WriteOpts holds output options.
type WriteOpts struct {
	OutFormat    Format
	OutDelimiter string
	OutQuote     string
	OutAllQuotes bool
	OutUseCRLF   bool
	OutHeader    bool
	OutNoWrap    bool
	OutNeedNULL  bool
	OutNULL      string
}

// Writer is the interface of output writers.
type Writer interface {
	PreWrite(columns []string, types []string) error
	WriteRow(values []any, columns []string) error
	PostWrite() error
}

func newWriter(w io.Writer, o *WriteOpts) Writer {
	switch o.OutFormat {
	case fmtLTSV:
		return &ltsvWriter{w: w, o: o}
	case fmtJSON:
		return &jsonWriter{w: w, o: o}
	case fmtJSONL:
		return &jsonlWriter{w: w, o: o}
	case fmtRAW:
		return newRawWriter(w, o)
	case fmtMD:
		return newTableWriter(w, o, true)
	case fmtAT:
		return newTableWriter(w, o, false)
	case fmtVF:
		return &vfWriter{w: w, o: o}
	case fmtTBLN:
		return &tblnWriter{w: w, o: o}
	case fmtYAML:
		return &yamlWriter{w: w, o: o}
	}
	return newCSVWriter(w, o)
}

// valString converts a value to its text representation.
func valString(v any) string {
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return t
	case []byte:
		if utf8.Valid(t) {
			return string(t)
		}
		return `\x` + hex.EncodeToString(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case int:
		return strconv.Itoa(t)
	case float64:
		return strconv.FormatFloat(t, 'g', -1, 64)
	case bool:
		if t {
			return "true"
		}
		return "false"
	case time.Time:
		return t.Format(time.RFC3339)
	}
	return toString(v)
}

func toString(v any) string {
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return t
	case []byte:
		return string(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case int:
		return strconv.Itoa(t)
	case float64:
		return strconv.FormatFloat(t, 'g', -1, 64)
	case bool:
		if t {
			return "true"
		}
		return "false"
	case time.Time:
		return t.Format(time.RFC3339)
	}
	return ""
}

func (o *WriteOpts) nullString(v any) string {
	if v == nil {
		if o.OutNeedNULL {
			return o.OutNULL
		}
		return ""
	}
	return valString(v)
}

// ---- CSV ----

type csvWriter struct {
	w        io.Writer
	o        *WriteOpts
	comma    rune
	quote    rune
	allQuote bool
	crlf     bool
	buf      bytes.Buffer
}

func outDelimiterRune(s string) rune {
	if s == "" {
		return 0
	}
	u, err := strconv.Unquote(`'` + s + `'`)
	if err != nil {
		return ','
	}
	return []rune(u)[0]
}

func newCSVWriter(w io.Writer, o *WriteOpts) *csvWriter {
	c := &csvWriter{w: w, o: o, allQuote: o.OutAllQuotes, crlf: o.OutUseCRLF}
	c.comma = outDelimiterRune(o.OutDelimiter)
	if o.OutQuote == "" {
		c.quote = 0
	} else {
		c.quote = []rune(o.OutQuote)[0]
	}
	return c
}

func (c *csvWriter) fieldNeedsQuotes(field string) bool {
	if field == "" {
		return false
	}
	if field == `\.` {
		return true
	}
	if c.comma < utf8.RuneSelf {
		for i := 0; i < len(field); i++ {
			ch := field[i]
			if ch == '\n' || ch == '\r' || rune(ch) == c.quote || rune(ch) == c.comma {
				return true
			}
		}
		if c.quote >= utf8.RuneSelf && strings.ContainsRune(field, c.quote) {
			return true
		}
	} else {
		if strings.ContainsRune(field, c.comma) || strings.ContainsRune(field, c.quote) || strings.ContainsAny(field, "\r\n") {
			return true
		}
	}
	r1, _ := utf8.DecodeRuneInString(field)
	return unicode.IsSpace(r1)
}

func (c *csvWriter) writeField(field string, quoted bool) {
	if !quoted {
		c.buf.WriteString(field)
		return
	}
	c.buf.WriteRune(c.quote)
	for _, r := range field {
		switch r {
		case c.quote:
			c.buf.WriteRune(c.quote)
			c.buf.WriteRune(c.quote)
		case '\r':
			if !c.crlf {
				c.buf.WriteByte('\r')
			}
		case '\n':
			if c.crlf {
				c.buf.WriteString("\r\n")
			} else {
				c.buf.WriteByte('\n')
			}
		default:
			c.buf.WriteRune(r)
		}
	}
	c.buf.WriteRune(c.quote)
}

func (c *csvWriter) endLine() {
	if c.crlf {
		c.buf.WriteString("\r\n")
	} else {
		c.buf.WriteByte('\n')
	}
}

func (c *csvWriter) PreWrite(columns []string, types []string) error {
	if !c.o.OutHeader {
		return nil
	}
	for i, col := range columns {
		if i > 0 {
			c.buf.WriteRune(c.comma)
		}
		c.writeField(col, c.allQuote || c.fieldNeedsQuotes(col))
	}
	c.endLine()
	return c.flush()
}

func (c *csvWriter) flush() error {
	_, err := c.w.Write(c.buf.Bytes())
	c.buf.Reset()
	return err
}

func (c *csvWriter) WriteRow(values []any, columns []string) error {
	for i, v := range values {
		if i > 0 {
			c.buf.WriteRune(c.comma)
		}
		if v == nil {
			c.writeField(c.o.nullString(nil), false)
			continue
		}
		s := valString(v)
		c.writeField(s, c.allQuote || c.fieldNeedsQuotes(s))
	}
	c.endLine()
	return c.flush()
}

func (c *csvWriter) PostWrite() error { return nil }

// ---- RAW ----

type rawWriter struct {
	w     io.Writer
	o     *WriteOpts
	delim string
}

func newRawWriter(w io.Writer, o *WriteOpts) *rawWriter {
	d, err := strconv.Unquote(`"` + o.OutDelimiter + `"`)
	if err != nil {
		d = ""
	}
	return &rawWriter{w: w, o: o, delim: d}
}

func (r *rawWriter) PreWrite(columns []string, types []string) error {
	if !r.o.OutHeader {
		return nil
	}
	nl := "\n"
	if r.o.OutUseCRLF {
		nl = "\r\n"
	}
	_, err := io.WriteString(r.w, strings.Join(columns, r.delim)+nl)
	return err
}

func (r *rawWriter) WriteRow(values []any, columns []string) error {
	var sb strings.Builder
	for i, v := range values {
		if i > 0 {
			sb.WriteString(r.delim)
		}
		sb.WriteString(r.o.nullString(v))
	}
	sb.WriteByte('\n')
	_, err := io.WriteString(r.w, sb.String())
	return err
}

func (r *rawWriter) PostWrite() error { return nil }

// ---- LTSV ----

type ltsvWriter struct {
	w io.Writer
	o *WriteOpts
}

func (l *ltsvWriter) PreWrite(columns []string, types []string) error { return nil }
func (l *ltsvWriter) WriteRow(values []any, columns []string) error {
