package main

import (
	"io"
	"math"
	"regexp"
	"strings"
)

var ansiRe = regexp.MustCompile("\033\\[(?:[0-9]{1,3}(?:;[0-9]{1,3})*)?[m|K]")
var decimalRe = regexp.MustCompile(`^-?(?:\d{1,3}(?:,\d{3})*|\d+)(\.\d+)?$`)

func displayWidth(s string) int {
	if strings.Contains(s, "\033") {
		s = ansiRe.ReplaceAllLiteralString(s, "")
	}
	return stringWidth(s)
}

// wrapString wraps s into lines of length lim with minimal raggedness.
func wrapString(s string, lim int) []string {
	words := strings.Split(strings.ReplaceAll(s, "\n", " "), " ")
	for _, v := range words {
		if w := displayWidth(v); w > lim {
			lim = w
		}
	}
	var lines []string
	for _, line := range wrapWords(words, 1, lim, 100000) {
		lines = append(lines, strings.Join(line, " "))
	}
	return lines
}

func wrapWords(words []string, spc, lim, pen int) [][]string {
	n := len(words)
	length := make([][]int, n)
	for i := 0; i < n; i++ {
		length[i] = make([]int, n)
		length[i][i] = stringWidth(words[i])
		for j := i + 1; j < n; j++ {
			length[i][j] = length[i][j-1] + spc + stringWidth(words[j])
		}
	}
	nbrk := make([]int, n)
	cost := make([]int, n)
	for i := range cost {
		cost[i] = math.MaxInt32
	}
	for i := n - 1; i >= 0; i-- {
		if length[i][n-1] <= lim {
			cost[i] = 0
			nbrk[i] = n
		} else {
			for j := i + 1; j < n; j++ {
				d := lim - length[i][j-1]
				c := d*d + cost[j]
				if length[i][j-1] > lim {
					c += pen
				}
				if c < cost[i] {
					cost[i] = c
					nbrk[i] = j
				}
			}
		}
	}
	var lines [][]string
	i := 0
	for i < n {
		lines = append(lines, words[i:nbrk[i]])
		i = nbrk[i]
	}
	return lines
}

type textTable struct {
	out      io.Writer
	autoWrap bool
	mW       int
	cs       map[int]int
	rs       map[int]int
	headers  [][]string
	lines    [][][]string
	markdown bool
	sb       strings.Builder
}

const headerRowIdx = -1

func newTextTable(out io.Writer, autoWrap bool, markdown bool) *textTable {
	return &textTable{out: out, autoWrap: autoWrap, mW: 30, cs: map[int]int{}, rs: map[int]int{}, markdown: markdown}
}

func (t *textTable) parseDimension(str string, colKey, rowKey int) []string {
	raw := strings.Split(str, "\n")
	maxWidth := 0
	for _, line := range raw {
		if w := displayWidth(line); w > maxWidth {
			maxWidth = w
		}
	}
	if t.autoWrap {
		if maxWidth > t.mW {
			maxWidth = t.mW
		}
		newMaxWidth := maxWidth
		newRaw := make([]string, 0, len(raw))
		raw = []string{strings.Join(raw, " ")}
		for i, para := range raw {
			paraLines := wrapString(para, maxWidth)
			for _, line := range paraLines {
				if w := displayWidth(line); w > newMaxWidth {
					newMaxWidth = w
				}
			}
			if i > 0 {
				newRaw = append(newRaw, " ")
			}
			newRaw = append(newRaw, paraLines...)
		}
		raw = newRaw
		maxWidth = newMaxWidth
	}
	if v, ok := t.cs[colKey]; !ok || v < maxWidth || v == 0 {
		t.cs[colKey] = maxWidth
	}
	h := len(raw)
	if v, ok := t.rs[rowKey]; !ok || v < h || v == 0 {
		t.rs[rowKey] = h
	}
	return raw
}

func (t *textTable) SetHeader(keys []string) {
	for i, v := range keys {
		t.headers = append(t.headers, t.parseDimension(v, i, headerRowIdx))
	}
}

func (t *textTable) Append(row []string) {
	n := len(t.lines)
	line := [][]string{}
	for i, v := range row {
		line = append(line, t.parseDimension(v, i, n))
	}
	t.lines = append(t.lines, line)
}

func padCenter(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		gapLeft := gap / 2
		gapRight := gap - gapLeft
		return strings.Repeat(" ", gapLeft) + s + strings.Repeat(" ", gapRight)
	}
	return s
}

func padRight(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return s + strings.Repeat(" ", gap)
	}
	return s
}

func padLeft(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return strings.Repeat(" ", gap) + s
	}
	return s
}

func (t *textTable) printLine() {
	center := "+"
	if t.markdown {
		center = "|"
	}
	t.sb.WriteString(center)
	for i := 0; i < len(t.cs); i++ {
		v := t.cs[i]
		t.sb.WriteString("-")
		t.sb.WriteString(strings.Repeat("-", v))
		t.sb.WriteString("-")
		t.sb.WriteString(center)
	}
	t.sb.WriteString("\n")
}

func (t *textTable) printHeading() {
	if len(t.headers) < 1 {
		return
	}
	end := len(t.cs) - 1
	max := t.rs[headerRowIdx]
	for x := 0; x < max; x++ {
		t.sb.WriteString("|")
		for y := 0; y <= end; y++ {
			v := t.cs[y]
			h := ""
			if y < len(t.headers) && x < len(t.headers[y]) {
				h = t.headers[y][x]
			}
			t.sb.WriteString(" ")
			t.sb.WriteString(padCenter(h, v))
			t.sb.WriteString(" |")
		}
		t.sb.WriteString("\n")
	}
	t.printLine()
}

func (t *textTable) printRow(columns [][]string, rowIdx int) {
	max := t.rs[rowIdx]
	total := len(columns)
	for i, line := range columns {
		pad := max - len(line)
		for n := 0; n < pad; n++ {
			columns[i] = append(columns[i], "  ")
		}
	}
	for x := 0; x < max; x++ {
		for y := 0; y < total; y++ {
			t.sb.WriteString("| ")
			str := columns[y][x]
			trimmed := strings.TrimSpace(str)
			if decimalRe.MatchString(trimmed) {
				t.sb.WriteString(padLeft(str, t.cs[y]))
			} else {
				t.sb.WriteString(padRight(str, t.cs[y]))
			}
			t.sb.WriteString(" ")
		}
		t.sb.WriteString("|")
		t.sb.WriteString("\n")
	}
}

func (t *textTable) Render() error {
	if !t.markdown {
		t.printLine()
	}
	t.printHeading()
	for i, line := range t.lines {
		t.printRow(line, i)
	}
	if !t.markdown {
		t.printLine()
	}
	_, err := io.WriteString(t.out, t.sb.String())
	t.sb.Reset()
	return err
}

// ---- writer for at / md ----

type tableWriter struct {
	w        io.Writer
	o        *WriteOpts
	markdown bool
	table    *textTable
}

func newTableWriter(w io.Writer, o *WriteOpts, markdown bool) *tableWriter {
	return &tableWriter{w: w, o: o, markdown: markdown}
}

func (t *tableWriter) PreWrite(columns []string, types []string) error {
	t.table = newTextTable(t.w, !t.o.OutNoWrap, t.markdown)
	t.table.SetHeader(columns)
	return nil
}

func (t *tableWriter) WriteRow(values []any, columns []string) error {
	row := make([]string, len(values))
	for i, v := range values {
		s := t.o.nullString(v)
		if t.markdown {
			s = strings.ReplaceAll(s, "|", "\\|")
		}
		row[i] = s
	}
	t.table.Append(row)
	return nil
}

func (t *tableWriter) PostWrite() error {
	return t.table.Render()
}
EOF
