// importTable imports the table referenced by raw token. Returns the quoted table
// name used in the query, or "" if the file could not be opened.
func (im *importer) importTable(raw string) (string, error) {
	filePart := raw
	jq := im.opts.InJQuery
	if i := strings.Index(raw, "::"); i >= 0 {
		filePart = raw[:i]
		jq = trimJQQuote(raw[i+2:])
	}
