		debugf("Guess file type as %s: [%s]", format, filePart)
	}
	rd, closer, err := openInput(fileName)
	if err != nil {
		debugln(err)
		return "", nil
	}
	defer closer.Close()

	tableName := raw
	if jq != "" {
		im.jqCounter++
		tableName = filePart + "::jq" + strconv.Itoa(im.jqCounter)
	}
	reader, err := newReader(format, rd, im.opts, jq)
	if err != nil {
		return "", err
