			if err != nil {
				return err
			}
			if !has {
				return nil
			}
		}
	}
	columns := make([]string, n)
	types := make([]string, n)
	for i := 0; i < n; i++ {
		columns[i] = st.ColumnName(i)
		types[i] = st.DeclType(i)
	}
