package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"sort"
	"strconv"
	"unicode/utf16"
	"unicode/utf8"
)

// omap is an ordered map (object) preserving the key order of the source.
type omap struct {
	keys []string
	vals map[string]any
}

func newOmap() *omap { return &omap{vals: map[string]any{}} }

func (m *omap) Set(k string, v any) {
	if _, ok := m.vals[k]; !ok {
		m.keys = append(m.keys, k)
	}
	m.vals[k] = v
}

func (m *omap) Get(k string) (any, bool) {
	v, ok := m.vals[k]
	return v, ok
}

func (m *omap) Len() int { return len(m.keys) }

func (m *omap) sortedKeys() []string {
	ks := make([]string, len(m.keys))
	copy(ks, m.keys)
	sort.Strings(ks)
	return ks
}

// ---- parser for valid JSON text ----

type jsonParser struct {
	data []byte
	pos  int
}

var errJSONSyntax = errors.New("invalid JSON")

func parseJSONValue(data []byte) (any, error) {
	p := &jsonParser{data: data}
	p.skipWS()
	v, err := p.value()
	if err != nil {
		return nil, err
	}
	return v, nil
}

func (p *jsonParser) skipWS() {
	for p.pos < len(p.data) {
		switch p.data[p.pos] {
		case ' ', '\t', '\n', '\r':
			p.pos++
		default:
			return
		}
	}
}

func (p *jsonParser) value() (any, error) {
	if p.pos >= len(p.data) {
		return nil, errJSONSyntax
	}
	switch c := p.data[p.pos]; {
	case c == '{':
		p.pos++
		m := newOmap()
		p.skipWS()
		if p.pos < len(p.data) && p.data[p.pos] == '}' {
			p.pos++
			return m, nil
		}
		for {
			p.skipWS()
			k, err := p.str()
			if err != nil {
				return nil, err
			}
			p.skipWS()
			if p.pos >= len(p.data) || p.data[p.pos] != ':' {
				return nil, errJSONSyntax
			}
			p.pos++
			p.skipWS()
			v, err := p.value()
			if err != nil {
				return nil, err
			}
			m.Set(k, v)
			p.skipWS()
			if p.pos >= len(p.data) {
				return nil, errJSONSyntax
			}
			if p.data[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.data[p.pos] == '}' {
				p.pos++
				return m, nil
			}
			return nil, errJSONSyntax
		}
	case c == '[':
		p.pos++
		arr := []any{}
		p.skipWS()
		if p.pos < len(p.data) && p.data[p.pos] == ']' {
			p.pos++
			return arr, nil
		}
		for {
			p.skipWS()
			v, err := p.value()
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
			p.skipWS()
			if p.pos >= len(p.data) {
				return nil, errJSONSyntax
			}
			if p.data[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.data[p.pos] == ']' {
				p.pos++
				return arr, nil
			}
			return nil, errJSONSyntax
		}
	case c == '"':
		return p.str()
	case c == 't':
		if bytes.HasPrefix(p.data[p.pos:], []byte("true")) {
			p.pos += 4
			return true, nil
		}
	case c == 'f':
