{"command":"cd /workspace && cat > reader_json.go <<'EOF'
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strconv"
)

// docSource yields top-level documents.
type docSource interface {
	Next() (any, error)
	More() bool
}

type jsonSource struct {
	dec *json.Decoder
}

func (s *jsonSource) Next() (any, error) {
	var raw json.RawMessage
	if err := s.dec.Decode(&raw); err != nil {
		return nil, err
	}
	return parseJSONValue(raw)
}

func (s *jsonSource) More() bool {
	return s.dec.More()
}

type rowMap struct {
	keys []string
	vals map[string]any
}

type docReader struct {
	src      docSource
	conv     func(any) any
	opts     *ReadOpts
	query    *jqProgram
	names    []string
	nameSet  map[string]bool
	preRead  [][]any
	pending  []any
	invalidE error
}

func jsonConv(v any) any {
	switch t := v.(type) {
	case nil:
		return nil
	case string:
		return t
	case json.Number:
		return string(t)
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int:
		return strconv.Itoa(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case float64:
		return strconv.FormatFloat(t, 'g', -1, 64)
	case []any, *omap:
		return marshalJSON(t)
	}
	return marshalJSON(v)
}

func newJSONReader(r io.Reader, opts *ReadOpts, jq string) (Reader, error) {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	return newDocReader(&jsonSource{dec: dec}, opts, jq, jsonConv, true)
}

func newDocReader(src docSource, opts *ReadOpts, jq string, conv func(any) any, isJSON bool) (*docReader, error) {
	d := &docReader{src: src, conv: conv, opts: opts, nameSet: map[string]bool{}}
	if jq != "" {
		q, err := parseJQ(jq)
		if err != nil {
			return nil, fmt.Errorf("%s gojq:(%s)", err, jq)
		}
		d.query = q
	}
	var rows []*rowMap
	inArray := false
	for i := 0; i < opts.InPreRead; i++ {
		if inArray {
			break
		}
		v, err := src.Next()
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			if isJSON {
				return nil, fmt.Errorf("invalid JSON: %w", err)
			}
			return nil, err
		}
		if d.query != nil {
			results, err := d.query.run(v)
			if err != nil {
				return nil, fmt.Errorf("%s gojq:(%s)", err, jq)
			}
			for _, res := range results {
				if arr, ok := res.([]any); ok {
					rows = rows[:0]
					for _, e := range arr {
						rows = append(rows, d.asRow(e))
					}
					continue
				}
				rows = append(rows, d.asRow(res))
			}
			continue
		}
		if arr, ok := v.([]any); ok && !src.More() {
			rows = rows[:0]
			for _, e := range arr {
				rows = append(rows, d.asRow(e))
			}
			inArray = true
			continue
		}
		rows = append(rows, d.asRow(v))
	}
	if len(d.names) == 0 {
		return nil, errInvalidNames
	}
	for _, rm := range rows {
		row := make([]any, len(d.names))
		for i, n := range d.names {
			if v, ok := rm.vals[n]; ok {
				row[i] = nullConv(opts, v)
			}
		}
		d.preRead = append(d.preRead, row)
	}
	return d, nil
}

func (d *docReader) addName(n string) {
	if !d.nameSet[n] {
		d.nameSet[n] = true
		d.names = append(d.names, n)
	}
}

func (d *docReader) asRow(v any) *rowMap {
	rm := &rowMap{vals: map[string]any{}}
	if m, ok := v.(*omap); ok {
		for _, k := range m.keys {
			d.addName(k)
			rm.keys = append(rm.keys, k)
			rm.vals[k] = d.conv(m.vals[k])
		}
		return rm
	}
	d.addName("c1")
	rm.keys = append(rm.keys, "c1")
	rm.vals["c1"] = d.conv(v)
	return rm
}

func (d *docReader) Names() ([]string, error) { return d.names, nil }
func (d *docReader) Types() ([]string, error) { return textTypes(len(d.names)), nil }
func (d *docReader) PreReadRow() [][]any      { return d.preRead }

func (d *docReader) toPositional(v any) []any {
	row := make([]any, len(d.names))
	if m, ok := v.(*omap); ok {
		for i, n := range d.names {
			if val, ok := m.vals[n]; ok {
				row[i] = nullConv(d.opts, d.conv(val))
			}
		}
		return row
	}
	if len(row) > 0 {
		row[0] = nullConv(d.opts, d.conv(v))
	}
	return row
}

func (d *docReader) ReadRow(_ []any) ([]any, error) {
	for {
		if len(d.pending) > 0 {
			v := d.pending[0]
			d.pending = d.pending[1:]
			return d.toPositional(v), nil
		}
		v, err := d.src.Next()
		if err != nil {
			return nil, err
		}
		if d.query != nil {
			results, err := d.query.run(v)
			if err != nil {
				return nil, err
			}
			for _, res := range results {
				if arr, ok := res.([]any); ok {
					d.pending = append(d.pending, arr...)
					continue
				}
				d.pending = append(d.pending, res)
			}
			continue
		}
		return d.toPositional(v), nil
	}
}
EOF
echo ok"}

