func (d *docReader) ReadRow(_ []any) ([]any, error) {
	for {
		if len(d.pending) > 0 {
			v := d.pending[0]
			d.pending = d.pending[1:]
			return d.toPositional(v), nil
		}
		v, err := d.src.Next()
		if err != nil {
			return nil, err
		}
		if d.query != nil {
			results, err := d.query.run(v)
			if err != nil {
				return nil, err
			}
