cd /workspace && cat > jq.go <<'EOF'
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// A small jq implementation covering the commonly used subset.

type jqProgram struct {
	root jqNode
}

type jqEnv struct {
	vars map[string]any
	parent *jqEnv
}

func (e *jqEnv) lookup(name string) (any, bool) {
	for x := e; x != nil; x = x.parent {
		if v, ok := x.vars[name]; ok {
			return v, true
		}
	}
	return nil, false
}

type jqNode interface {
	eval(env *jqEnv, in any) ([]any, error)
}

var errJQEmpty = errors.New("empty")

func parseJQ(src string) (*jqProgram, error) {
	p := &jqParser{}
	if err := p.tokenize(src); err != nil {
		return nil, err
	}
	if len(p.toks) == 0 {
		return &jqProgram{root: &jqIdentity{}}, nil
	}
	n, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.toks) {
		return nil, fmt.Errorf("unexpected token %q", p.toks[p.pos].s)
	}
	return &jqProgram{root: n}, nil
}

func (q *jqProgram) run(in any) ([]any, error) {
	return q.root.eval(&jqEnv{vars: map[string]any{}}, in)
}

// ---- tokenizer ----

type jqTok struct {
	kind string // "num","str","ident","field","var","op","fmt"
	s    string
}

type jqParser struct {
	toks []jqTok
	pos  int
}

func (p *jqParser) tokenize(src string) error {
	i := 0
	for i < len(src) {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '#':
			for i < len(src) && src[i] != '\n' {
				i++
			}
		case c == '"':
			j := i + 1
			var sb strings.Builder
			for j < len(src) && src[j] != '"' {
				if src[j] == '\\' && j+1 < len(src) {
					j++
					switch src[j] {
					case 'n':
						sb.WriteByte('\n')
					case 't':
						sb.WriteByte('\t')
					case 'r':
						sb.WriteByte('\r')
					case '"':
						sb.WriteByte('"')
					case '\\':
						sb.WriteByte('\\')
					case '/':
						sb.WriteByte('/')
					case 'u':
						if j+4 < len(src) {
							v, err := strconv.ParseUint(src[j+1:j+5], 16, 32)
							if err == nil {
								sb.WriteRune(rune(v))
								j += 4
							}
						}
					default:
						sb.WriteByte('\\')
						sb.WriteByte(src[j])
					}
					j++
					continue
				}
				sb.WriteByte(src[j])
				j++
			}
			if j >= len(src) {
				return errors.New("unexpected EOF")
			}
			p.toks = append(p.toks, jqTok{"str", sb.String()})
			i = j + 1
		case c >= '0' && c <= '9':
			j := i
			for j < len(src) && ((src[j] >= '0' && src[j] <= '9') || src[j] == '.' || src[j] == 'e' || src[j] == 'E' ||
				((src[j] == '+' || src[j] == '-') && j > i && (src[j-1] == 'e' || src[j-1] == 'E'))) {
				j++
			}
			p.toks = append(p.toks, jqTok{"num", src[i:j]})
			i = j
		case c == '.':
			if i+1 < len(src) && src[i+1] == '.' {
				p.toks = append(p.toks, jqTok{"op", ".."})
				i += 2
				continue
			}
			j := i + 1
			for j < len(src) && (isIdentChar(src[j])) {
				j++
			}
			if j > i+1 {
				p.toks = append(p.toks, jqTok{"field", src[i+1 : j]})
			} else {
				p.toks = append(p.toks, jqTok{"op", "."})
			}
			i = j
		case c == '$':
			j := i + 1
			for j < len(src) && isIdentChar(src[j]) {
				j++
			}
			p.toks = append(p.toks, jqTok{"var", src[i+1 : j]})
			i = j
		case c == '@':
			j := i + 1
			for j < len(src) && isIdentChar(src[j]) {
				j++
			}
			p.toks = append(p.toks, jqTok{"fmt", src[i+1 : j]})
			i = j
		case isIdentStart(c):
			j := i
			for j < len(src) && (isIdentChar(src[j]) || (src[j] == ':' && j+1 < len(src) && src[j+1] == ':')) {
				if src[j] == ':' {
					j += 2
					continue
				}
				j++
			}
			p.toks = append(p.toks, jqTok{"ident", src[i:j]})
			i = j
		default:
			two := ""
			if i+1 < len(src) {
				two = src[i : i+2]
			}
			switch two {
			case "==", "!=", "<=", ">=", "//", "|=", "+=", "-=", "*=", "/=", "%=", "?/":
				if two == "//" && i+2 < len(src) && src[i+2] == '=' {
					p.toks = append(p.toks, jqTok{"op", "//="})
					i += 3
					continue
				}
				p.toks = append(p.toks, jqTok{"op", two})
				i += 2
				continue
			}
			switch c {
			case '|', ',', '(', ')', '[', ']', '{', '}', ':', ';', '+', '-', '*', '/', '%', '<', '>', '?', '=':
				p.toks = append(p.toks, jqTok{"op", string(c)})
				i++
			default:
				return fmt.Errorf("unexpected token %q", string(c))
			}
		}
	}
	return nil
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func (p *jqParser) peek() *jqTok {
	if p.pos < len(p.toks) {
		return &p.toks[p.pos]
	}
	return nil
}

func (p *jqParser) isOp(s string) bool {
	t := p.peek()
	return t != nil && t.kind == "op" && t.s == s
}

func (p *jqParser) isIdent(s string) bool {
	t := p.peek()
	return t != nil && t.kind == "ident" && t.s == s
}

func (p *jqParser) expectOp(s string) error {
	if !p.isOp(s) {
		if p.peek() == nil {
			return errors.New("unexpected EOF")
		}
		return fmt.Errorf("unexpected token %q", p.peek().s)
	}
	p.pos++
	return nil
}

func (p *jqParser) expectIdent(s string) error {
	if !p.isIdent(s) {
		if p.peek() == nil {
			return errors.New("unexpected EOF")
		}
		return fmt.Errorf("unexpected token %q", p.peek().s)
	}
	p.pos++
	return nil
}

// pipe: comma ('|' pipe)* ; also "term as $x | pipe"; "def"
func (p *jqParser) parsePipe() (jqNode, error) {
	if p.isIdent("def") {
		return p.parseDef()
	}
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	if p.isIdent("as") {
		p.pos++
		t := p.peek()
		if t == nil || t.kind != "var" {
			return nil, errors.New("unexpected EOF")
		}
		p.pos++
		if err := p.expectOp("|"); err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &jqAs{src: left, name: t.s, body: body}, nil
	}
	if p.isOp("|") {
		p.pos++
		right, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &jqPipe{left, right}, nil
	}
	return left, nil
}

func (p *jqParser) parseDef() (jqNode, error) {
	p.pos++
	t := p.peek()
	if t == nil || t.kind != "ident" {
		return nil, errors.New("unexpected EOF")
	}
	name := t.s
	p.pos++
	var params []string
	if p.isOp("(") {
		p.pos++
		for {
			t := p.peek()
			if t == nil {
				return nil, errors.New("unexpected EOF")
			}
			if t.kind == "ident" || t.kind == "var" {
				params = append(params, t.s)
				p.pos++
			}
			if p.isOp(";") {
				p.pos++
				continue
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			break
		}
	}
	if err := p.expectOp(":"); err != nil {
		return nil, err
	}
	body, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp(";"); err != nil {
		return nil, err
	}
	rest, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	return &jqDef{name: name, params: params, body: body, rest: rest}, nil
}

func (p *jqParser) parseComma() (jqNode, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.isOp(",") {
		p.pos++
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &jqComma{left, right}
	}
	return left, nil
}

func (p *jqParser) parseAlt() (jqNode, error) {
	left, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	if p.isOp("//") {
		p.pos++
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		return &jqAlt{left, right}, nil
	}
	return left, nil
}

func (p *jqParser) parseAssign() (jqNode, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	for _, op := range []string{"|=", "=", "+=", "-=", "*=", "/=", "%=", "//="} {
		if p.isOp(op) {
			p.pos++
			right, err := p.parseAlt()
			if err != nil {
				return nil, err
			}
			return &jqAssign{op: op, path: left, val: right}, nil
		}
	}
	return left, nil
}

func (p *jqParser) parseOr() (jqNode, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.isIdent("or") {
		p.pos++
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &jqBool{op: "or", l: left, r: right}
	}
	return left, nil
}

func (p *jqParser) parseAnd() (jqNode, error) {
	left, err := p.parseCmp()
	if err != nil {
		return nil, err
	}
	for p.isIdent("and") {
		p.pos++
		right, err := p.parseCmp()
		if err != nil {
			return nil, err
		}
		left = &jqBool{op: "and", l: left, r: right}
	}
	return left, nil
}

func (p *jqParser) parseCmp() (jqNode, error) {
	left, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	for _, op := range []string{"==", "!=", "<=", ">=", "<", ">"} {
		if p.isOp(op) {
			p.pos++
			right, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			return &jqBin{op: op, l: left, r: right}, nil
		}
	}
	return left, nil
}

func (p *jqParser) parseAdd() (jqNode, error) {
	left, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for p.isOp("+") || p.isOp("-") {
		op := p.peek().s
		p.pos++
		right, err := p.parseMul()
		if err != nil {
			return nil, err
		}
		left = &jqBin{op: op, l: left, r: right}
	}
	return left, nil
}

func (p *jqParser) parseMul() (jqNode, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.isOp("*") || p.isOp("/") || p.isOp("%") {
		op := p.peek().s
		p.pos++
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &jqBin{op: op, l: left, r: right}
	}
	return left, nil
}

func (p *jqParser) parseUnary() (jqNode, error) {
	if p.isOp("-") {
		p.pos++
		n, err := p.parsePostfix()
		if err != nil {
			return nil, err
		}
		return &jqNeg{n}, nil
	}
	return p.parsePostfix()
}

func (p *jqParser) parsePostfix() (jqNode, error) {
	n, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil {
			return n, nil
		}
		switch {
		case t.kind == "field":
			p.pos++
			n = &jqPipe{n, &jqField{name: t.s}}
		case t.kind == "op" && t.s == "." && p.pos+1 < len(p.toks) && p.toks[p.pos+1].kind == "str":
			p.pos += 2
			n = &jqPipe{n, &jqField{name: p.toks[p.pos-1].s}}
		case t.kind == "op" && t.s == "." && p.pos+1 < len(p.toks) && p.toks[p.pos+1].kind == "op" && p.toks[p.pos+1].s == "[":
			p.pos++
		case t.kind == "op" && t.s == "[":
			idx, err := p.parseBracket()
			if err != nil {
				return nil, err
			}
			n = &jqPipe{n, idx}
		case t.kind == "op" && t.s == "?":
			p.pos++
			n = &jqTry{body: n}
		default:
			return n, nil
		}
	}
}

// parseBracket parses [ ... ] suffix.
func (p *jqParser) parseBracket() (jqNode, error) {
	p.pos++ // [
	if p.isOp("]") {
		p.pos++
		return &jqIter{}, nil
	}
	if p.isOp(":") {
		p.pos++
		hi, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if err := p.expectOp("]"); err != nil {
			return nil, err
		}
		return &jqSlice{hi: hi}, nil
	}
	lo, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.isOp(":") {
		p.pos++
		var hi jqNode
		if !p.isOp("]") {
			hi, err = p.parsePipe()
			if err != nil {
				return nil, err
			}
		}
		if err := p.expectOp("]"); err != nil {
			return nil, err
		}
		return &jqSlice{lo: lo, hi: hi}, nil
	}
	if err := p.expectOp("]"); err != nil {
		return nil, err
	}
	return &jqIndex{idx: lo}, nil
}

func (p *jqParser) parseTerm() (jqNode, error) {
	t := p.peek()
	if t == nil {
		return nil, errors.New("unexpected EOF")
	}
	switch t.kind {
	case "num":
		p.pos++
		f, err := strconv.ParseFloat(t.s, 64)
		if err != nil {
			return nil, err
		}
		return &jqLit{v: normNum(f)}, nil
	case "str":
		p.pos++
		return &jqLit{v: t.s}, nil
	case "field":
		p.pos++
		return &jqField{name: t.s}, nil
	case "var":
		p.pos++
		return &jqVar{name: t.s}, nil
	case "fmt":
		p.pos++
		if p.peek() != nil && p.peek().kind == "str" {
			s := p.peek().s
			p.pos++
			return &jqPipe{&jqLit{v: s}, &jqFormat{name: t.s}}, nil
		}
		return &jqFormat{name: t.s}, nil
	case "op":
		switch t.s {
		case ".":
			p.pos++
			if p.peek() != nil && p.peek().kind == "str" {
				s := p.peek().s
				p.pos++
				return &jqField{name: s}, nil
			}
			if p.isOp("[") {
				idx, err := p.parseBracket()
				if err != nil {
					return nil, err
				}
				return idx, nil
			}
			return &jqIdentity{}, nil
		case "..":
			p.pos++
			return &jqCall{name: "recurse"}, nil
		case "(":
			p.pos++
			n, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return n, nil
		case "[":
			p.pos++
			if p.isOp("]") {
				p.pos++
				return &jqArray{}, nil
			}
			n, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("]"); err != nil {
				return nil, err
			}
			return &jqArray{body: n}, nil
		case "{":
			return p.parseObject()
		}
	case "ident":
		switch t.s {
		case "if":
			return p.parseIf()
		case "try":
			p.pos++
			body, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			var catch jqNode
			if p.isIdent("catch") {
				p.pos++
				catch, err = p.parsePostfix()
				if err != nil {
					return nil, err
				}
			}
			return &jqTry{body: body, catch: catch}, nil
		case "reduce":
			return p.parseReduce()
		case "true":
			p.pos++
			return &jqLit{v: true}, nil
		case "false":
			p.pos++
			return &jqLit{v: false}, nil
		case "null":
			p.pos++
			return &jqLit{v: nil}, nil
		case "not":
			p.pos++
			return &jqCall{name: "not"}, nil
		}
		p.pos++
		call := &jqCall{name: t.s}
		if p.isOp("(") {
			p.pos++
			for {
				a, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				call.args = append(call.args, a)
				if p.isOp(";") {
					p.pos++
					continue
				}
				if err := p.expectOp(")"); err != nil {
					return nil, err
				}
				break
			}
		}
		return call, nil
	}
	return nil, fmt.Errorf("unexpected token %q", t.s)
}

func (p *jqParser) parseIf() (jqNode, error) {
	p.pos++
	cond, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectIdent("then"); err != nil {
		return nil, err
	}
	then, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	n := &jqIf{cond: cond, then: then}
	if p.isIdent("elif") {
		p.toks[p.pos].s = "if"
		els, err := p.parseIf()
		if err != nil {
			return nil, err
		}
		n.els = els
		return n, nil
	}
	if p.isIdent("else") {
		p.pos++
		els, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		n.els = els
	}
	if err := p.expectIdent("end"); err != nil {
		return nil, err
	}
	return n, nil
}

func (p *jqParser) parseReduce() (jqNode, error) {
	p.pos++
	src, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	if err := p.expectIdent("as"); err != nil {
		return nil, err
	}
	t := p.peek()
	if t == nil || t.kind != "var" {
		return nil, errors.New("unexpected EOF")
	}
	p.pos++
	if err := p.expectOp("("); err != nil {
		return nil, err
	}
	init, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp(";"); err != nil {
		return nil, err
	}
	upd, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp(")"); err != nil {
		return nil, err
	}
	return &jqReduce{src: src, name: t.s, init: init, upd: upd}, nil
}

func (p *jqParser) parseObject() (jqNode, error) {
	p.pos++ // {
	obj := &jqObject{}
	if p.isOp("}") {
		p.pos++
		return obj, nil
	}
	for {
		t := p.peek()
		if t == nil {
			return nil, errors.New("unexpected EOF")
		}
		var key jqNode
		var val jqNode
		switch {
		case t.kind == "ident" || t.kind == "field":
			p.pos++
			key = &jqLit{v: t.s}
			if t.kind == "field" {
				key = &jqLit{v: t.s}
			}
			if !p.isOp(":") {
				val = &jqField{name: t.s}
			}
		case t.kind == "str":
			p.pos++
			key = &jqLit{v: t.s}
			if !p.isOp(":") {
				val = &jqField{name: t.s}
			}
		case t.kind == "var":
			p.pos++
			key = &jqLit{v: t.s}
			if !p.isOp(":") {
				val = &jqVar{name: t.s}
			}
		case t.kind == "op" && t.s == "(":
			p.pos++
			k, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			key = k
		default:
			return nil, fmt.Errorf("unexpected token %q", t.s)
		}
		if val == nil {
			if err := p.expectOp(":"); err != nil {
				return nil, err
			}
			v, err := p.parseObjVal()
			if err != nil {
				return nil, err
			}
			val = v
		}
		obj.keys = append(obj.keys, key)
		obj.vals = append(obj.vals, val)
		if p.isOp(",") {
			p.pos++
			continue
		}
		if err := p.expectOp("}"); err != nil {
			return nil, err
		}
		return obj, nil
	}
}

func (p *jqParser) parseObjVal() (jqNode, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.isOp("|") {
		p.pos++
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &jqPipe{left, right}
	}
	return left, nil
}

// ---- nodes ----

type jqIdentity struct{}

func (jqIdentity) eval(env *jqEnv, in any) ([]any, error) { return []any{in}, nil }

type jqLit struct{ v any }

func (n *jqLit) eval(env *jqEnv, in any) ([]any, error) { return []any{n.v}, nil }

type jqVar struct{ name string }

func (n *jqVar) eval(env *jqEnv, in any) ([]any, error) {
	if n.name == "__loc__" {
		return []any{nil}, nil
	}
	v, ok := env.lookup("$" + n.name)
	if !ok {
		return nil, fmt.Errorf("variable not defined: $%s", n.name)
	}
	return []any{v}, nil
}

type jqPipe struct{ l, r jqNode }

func (n *jqPipe) eval(env *jqEnv, in any) ([]any, error) {
	ls, err := n.l.eval(env, in)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, v := range ls {
		rs, err := n.r.eval(env, v)
		if err != nil {
			return out, err
		}
		out = append(out, rs...)
	}
	return out, nil
}

type jqComma struct{ l, r jqNode }

func (n *jqComma) eval(env *jqEnv, in any) ([]any, error) {
	ls, err := n.l.eval(env, in)
	if err != nil {
		return ls, err
	}
	rs, err := n.r.eval(env, in)
	return append(ls, rs...), err
}

type jqAs struct {
	src  jqNode
	name string
	body jqNode
}

func (n *jqAs) eval(env *jqEnv, in any) ([]any, error) {
	vs, err := n.src.eval(env, in)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, v := range vs {
		e := &jqEnv{vars: map[string]any{"$" + n.name: v}, parent: env}
		rs, err := n.body.eval(e, in)
		if err != nil {
			return out, err
		}
		out = append(out, rs...)
	}
	return out, nil
}

type jqDef struct {
	name   string
	params []string
	body   jqNode
	rest   jqNode
}

type jqClosure struct {
	def *jqDef
	env *jqEnv
}

func (n *jqDef) eval(env *jqEnv, in any) ([]any, error) {
	e := &jqEnv{vars: map[string]any{}, parent: env}
	e.vars["def:"+n.name+"/"+strconv.Itoa(len(n.params))] = &jqClosure{def: n, env: e}
	return n.rest.eval(e, in)
}

type jqField struct{ name string }

func (n *jqField) eval(env *jqEnv, in any) ([]any, error) {
	switch t := in.(type) {
	case nil:
		return []any{nil}, nil
	case *omap:
		v, _ := t.Get(n.name)
		return []any{v}, nil
	}
	return nil, fmt.Errorf("expected an object but got: %s (%s)", jqTypeName(in), jqShort(in))
}

type jqIndex struct{ idx jqNode }

func (n *jqIndex) eval(env *jqEnv, in any) ([]any, error) {
	ks, err := n.idx.eval(env, in)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, k := range ks {
		v, err := jqIndexValue(in, k)
		if err != nil {
			return out, err
		}
		out = append(out, v)
	}
	return out, nil
}

func jqIndexValue(in any, k any) (any, error) {
	switch t := in.(type) {
	case nil:
		return nil, nil
	case *omap:
		if s, ok := k.(string); ok {
			v, _ := t.Get(s)
			return v, nil
		}
		return nil, fmt.Errorf("expected a string for object key but got: %s", jqTypeName(k))
	case []any:
		if f, ok := jqToFloat(k); ok {
			i := int(math.Floor(f))
			if i < 0 {
				i += len(t)
			}
			if i < 0 || i >= len(t) {
				return nil, nil
			}
			return t[i], nil
		}
		return nil, fmt.Errorf("expected a number for indexing an array but got: %s", jqTypeName(k))
	}
	return nil, fmt.Errorf("expected an object but got: %s (%s)", jqTypeName(in), jqShort(in))
}

type jqSlice struct{ lo, hi jqNode }

func (n *jqSlice) eval(env *jqEnv, in any) ([]any, error) {
	lo, hi := 0.0, math.Inf(1)
	if n.lo != nil {
		vs, err := n.lo.eval(env, in)
		if err != nil || len(vs) == 0 {
			return nil, err
		}
		if vs[0] != nil {
			lo, _ = jqToFloat(vs[0])
		}
	}
	if n.hi != nil {
		vs, err := n.hi.eval(env, in)
		if err != nil || len(vs) == 0 {
			return nil, err
		}
		if vs[0] != nil {
			hi, _ = jqToFloat(vs[0])
		}
	}
	clamp := func(f float64, l int) int {
		if math.IsInf(f, 1) {
			return l
		}
		i := int(math.Floor(f))
		if i < 0 {
			i += l
		}
		if i < 0 {
			i = 0
		}
		if i > l {
			i = l
		}
		return i
	}
	switch t := in.(type) {
	case nil:
		return []any{nil}, nil
	case []any:
		a, b := clamp(lo, len(t)), clamp(hi, len(t))
		if b < a {
			b = a
		}
		res := make([]any, b-a)
		copy(res, t[a:b])
		return []any{res}, nil
	case string:
		r := []rune(t)
		a, b := clamp(lo, len(r)), clamp(hi, len(r))
		if b < a {
			b = a
		}
		return []any{string(r[a:b])}, nil
	}
	return nil, fmt.Errorf("cannot slice %s", jqTypeName(in))
}

type jqIter struct{}

func (jqIter) eval(env *jqEnv, in any) ([]any, error) {
	switch t := in.(type) {
	case []any:
		out := make([]any, len(t))
		copy(out, t)
		return out, nil
	case *omap:
		out := make([]any, 0, len(t.keys))
		for _, k := range t.keys {
			out = append(out, t.vals[k])
		}
		return out, nil
	}
	return nil, fmt.Errorf("cannot iterate over: %s", jqShortType(in))
}

type jqTry struct {
	body  jqNode
	catch jqNode
}

func (n *jqTry) eval(env *jqEnv, in any) ([]any, error) {
	vs, err := n.body.eval(env, in)
	if err != nil {
		if n.catch != nil {
			cs, err2 := n.catch.eval(env, err.Error())
			return append(vs, cs...), err2
		}
		return vs, nil
	}
	return vs, nil
}

type jqArray struct{ body jqNode }

func (n *jqArray) eval(env *jqEnv, in any) ([]any, error) {
	if n.body == nil {
		return []any{[]any{}}, nil
	}
	vs, err := n.body.eval(env, in)
	if err != nil {
		return nil, err
	}
	if vs == nil {
		vs = []any{}
	}
	return []any{vs}, nil
}

type jqObject struct {
	keys []jqNode
	vals []jqNode
}

func (n *jqObject) eval(env *jqEnv, in any) ([]any, error) {
	results := []*omap{newOmap()}
	for i := range n.keys {
		ks, err := n.keys[i].eval(env, in)
		if err != nil {
			return nil, err
		}
		vs, err := n.vals[i].eval(env, in)
		if err != nil {
			return nil, err
		}
		var next []*omap
		for _, base := range results {
			for _, k := range ks {
				ksStr, ok := k.(string)
				if !ok {
					return nil, fmt.Errorf("expected a string for object key but got: %s", jqTypeName(k))
				}
				for _, v := range vs {
					m := cloneOmap(base)
					m.Set(ksStr, v)
					next = append(next, m)
				}
			}
		}
		results = next
	}
	out := make([]any, len(results))
	for i, r := range results {
		out[i] = r
	}
	return out, nil
}

func cloneOmap(m *omap) *omap {
	c := newOmap()
	for _, k := range m.keys {
		c.Set(k, m.vals[k])
	}
	return c
}

type jqIf struct {
	cond, then, els jqNode
}

func (n *jqIf) eval(env *jqEnv, in any) ([]any, error) {
	cs, err := n.cond.eval(env, in)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, c := range cs {
		if jqTruthy(c) {
			vs, err := n.then.eval(env, in)
			if err != nil {
				return out, err
			}
			out = append(out, vs...)
		} else if n.els != nil {
			vs, err := n.els.eval(env, in)
			if err != nil {
				return out, err
			}
			out = append(out, vs...)
		} else {
			out = append(out, in)
		}
	}
	return out, nil
}

type jqReduce struct {
	src       jqNode
	name      string
	init, upd jqNode
}

func (n *jqReduce) eval(env *jqEnv, in any) ([]any, error) {
	accs, err := n.init.eval(env, in)
	if err != nil || len(accs) == 0 {
		return nil, err
	}
	acc := accs[len(accs)-1]
	vs, err := n.src.eval(env, in)
	if err != nil {
		return nil, err
	}
	for _, v := range vs {
		e := &jqEnv{vars: map[string]any{"$" + n.name: v}, parent: env}
		rs, err := n.upd.eval(e, acc)
		if err != nil {
			return nil, err
		}
		if len(rs) == 0 {
			acc = nil
		} else {
			acc = rs[len(rs)-1]
		}
	}
	return []any{acc}, nil
}

type jqAlt struct{ l, r jqNode }

func (n *jqAlt) eval(env *jqEnv, in any) ([]any, error) {
	ls, _ := n.l.eval(env, in)
	var out []any
	for _, v := range ls {
		if jqTruthy(v) {
			out = append(out, v)
		}
	}
	if len(out) > 0 {
		return out, nil
	}
	return n.r.eval(env, in)
}

type jqBool struct {
	op   string
	l, r jqNode
}

func (n *jqBool) eval(env *jqEnv, in any) ([]any, error) {
	ls, err := n.l.eval(env, in)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, l := range ls {
		lt := jqTruthy(l)
		if n.op == "and" && !lt {
			out = append(out, false)
			continue
		}
		if n.op == "or" && lt {
			out = append(out, true)
			continue
		}
		rs, err := n.r.eval(env, in)
		if err != nil {
			return out, err
		}
		for _, r := range rs {
			out = append(out, jqTruthy(r))
		}
	}
	return out, nil
}

type jqNeg struct{ n jqNode }

func (n *jqNeg) eval(env *jqEnv, in any) ([]any, error) {
	vs, err := n.n.eval(env, in)
	if err != nil {
		return nil, err
	}
	out := make([]any, 0, len(vs))
	for _, v := range vs {
		f, ok := jqToFloat(v)
		if !ok {
			return nil, fmt.Errorf("cannot negate: %s", jqShortType(v))
		}
		out = append(out, normNum(-f))
	}
	return out, nil
}

type jqBin struct {
	op   string
	l, r jqNode
}

func (n *jqBin) eval(env *jqEnv, in any) ([]any, error) {
	rs, err := n.r.eval(env, in)
	if err != nil {
		return nil, err
	}
	ls, err := n.l.eval(env, in)
	if err != nil {
		return nil, err
	}
	var out []any
	for _, r := range rs {
		for _, l := range ls {
			v, err := jqBinOp(n.op, l, r)
			if err != nil {
				return out, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

type jqAssign struct {
	op   string
	path jqNode
	val  jqNode
}

func (n *jqAssign) eval(env *jqEnv, in any) ([]any, error) {
	paths, err := jqPaths(n.path, env, in)
	if err != nil {
		return nil, err
	}
	if n.op == "=" {
		vs, err := n.val.eval(env, in)
		if err != nil {
			return nil, err
		}
		var out []any
		for _, v := range vs {
			cur := in
			for _, p := range paths {
				cur, err = jqSetPath(cur, p, v)
				if err != nil {
					return nil, err
				}
			}
			out = append(out, cur)
		}
		return out, nil
	}
	cur := in
	for _, p := range paths {
		old, _ := jqGetPath(cur, p)
		var nv any
		if n.op == "|=" {
			vs, err := n.val.eval(env, old)
			if err != nil {
				return nil, err
			}
			if len(vs) > 0 {
				nv = vs[0]
			}
		} else {
			vs, err := n.val.eval(env, in)
			if err != nil {
				return nil, err
			}
			if len(vs) == 0 {
				continue
			}
			op := strings.TrimSuffix(n.op, "=")
			if op == "//" {
				if jqTruthy(old) {
					nv = old
				} else {
					nv = vs[0]
				}
			} else {
				nv, err = jqBinOp(op, old, vs[0])
				if err != nil {
					return nil, err
				}
			}
		}
		cur, err = jqSetPath(cur, p, nv)
		if err != nil {
			return nil, err
		}
	}
	return []any{cur}, nil
}

type jqFormat struct{ name string }

func (n *jqFormat) eval(env *jqEnv, in any) ([]any, error) {
	switch n.name {
	case "json":
		return []any{marshalJSON(in)}, nil
	case "text":
		return []any{jqToString(in)}, nil
	case "csv", "tsv":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("cannot %s: %s", n.name, jqShortType(in))
		}
		parts := make([]string, len(arr))
		for i, e := range arr {
			switch t := e.(type) {
			case string:
				if n.name == "csv" {
					parts[i] = `"` + strings.ReplaceAll(t, `"`, `""`) + `"`
				} else {
					r := strings.NewReplacer("\\", "\\\\", "\t", "\\t", "\r", "\\r", "\n", "\\n")
					parts[i] = r.Replace(t)
				}
			default:
				parts[i] = jqToString(e)
			}
		}
		sep := ","
		if n.name == "tsv" {
			sep = "\t"
		}
		return []any{strings.Join(parts, sep)}, nil
	case "base64":
		return []any{base64Encode(jqToString(in))}, nil
	case "html":
		r := strings.NewReplacer("<", "&lt;", ">", "&gt;", "&", "&amp;", "'", "&#39;", `"`, "&quot;")
		return []any{r.Replace(jqToString(in))}, nil
	case "uri":
		return []any{uriEscape(jqToString(in))}, nil
	case "sh":
		return []any{"'" + strings.ReplaceAll(jqToString(in), "'", `'\''`) + "'"}, nil
	}
	return nil, fmt.Errorf("%s is not a valid format", n.name)
}

// ---- path helpers ----

func jqPaths(n jqNode, env *jqEnv, in any) ([][]any, error) {
	switch t := n.(type) {
	case *jqIdentity:
		return [][]any{{}}, nil
	case *jqField:
		return [][]any{{t.name}}, nil
	case *jqIndex:
		ks, err := t.idx.eval(env, in)
		if err != nil {
			return nil, err
		}
		var out [][]any
		for _, k := range ks {
			out = append(out, []any{k})
		}
		return out, nil
	case *jqIter:
		switch v := in.(type) {
		case []any:
			var out [][]any
			for i := range v {
				out = append(out, []any{float64(i)})
			}
			return out, nil
		case *omap:
			var out [][]any
			for _, k := range v.keys {
				out = append(out, []any{k})
			}
			return out, nil
		}
		return nil, nil
	case *jqPipe:
		lps, err := jqPaths(t.l, env, in)
		if err != nil {
			return nil, err
		}
		var out [][]any
		for _, lp := range lps {
			sub, _ := jqGetPath(in, lp)
			rps, err := jqPaths(t.r, env, sub)
			if err != nil {
				return nil, err
			}
			for _, rp := range rps {
				p := append(append([]any{}, lp...), rp...)
				out = append(out, p)
			}
		}
		return out, nil
	case *jqComma:
		a, err := jqPaths(t.l, env, in)
		if err != nil {
			return nil, err
		}
		b, err := jqPaths(t.r, env, in)
		if err != nil {
			return nil, err
		}
		return append(a, b...), nil
	case *jqCall:
		if t.name == "select" && len(t.args) == 1 {
			cs, err := t.args[0].eval(env, in)
			if err != nil {
				return nil, err
			}
			for _, c := range cs {
				if jqTruthy(c) {
					return [][]any{{}}, nil
				}
			}
			return nil, nil
		}
		if t.name == "empty" {
			return nil, nil
		}
	}
	return nil, errors.New("invalid path expression")
}

func jqGetPath(v any, path []any) (any, error) {
	cur := v
	for _, k := range path {
		var err error
		cur, err = jqIndexValue(cur, k)
		if err != nil {
			return nil, err
		}
	}
	return cur, nil
}

func jqSetPath(v any, path []any, nv any) (any, error) {
	if len(path) == 0 {
		return nv, nil
	}
	k := path[0]
	switch t := v.(type) {
	case nil:
		if s, ok := k.(string); ok {
			m := newOmap()
			child, err := jqSetPath(nil, path[1:], nv)
			if err != nil {
				return nil, err
			}
			m.Set(s, child)
			return m, nil
		}
		if f, ok := jqToFloat(k); ok {
			arr := make([]any, int(f)+1)
			child, err := jqSetPath(nil, path[1:], nv)
			if err != nil {
				return nil, err
			}
			arr[int(f)] = child
			return arr, nil
		}
	case *omap:
		s, ok := k.(string)
		if !ok {
			return nil, errors.New("invalid path")
		}
		m := cloneOmap(t)
		old, _ := t.Get(s)
		child, err := jqSetPath(old, path[1:], nv)
		if err != nil {
			return nil, err
		}
		m.Set(s, child)
		return m, nil
	case []any:
		f, ok := jqToFloat(k)
		if !ok {
			return nil, errors.New("invalid path")
		}
		i := int(f)
		if i < 0 {
			i += len(t)
		}
		arr := make([]any, len(t))
		copy(arr, t)
		for len(arr) <= i {
			arr = append(arr, nil)
		}
		child, err := jqSetPath(arr[i], path[1:], nv)
		if err != nil {
			return nil, err
		}
		arr[i] = child
		return arr, nil
	}
	return nil, fmt.Errorf("cannot index %s", jqTypeName(v))
}

func jqDeletePath(v any, path []any) any {
	if len(path) == 0 {
		return nil
	}
	if len(path) == 1 {
		switch t := v.(type) {
		case *omap:
			s, _ := path[0].(string)
			m := newOmap()
			for _, k := range t.keys {
				if k != s {
					m.Set(k, t.vals[k])
				}
			}
			return m
		case []any:
			f, _ := jqToFloat(path[0])
			i := int(f)
			if i < 0 {
				i += len(t)
			}
			var arr []any
			for j, e := range t {
				if j != i {
					arr = append(arr, e)
				}
			}
			if arr == nil {
				arr = []any{}
			}
			return arr
		}
		return v
	}
	child, _ := jqIndexValue(v, path[0])
	nc := jqDeletePath(child, path[1:])
	r, _ := jqSetPath(v, path[:1], nc)
	return r
}

// ---- value helpers ----

func normNum(f float64) any {
	return f
}

func jqToFloat(v any) (float64, bool) {
	switch t := v.(type) {
	case float64:
		return t, true
	case int:
		return float64(t), true
	case int64:
		return float64(t), true
	case json.Number:
		f, err := strconv.ParseFloat(string(t), 64)
		return f, err == nil
	}
	return 0, false
}

func jqTruthy(v any) bool {
	switch t := v.(type) {
	case nil:
		return false
	case bool:
		return t
	}
	return true
}

func jqTypeName(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case float64, int, int64, json.Number:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case *omap:
		return "object"
	}
	return "unknown"
}

func jqShort(v any) string {
	s := jqEncode(v)
	if len(s) > 11 {
		s = s[:10] + "..."
	}
	return s
}

func jqShortType(v any) string {
	if v == nil {
		return "null"
	}
	return jqTypeName(v) + " (" + jqShort(v) + ")"
}

func jqEncode(v any) string {
	switch t := v.(type) {
	case float64:
		return jqNumString(t)
	case *omap:
		var sb strings.Builder
		sb.WriteByte('{')
		for i, k := range t.keys {
			if i > 0 {
				sb.WriteByte(',')
			}
			sb.WriteString(marshalJSON(k))
			sb.WriteByte(':')
			sb.WriteString(jqEncode(t.vals[k]))
		}
		sb.WriteByte('}')
		return sb.String()
	case []any:
		var sb strings.Builder
		sb.WriteByte('[')
		for i, e := range t {
			if i > 0 {
				sb.WriteByte(',')
			}
			sb.WriteString(jqEncode(e))
		}
		sb.WriteByte(']')
		return sb.String()
	}
	return marshalJSON(v)
}

func jqNumString(f float64) string {
	if f == math.Trunc(f) && math.Abs(f) < 1e17 {
		return strconv.FormatFloat(f, 'f', -1, 64)
	}
	return strconv.FormatFloat(f, 'g', 17, 64)
}

func jqToString(v any) string {
	if s, ok := v.(string); ok {
		return s
	}
	return jqEncode(v)
}

func jqOrder(v any) int {
	switch t := v.(type) {
	case nil:
		return 0
	case bool:
		if t {
			return 2
		}
		return 1
	case float64, int, int64, json.Number:
		return 3
	case string:
		return 4
	case []any:
		return 5
	case *omap:
		return 6
	}
	return 7
}

func jqCompare(a, b any) int {
	oa, ob := jqOrder(a), jqOrder(b)
	if oa != ob {
		if oa < ob {
			return -1
		}
		return 1
	}
	switch oa {
	case 3:
		fa, _ := jqToFloat(a)
		fb, _ := jqToFloat(b)
		switch {
		case fa < fb:
			return -1
		case fa > fb:
			return 1
		}
		return 0
	case 4:
		return strings.Compare(a.(string), b.(string))
	case 5:
		x, y := a.([]any), b.([]any)
		for i := 0; i < len(x) && i < len(y); i++ {
			if c := jqCompare(x[i], y[i]); c != 0 {
				return c
			}
		}
		switch {
		case len(x) < len(y):
			return -1
		case len(x) > len(y):
			return 1
		}
		return 0
	case 6:
		x, y := a.(*omap), b.(*omap)
		kx, ky := x.sortedKeys(), y.sortedKeys()
		ax, ay := make([]any, len(kx)), make([]any, len(ky))
		for i, k := range kx {
			ax[i] = k
		}
		for i, k := range ky {
			ay[i] = k
		}
		if c := jqCompare(ax, ay); c != 0 {
			return c
		}
		for _, k := range kx {
			if c := jqCompare(x.vals[k], y.vals[k]); c != 0 {
				return c
			}
		}
		return 0
	}
	return 0
}

func jqBinOp(op string, l, r any) (any, error) {
	switch op {
	case "==":
		return jqCompare(l, r) == 0, nil
	case "!=":
		return jqCompare(l, r) != 0, nil
	case "<":
		return jqCompare(l, r) < 0, nil
	case "<=":
		return jqCompare(l, r) <= 0, nil
	case ">":
		return jqCompare(l, r) > 0, nil
	case ">=":
		return jqCompare(l, r) >= 0, nil
	}
	lf, lok := jqToFloat(l)
	rf, rok := jqToFloat(r)
	switch op {
	case "+":
		if l == nil {
			return r, nil
		}
		if r == nil {
			return l, nil
		}
		if lok && rok {
			return normNum(lf + rf), nil
		}
		switch lt := l.(type) {
		case string:
			if rt, ok := r.(string); ok {
				return lt + rt, nil
			}
		case []any:
			if rt, ok := r.([]any); ok {
				out := append(append([]any{}, lt...), rt...)
				return out, nil
			}
		case *omap:
			if rt, ok := r.(*omap); ok {
				m := cloneOmap(lt)
				for _, k := range rt.keys {
					m.Set(k, rt.vals[k])
				}
				return m, nil
			}
		}
	case "-":
		if lok && rok {
			return normNum(lf - rf), nil
		}
		if lt, ok := l.([]any); ok {
			if rt, ok := r.([]any); ok {
				out := []any{}
				for _, e := range lt {
					found := false
					for _, x := range rt {
						if jqCompare(e, x) == 0 {
							found = true
							break
						}
					}
					if !found {
						out = append(out, e)
					}
				}
				return out, nil
			}
		}
	case "*":
		if lok && rok {
			return normNum(lf * rf), nil
		}
		if s, ok := l.(string); ok && rok {
			if rf <= 0 {
				return nil, nil
			}
			return strings.Repeat(s, int(rf)), nil
		}
		if lt, ok := l.(*omap); ok {
			if rt, ok := r.(*omap); ok {
				return jqDeepMerge(lt, rt), nil
			}
		}
	case "/":
		if lok && rok {
			if rf == 0 {
				return nil, fmt.Errorf("cannot divide %s by: %s", jqShortType(l), jqShortType(r))
			}
			return normNum(lf / rf), nil
		}
		if ls, ok := l.(string); ok {
			if rs, ok := r.(string); ok {
				parts := strings.Split(ls, rs)
				out := make([]any, len(parts))
				for i, p := range parts {
					out[i] = p
				}
				return out, nil
			}
		}
	case "%":
		if lok && rok {
			ri := int64(rf)
			if ri == 0 {
				return nil, fmt.Errorf("cannot modulo %s by: %s", jqShortType(l), jqShortType(r))
			}
			return normNum(float64(int64(lf) % ri)), nil
		}
	}
	verb := map[string]string{"+": "add", "-": "subtract", "*": "multiply", "/": "divide", "%": "modulo"}[op]
	return nil, fmt.Errorf("cannot %s: %s and %s", verb, jqShortType(l), jqShortType(r))
}

func jqDeepMerge(a, b *omap) *omap {
	m := cloneOmap(a)
	for _, k := range b.keys {
		bv := b.vals[k]
		if av, ok := m.vals[k]; ok {
			am, ok1 := av.(*omap)
			bm, ok2 := bv.(*omap)
			if ok1 && ok2 {
				m.Set(k, jqDeepMerge(am, bm))
				continue
			}
		}
		m.Set(k, bv)
	}
	return m
}

func jqLength(v any) (any, error) {
	switch t := v.(type) {
	case nil:
		return float64(0), nil
	case bool:
		return nil, fmt.Errorf("length cannot be applied to: %s", jqShortType(v))
	case string:
		return float64(utf8.RuneCountInString(t)), nil
	case []any:
		return float64(len(t)), nil
	case *omap:
		return float64(len(t.keys)), nil
	}
	f, _ := jqToFloat(v)
	return math.Abs(f), nil
}

// ---- function calls ----

type jqCall struct {
	name string
	args []jqNode
}

func (n *jqCall) evalArg(i int, env *jqEnv, in any) ([]any, error) {
	return n.args[i].eval(env, in)
}

func (n *jqCall) eval(env *jqEnv, in any) ([]any, error) {
	if c, ok := env.lookup("def:" + n.name + "/" + strconv.Itoa(len(n.args))); ok {
		cl := c.(*jqClosure)
		e := &jqEnv{vars: map[string]any{}, parent: cl.env}
		for i, p := range cl.def.params {
			if strings.HasPrefix(p, "$") || true {
				vs, err := n.args[i].eval(env, in)
				if err != nil {
					return nil, err
				}
				var v any
				if len(vs) > 0 {
					v = vs[0]
				}
				name := strings.TrimPrefix(p, "$")
				e.vars["$"+name] = v
				argNode := n.args[i]
				argEnv := env
				e.vars["def:"+name+"/0"] = &jqClosure{def: &jqDef{name: name, body: &jqBound{node: argNode, env: argEnv}}, env: argEnv}
			}
		}
		return cl.def.body.eval(e, in)
	}
	one := func(v any, err error) ([]any, error) {
		if err != nil {
			return nil, err
		}
		return []any{v}, nil
	}
	switch n.name + "/" + strconv.Itoa(len(n.args)) {
	case "empty/0":
		return nil, nil
	case "not/0":
		return []any{!jqTruthy(in)}, nil
	case "length/0":
		return one(jqLength(in))
	case "utf8bytelength/0":
		s, ok := in.(string)
		if !ok {
			return nil, fmt.Errorf("utf8bytelength cannot be applied to: %s", jqShortType(in))
		}
		return []any{float64(len(s))}, nil
	case "keys/0", "keys_unsorted/0":
		switch t := in.(type) {
		case *omap:
			ks := t.keys
			if n.name == "keys" {
				ks = t.sortedKeys()
			}
			out := make([]any, len(ks))
			for i, k := range ks {
				out[i] = k
			}
			return []any{out}, nil
		case []any:
			out := make([]any, len(t))
			for i := range t {
				out[i] = float64(i)
			}
			return []any{out}, nil
		}
		return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
	case "values/0":
		if in == nil {
			return nil, nil
		}
		return []any{in}, nil
	case "has/1":
		ks, err := n.evalArg(0, env, in)
		if err != nil {
			return nil, err
		}
		var out []any
		for _, k := range ks {
			switch t := in.(type) {
			case *omap:
				s, _ := k.(string)
				_, ok := t.vals[s]
				out = append(out, ok)
			case []any:
				f, _ := jqToFloat(k)
				out = append(out, f >= 0 && int(f) < len(t))
			default:
				return nil, fmt.Errorf("has(%s) cannot be applied to: %s", jqEncode(k), jqShortType(in))
			}
		}
		return out, nil
	case "in/1":
		cs, err := n.evalArg(0, env, in)
		if err != nil {
			return nil, err
		}
		var out []any
		for _, c := range cs {
			r, err := (&jqCall{name: "has", args: []jqNode{&jqLit{v: in}}}).eval(env, c)
			if err != nil {
				return nil, err
			}
			out = append(out, r...)
		}
		return out, nil
	case "map/1":
		vs, err := jqIter{}.eval(env, in)
		if err != nil {
			return nil, err
		}
		out := []any{}
		for _, v := range vs {
			rs, err := n.evalArg(0, env, v)
			if err != nil {
				return nil, err
			}
			out = append(out, rs...)
		}
		return []any{out}, nil
	case "map_values/1":
		switch t := in.(type) {
		case *omap:
			m := newOmap()
			for _, k := range t.keys {
				rs, err := n.evalArg(0, env, t.vals[k])
				if err != nil {
					return nil, err
				}
				if len(rs) > 0 {
					m.Set(k, rs[0])
				}
			}
			return []any{m}, nil
		case []any:
			out := []any{}
			for _, e := range t {
				rs, err := n.evalArg(0, env, e)
				if err != nil {
					return nil, err
				}
				if len(rs) > 0 {
					out = append(out, rs[0])
				}
			}
			return []any{out}, nil
		}
		return nil, fmt.Errorf("cannot iterate over: %s", jqShortType(in))
	case "select/1":
		cs, err := n.evalArg(0, env, in)
		if err != nil {
			return nil, err
		}
		var out []any
		for _, c := range cs {
			if jqTruthy(c) {
				out = append(out, in)
			}
		}
		return out, nil
	case "recurse/0":
		var out []any
		var rec func(v any)
		rec = func(v any) {
			out = append(out, v)
			switch t := v.(type) {
			case []any:
				for _, e := range t {
					rec(e)
				}
			case *omap:
				for _, k := range t.keys {
					rec(t.vals[k])
				}
			}
		}
		rec(in)
		return out, nil
	case "recurse/1":
		var out []any
		var rec func(v any) error
		rec = func(v any) error {
			out = append(out, v)
			rs, err := n.evalArg(0, env, v)
			if err != nil {
				return nil
			}
			for _, r := range rs {
				if err := rec(r); err != nil {
					return err
				}
			}
			return nil
		}
		if err := rec(in); err != nil {
			return nil, err
		}
		return out, nil
	case "type/0":
		return []any{jqTypeName(in)}, nil
	case "add/0":
		vs, err := jqIter{}.eval(env, in)
		if err != nil {
			return nil, err
		}
		var acc any
		for i, v := range vs {
			if i == 0 {
				acc = v
				continue
			}
			acc, err = jqBinOp("+", acc, v)
			if err != nil {
				return nil, err
			}
		}
		return []any{acc}, nil
	case "tostring/0":
		return []any{jqToString(in)}, nil
	case "tojson/0":
		return []any{jqEncode(in)}, nil
	case "fromjson/0":
		s, ok := in.(string)
		if !ok {
			return nil, fmt.Errorf("fromjson cannot be applied to: %s", jqShortType(in))
		}
		v, err := parseJSONValue([]byte(s))
		if err != nil {
			return nil, err
		}
		return []any{v}, nil
	case "tonumber/0":
		switch t := in.(type) {
		case string:
			f, err := strconv.ParseFloat(strings.TrimSpace(t), 64)
			if err != nil {
				return nil, fmt.Errorf("cannot parse %q as JSON", t)
			}
			return []any{normNum(f)}, nil
		case float64, json.Number, int, int64:
			return []any{in}, nil
		}
		return nil, fmt.Errorf("tonumber cannot be applied to: %s", jqShortType(in))
	case "ascii_downcase/0", "ascii_upcase/0":
		s, ok := in.(string)
		if !ok {
			return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
		}
		b := []byte(s)
		for i, c := range b {
			if n.name == "ascii_downcase" && c >= 'A' && c <= 'Z' {
				b[i] = c + 32
			} else if n.name == "ascii_upcase" && c >= 'a' && c <= 'z' {
				b[i] = c - 32
			}
		}
		return []any{string(b)}, nil
	case "sort/0", "unique/0":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
		}
		out := append([]any{}, arr...)
		sort.SliceStable(out, func(i, j int) bool { return jqCompare(out[i], out[j]) < 0 })
		if n.name == "unique" {
			var u []any
			for i, v := range out {
				if i == 0 || jqCompare(v, out[i-1]) != 0 {
					u = append(u, v)
				}
			}
			if u == nil {
				u = []any{}
			}
			out = u
		}
		return []any{out}, nil
	case "sort_by/1", "group_by/1", "unique_by/1", "min_by/1", "max_by/1":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
		}
		type kv struct {
			k any
			v any
		}
		items := make([]kv, len(arr))
		for i, e := range arr {
			ks, err := n.evalArg(0, env, e)
			if err != nil {
				return nil, err
			}
			items[i] = kv{k: ks, v: e}
		}
		sort.SliceStable(items, func(i, j int) bool { return jqCompare(items[i].k, items[j].k) < 0 })
		switch n.name {
		case "sort_by":
			out := make([]any, len(items))
			for i, it := range items {
				out[i] = it.v
			}
			return []any{out}, nil
		case "group_by", "unique_by":
			out := []any{}
			var cur []any
			for i, it := range items {
				if i > 0 && jqCompare(it.k, items[i-1].k) != 0 {
					out = append(out, cur)
					cur = nil
				}
				cur = append(cur, it.v)
			}
			if cur != nil {
				out = append(out, cur)
			}
			if n.name == "unique_by" {
				u := make([]any, len(out))
				for i, g := range out {
					u[i] = g.([]any)[0]
				}
				return []any{u}, nil
			}
			return []any{out}, nil
		case "min_by":
			if len(items) == 0 {
				return []any{nil}, nil
			}
			return []any{items[0].v}, nil
		case "max_by":
			if len(items) == 0 {
				return []any{nil}, nil
			}
			return []any{items[len(items)-1].v}, nil
		}
	case "min/0", "max/0":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
		}
		if len(arr) == 0 {
			return []any{nil}, nil
		}
		best := arr[0]
		for _, e := range arr[1:] {
			c := jqCompare(e, best)
			if (n.name == "min" && c < 0) || (n.name == "max" && c >= 0) {
				best = e
			}
		}
		return []any{best}, nil
	case "reverse/0":
		switch t := in.(type) {
		case []any:
			out := make([]any, len(t))
			for i, e := range t {
				out[len(t)-1-i] = e
			}
			return []any{out}, nil
		case string:
			r := []rune(t)
			for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
				r[i], r[j] = r[j], r[i]
			}
			return []any{string(r)}, nil
		case nil:
			return []any{[]any{}}, nil
		}
		return nil, fmt.Errorf("reverse cannot be applied to: %s", jqShortType(in))
	case "first/0":
		return one(jqIndexValue(in, float64(0)))
	case "last/0":
		return one(jqIndexValue(in, float64(-1)))
	case "first/1":
		vs, err := n.evalArg(0, env, in)
		if len(vs) > 0 {
			return vs[:1], nil
		}
		return nil, err
	case "last/1":
		vs, err := n.evalArg(0, env, in)
		if err != nil {
			return nil, err
		}
		if len(vs) > 0 {
			return vs[len(vs)-1:], nil
		}
		return nil, nil
	case "limit/2":
		ls, err := n.evalArg(0, env, in)
		if err != nil || len(ls) == 0 {
			return nil, err
		}
		lim, _ := jqToFloat(ls[0])
		vs, err := n.evalArg(1, env, in)
		if int(lim) < len(vs) {
			if lim <= 0 {
				return nil, nil
			}
			return vs[:int(lim)], nil
		}
		return vs, err
	case "nth/1":
		ks, err := n.evalArg(0, env, in)
		if err != nil || len(ks) == 0 {
			return nil, err
		}
		return one(jqIndexValue(in, ks[0]))
	case "range/1", "range/2":
		var lo, hi float64
		if len(n.args) == 1 {
			vs, err := n.evalArg(0, env, in)
			if err != nil || len(vs) == 0 {
				return nil, err
			}
			hi, _ = jqToFloat(vs[0])
		} else {
			a, err := n.evalArg(0, env, in)
			if err != nil || len(a) == 0 {
				return nil, err
			}
			b, err := n.evalArg(1, env, in)
			if err != nil || len(b) == 0 {
				return nil, err
			}
			lo, _ = jqToFloat(a[0])
			hi, _ = jqToFloat(b[0])
		}
		var out []any
		for x := lo; x < hi; x++ {
			out = append(out, normNum(x))
		}
		return out, nil
	case "flatten/0", "flatten/1":
		depth := 1e9
		if len(n.args) == 1 {
			ds, err := n.evalArg(0, env, in)
			if err != nil || len(ds) == 0 {
				return nil, err
			}
			depth, _ = jqToFloat(ds[0])
		}
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("flatten cannot be applied to: %s", jqShortType(in))
		}
		var flat func(a []any, d float64) []any
		flat = func(a []any, d float64) []any {
			out := []any{}
			for _, e := range a {
				if sub, ok := e.([]any); ok && d > 0 {
					out = append(out, flat(sub, d-1)...)
				} else {
					out = append(out, e)
				}
			}
			return out
		}
		return []any{flat(arr, depth)}, nil
	case "join/1":
		ss, err := n.evalArg(0, env, in)
		if err != nil || len(ss) == 0 {
			return nil, err
		}
		sep, _ := ss[0].(string)
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("cannot iterate over: %s", jqShortType(in))
		}
		parts := make([]string, len(arr))
		for i, e := range arr {
			if e == nil {
				parts[i] = ""
			} else {
				parts[i] = jqToString(e)
			}
		}
		return []any{strings.Join(parts, sep)}, nil
	case "split/1":
		ss, err := n.evalArg(0, env, in)
		if err != nil || len(ss) == 0 {
			return nil, err
		}
		s, ok := in.(string)
		if !ok {
			return nil, fmt.Errorf("split cannot be applied to: %s", jqShortType(in))
		}
		sep, _ := ss[0].(string)
		parts := strings.Split(s, sep)
		out := make([]any, len(parts))
		for i, p := range parts {
			out[i] = p
		}
		return []any{out}, nil
	case "test/1", "test/2", "match/1", "capture/1", "sub/2", "gsub/2", "sub/3", "gsub/3":
		return n.regexFunc(env, in)
	case "startswith/1", "endswith/1", "ltrimstr/1", "rtrimstr/1", "contains/1", "inside/1", "index/1", "rindex/1", "indices/1":
		as, err := n.evalArg(0, env, in)
		if err != nil || len(as) == 0 {
			return nil, err
		}
		a := as[0]
		switch n.name {
		case "startswith", "endswith":
			s, ok1 := in.(string)
			p, ok2 := a.(string)
			if !ok1 || !ok2 {
				return nil, fmt.Errorf("%s() requires string inputs", n.name)
			}
			if n.name == "startswith" {
				return []any{strings.HasPrefix(s, p)}, nil
			}
			return []any{strings.HasSuffix(s, p)}, nil
		case "ltrimstr", "rtrimstr":
			s, ok1 := in.(string)
			p, ok2 := a.(string)
			if !ok1 || !ok2 {
				return []any{in}, nil
			}
			if n.name == "ltrimstr" {
				return []any{strings.TrimPrefix(s, p)}, nil
			}
			return []any{strings.TrimSuffix(s, p)}, nil
		case "contains":
			return []any{jqContains(in, a)}, nil
		case "inside":
			return []any{jqContains(a, in)}, nil
		case "index", "rindex", "indices":
			s, ok1 := in.(string)
			p, ok2 := a.(string)
			if ok1 && ok2 {
				var idx []any
				if p != "" {
					for i := 0; i+len(p) <= len(s); i++ {
						if s[i:i+len(p)] == p {
							idx = append(idx, float64(utf8.RuneCountInString(s[:i])))
						}
					}
				}
				switch n.name {
				case "index":
					if len(idx) == 0 {
						return []any{nil}, nil
					}
					return []any{idx[0]}, nil
				case "rindex":
					if len(idx) == 0 {
						return []any{nil}, nil
					}
					return []any{idx[len(idx)-1]}, nil
				}
				if idx == nil {
					idx = []any{}
				}
				return []any{idx}, nil
			}
			return []any{nil}, nil
		}
	case "to_entries/0":
		m, ok := in.(*omap)
		if !ok {
			return nil, fmt.Errorf("to_entries cannot be applied to: %s", jqShortType(in))
		}
		out := []any{}
		for _, k := range m.keys {
			e := newOmap()
			e.Set("key", k)
			e.Set("value", m.vals[k])
			out = append(out, e)
		}
		return []any{out}, nil
	case "from_entries/0":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("from_entries cannot be applied to: %s", jqShortType(in))
		}
		m := newOmap()
		for _, e := range arr {
			em, ok := e.(*omap)
			if !ok {
				continue
			}
			var k any
			for _, kn := range []string{"key", "k", "name", "Name", "Key", "K"} {
				if v, ok := em.vals[kn]; ok && v != nil {
					k = v
					break
				}
			}
			var v any
			for _, vn := range []string{"value", "v", "Value", "V"} {
				if x, ok := em.vals[vn]; ok {
					v = x
					break
				}
			}
			m.Set(jqToString(k), v)
		}
		return []any{m}, nil
	case "with_entries/1":
		te, err := (&jqCall{name: "to_entries"}).eval(env, in)
		if err != nil {
			return nil, err
		}
		mapped, err := (&jqCall{name: "map", args: n.args}).eval(env, te[0])
		if err != nil {
			return nil, err
		}
		return (&jqCall{name: "from_entries"}).eval(env, mapped[0])
	case "paths/0":
		var out []any
		var rec func(v any, path []any)
		rec = func(v any, path []any) {
			switch t := v.(type) {
			case []any:
				for i, e := range t {
					p := append(append([]any{}, path...), float64(i))
					out = append(out, p)
					rec(e, p)
				}
			case *omap:
				for _, k := range t.keys {
					p := append(append([]any{}, path...), k)
					out = append(out, p)
					rec(t.vals[k], p)
				}
			}
		}
		rec(in, nil)
		return out, nil
	case "getpath/1":
		ps, err := n.evalArg(0, env, in)
		if err != nil || len(ps) == 0 {
			return nil, err
		}
		p, _ := ps[0].([]any)
		v, err := jqGetPath(in, p)
		if err != nil {
			return []any{nil}, nil
		}
		return []any{v}, nil
	case "setpath/2":
		ps, err := n.evalArg(0, env, in)
		if err != nil || len(ps) == 0 {
			return nil, err
		}
		vs, err := n.evalArg(1, env, in)
		if err != nil || len(vs) == 0 {
			return nil, err
		}
		p, _ := ps[0].([]any)
		return one(jqSetPath(in, p, vs[0]))
	case "del/1":
		paths, err := jqPaths(n.args[0], env, in)
		if err != nil {
			return nil, err
		}
		cur := in
		for i := len(paths) - 1; i >= 0; i-- {
			cur = jqDeletePath(cur, paths[i])
		}
		return []any{cur}, nil
	case "to_array/0":
		if a, ok := in.([]any); ok {
			return []any{a}, nil
		}
		return []any{[]any{in}}, nil
	case "any/0", "all/0":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("cannot iterate over: %s", jqShortType(in))
		}
		res := n.name == "all"
		for _, e := range arr {
			if n.name == "any" && jqTruthy(e) {
				return []any{true}, nil
			}
			if n.name == "all" && !jqTruthy(e) {
				return []any{false}, nil
			}
		}
		return []any{res}, nil
	case "any/1", "all/1":
		vs, err := jqIter{}.eval(env, in)
		if err != nil {
			return nil, err
		}
		for _, e := range vs {
			cs, err := n.evalArg(0, env, e)
			if err != nil {
				return nil, err
			}
			for _, c := range cs {
				if n.name == "any" && jqTruthy(c) {
					return []any{true}, nil
				}
				if n.name == "all" && !jqTruthy(c) {
					return []any{false}, nil
				}
			}
		}
		return []any{n.name == "all"}, nil
	case "isempty/1":
		vs, _ := n.evalArg(0, env, in)
		return []any{len(vs) == 0}, nil
	case "error/0":
		return nil, errors.New(jqToString(in))
	case "error/1":
		vs, err := n.evalArg(0, env, in)
		if err != nil {
			return nil, err
		}
		if len(vs) > 0 {
			return nil, errors.New(jqToString(vs[0]))
		}
		return nil, errors.New("null")
	case "null/0":
		return []any{nil}, nil
	case "arrays/0", "objects/0", "strings/0", "numbers/0", "booleans/0", "nulls/0", "iterables/0", "scalars/0":
		t := jqTypeName(in)
		ok := false
		switch n.name {
		case "arrays":
			ok = t == "array"
		case "objects":
			ok = t == "object"
		case "strings":
			ok = t == "string"
		case "numbers":
			ok = t == "number"
		case "booleans":
			ok = t == "boolean"
		case "nulls":
			ok = t == "null"
		case "iterables":
			ok = t == "array" || t == "object"
		case "scalars":
			ok = t != "array" && t != "object"
		}
		if ok {
			return []any{in}, nil
		}
		return nil, nil
	case "floor/0", "ceil/0", "round/0", "sqrt/0", "fabs/0", "log/0", "exp/0", "log10/0", "log2/0", "trunc/0":
		f, ok := jqToFloat(in)
		if !ok {
			return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
		}
		fn := map[string]func(float64) float64{"floor": math.Floor, "ceil": math.Ceil, "round": math.Round, "sqrt": math.Sqrt,
			"fabs": math.Abs, "log": math.Log, "exp": math.Exp, "log10": math.Log10, "log2": math.Log2, "trunc": math.Trunc}[n.name]
		return []any{normNum(fn(f))}, nil
	case "abs/0":
		f, ok := jqToFloat(in)
		if !ok {
			return nil, fmt.Errorf("abs cannot be applied to: %s", jqShortType(in))
		}
		return []any{normNum(math.Abs(f))}, nil
	case "ltrimstr/0", "trim/0", "ltrim/0", "rtrim/0":
		s, ok := in.(string)
		if !ok {
			return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
		}
		switch n.name {
		case "trim":
			return []any{strings.TrimSpace(s)}, nil
		case "ltrim":
			return []any{strings.TrimLeft(s, " \t\r\n\f\v")}, nil
		}
		return []any{strings.TrimRight(s, " \t\r\n\f\v")}, nil
	case "env/0", "$ENV/0":
		return []any{newOmap()}, nil
	case "input/0", "inputs/0":
		return nil, nil
	case "splits/1":
		r, err := (&jqCall{name: "split", args: n.args}).eval(env, in)
		if err != nil {
			return nil, err
		}
		if len(r) > 0 {
			return r[0].([]any), nil
		}
		return nil, nil
	case "ascii/0", "implode/0":
		arr, ok := in.([]any)
		if !ok {
			return nil, fmt.Errorf("implode input must be an array")
		}
		var sb strings.Builder
		for _, e := range arr {
			f, _ := jqToFloat(e)
			sb.WriteRune(rune(f))
		}
		return []any{sb.String()}, nil
	case "explode/0":
		s, ok := in.(string)
		if !ok {
			return nil, fmt.Errorf("explode cannot be applied to: %s", jqShortType(in))
		}
		out := []any{}
		for _, r := range s {
			out = append(out, float64(r))
		}
		return []any{out}, nil
	case "tostream/0", "input_line_number/0", "halt/0":
		return nil, nil
	case "infinite/0":
		return []any{math.Inf(1)}, nil
	case "nan/0":
		return []any{math.NaN()}, nil
	case "now/0":
		return []any{0.0}, nil
	case "getpath/0":
		return nil, nil
	}
	return nil, fmt.Errorf("function not defined: %s/%d", n.name, len(n.args))
}

type jqBound struct {
	node jqNode
	env  *jqEnv
}

func (b *jqBound) eval(env *jqEnv, in any) ([]any, error) {
	return b.node.eval(b.env, in)
}

func jqContains(a, b any) bool {
	switch at := a.(type) {
	case string:
		bs, ok := b.(string)
		return ok && strings.Contains(at, bs)
	case []any:
		bt, ok := b.([]any)
		if !ok {
			return false
		}
		for _, be := range bt {
			found := false
			for _, ae := range at {
				if jqContains(ae, be) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	case *omap:
		bt, ok := b.(*omap)
		if !ok {
			return false
		}
		for _, k := range bt.keys {
			av, ok := at.vals[k]
			if !ok || !jqContains(av, bt.vals[k]) {
				return false
			}
		}
		return true
	}
	return jqCompare(a, b) == 0
}

func (n *jqCall) regexFunc(env *jqEnv, in any) ([]any, error) {
	s, ok := in.(string)
	if !ok {
		return nil, fmt.Errorf("%s cannot be applied to: %s", n.name, jqShortType(in))
	}
	res, err := n.evalArg(0, env, in)
	if err != nil || len(res) == 0 {
		return nil, err
	}
	pat, _ := res[0].(string)
	flags := ""
	if (n.name == "test" && len(n.args) == 2) || ((n.name == "sub" || n.name == "gsub") && len(n.args) == 3) {
		fs, err := n.evalArg(len(n.args)-1, env, in)
		if err == nil && len(fs) > 0 {
			flags, _ = fs[0].(string)
		}
	}
	prefix := ""
	if strings.Contains(flags, "i") {
		prefix += "(?i)"
	}
	if strings.Contains(flags, "x") {
		prefix += "(?x)"
	}
	if strings.Contains(flags, "s") {
		prefix += "(?s)"
	}
	re, err := regexp.Compile(prefix + pat)
	if err != nil {
		return nil, err
	}
	switch n.name {
	case "test":
		return []any{re.MatchString(s)}, nil
	case "match", "capture":
		var out []any
		for _, m := range re.FindAllStringSubmatchIndex(s, -1) {
			if n.name == "capture" {
				obj := newOmap()
				for i, name := range re.SubexpNames() {
					if i == 0 || name == "" {
						continue
					}
					if m[2*i] >= 0 {
						obj.Set(name, s[m[2*i]:m[2*i+1]])
					} else {
						obj.Set(name, nil)
					}
				}
				out = append(out, obj)
			} else {
				obj := newOmap()
				obj.Set("offset", float64(utf8.RuneCountInString(s[:m[0]])))
				obj.Set("length", float64(utf8.RuneCountInString(s[m[0]:m[1]])))
				obj.Set("string", s[m[0]:m[1]])
				caps := []any{}
				for i := 1; i < len(m)/2; i++ {
					c := newOmap()
					if m[2*i] >= 0 {
						c.Set("offset", float64(utf8.RuneCountInString(s[:m[2*i]])))
						c.Set("length", float64(utf8.RuneCountInString(s[m[2*i]:m[2*i+1]])))
						c.Set("string", s[m[2*i]:m[2*i+1]])
					} else {
						c.Set("offset", float64(-1))
						c.Set("length", float64(0))
						c.Set("string", nil)
					}
					c.Set("name", nil)
					caps = append(caps, c)
				}
				obj.Set("captures", caps)
				out = append(out, obj)
			}
			if !strings.Contains(flags, "g") {
				break
			}
		}
		return out, nil
	case "sub", "gsub":
		reps, err := n.evalArg(1, env, in)
		if err != nil || len(reps) == 0 {
			return nil, err
		}
		_ = reps
		count := 1
		if n.name == "gsub" || strings.Contains(flags, "g") {
			count = -1
		}
		var sb strings.Builder
		last := 0
		matches := re.FindAllStringSubmatchIndex(s, count)
		for _, m := range matches {
			sb.WriteString(s[last:m[0]])
			capObj := newOmap()
			for i, name := range re.SubexpNames() {
				if i == 0 || name == "" {
					continue
				}
				if m[2*i] >= 0 {
					capObj.Set(name, s[m[2*i]:m[2*i+1]])
				} else {
					capObj.Set(name, nil)
				}
			}
			rs, err := n.evalArg(1, env, capObj)
			if err != nil {
				return nil, err
			}
			if len(rs) > 0 {
				sb.WriteString(jqToString(rs[0]))
			}
			last = m[1]
		}
		sb.WriteString(s[last:])
		return []any{sb.String()}, nil
	}
	return nil, nil
}
