{"command":"cd /workspace && cat > yaml.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

// A compact YAML parser (block & flow styles) producing *omap, []any and scalars.

type yamlLine struct {
	indent int
	text   string // content after indentation (comments not stripped)
	num    int
}

type yamlParser struct {
	lines   []yamlLine
	pos     int
	anchors map[string]any
}

var errYAML = errors.New("yaml: syntax error")

func yamlErr(format string, args ...any) error {
	return fmt.Errorf(format, args...)
}

// sanitizeUTF8 replaces invalid UTF-8 bytes with U+FFFD.
func sanitizeUTF8(s string) string {
	if utf8.ValidString(s) {
		return s
	}
	var sb strings.Builder
	for _, r := range s {
		sb.WriteRune(r)
	}
	return sb.String()
}

// parseYAMLDocuments parses all documents in src.
func parseYAMLDocuments(src string) ([]any, error) {
	src = sanitizeUTF8(src)
	src = strings.ReplaceAll(src, "\r\n", "\n")
	src = strings.TrimPrefix(src, "\ufeff")
	raw := strings.Split(src, "\n")
	var docs []any
	var cur []string
	started := false
	hasContent := false
	flush := func(force bool) error {
		if !hasContent && !force {
			cur = nil
			return nil
		}
		v, err := parseYAMLDoc(cur)
		if err != nil {
			return err
		}
		docs = append(docs, v)
		cur = nil
		hasContent = false
		return nil
	}
	for _, l := range raw {
		if l == "---" || strings.HasPrefix(l, "--- ") || strings.HasPrefix(l, "---\t") {
			if started || hasContent {
				if err := flush(started); err != nil {
					return nil, err
				}
			}
			started = true
			rest := strings.TrimLeft(l[3:], " \t")
			if rest != "" && !strings.HasPrefix(rest, "#") {
				cur = append(cur, rest)
				hasContent = true
			}
			continue
		}
		if l == "..." || strings.HasPrefix(l, "... ") {
			if err := flush(started); err != nil {
				return nil, err
			}
			started = false
			continue
		}
		if !started && !hasContent && strings.HasPrefix(l, "%") {
			if strings.HasPrefix(l, "%YAML") || strings.HasPrefix(l, "%TAG") {
				continue
			}
			return nil, yamlErr("unknown directive")
		}
		cur = append(cur, l)
		t := strings.TrimSpace(l)
		if t != "" && !strings.HasPrefix(t, "#") {
			hasContent = true
		}
	}
	if err := flush(started); err != nil {
		return nil, err
	}
	return docs, nil
}

func parseYAMLDoc(lines []string) (any, error) {
	p := &yamlParser{anchors: map[string]any{}}
	for i, l := range lines {
		if strings.ContainsRune(l, '\t') {
			// tabs in indentation are not allowed; keep content
		}
		ind := 0
		for ind < len(l) && l[ind] == ' ' {
			ind++
		}
		p.lines = append(p.lines, yamlLine{indent: ind, text: l[ind:], num: i})
	}
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	v, err := p.parseBlock(-1)
	if err != nil {
		return nil, err
	}
	p.skipBlank()
	if p.pos < len(p.lines) {
		return nil, yamlErr("unexpected content")
	}
	return v, nil
}

func isBlankOrComment(s string) bool {
	t := strings.TrimSpace(s)
	return t == "" || strings.HasPrefix(t, "#")
}

func (p *yamlParser) skipBlank() {
	for p.pos < len(p.lines) && isBlankOrComment(p.lines[p.pos].text) {
		p.pos++
	}
}

// stripComment removes a trailing comment from a line outside quotes/flow.
func stripComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inD:
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
		case inS:
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
		default:
			if c == '#' && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
				return strings.TrimRight(s[:i], " \t")
			}
			if c == '"' && (i == 0 || strings.ContainsRune(" \t[{,:-?", rune(s[i-1]))) {
				inD = true
			} else if c == '\'' && (i == 0 || strings.ContainsRune(" \t[{,:-?", rune(s[i-1]))) {
				inS = true
			}
		}
	}
	return strings.TrimRight(s, " \t")
}

// findMapColon finds the position of a mapping indicator ": " (or ':' at end) outside quotes and flow.
func findMapColon(s string) int {
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inD:
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
		case inS:
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
		default:
			switch c {
			case '"':
				if i == 0 || depth > 0 {
					inD = true
				}
			case '\'':
				if i == 0 || depth > 0 {
					inS = true
				}
			case '[', '{':
				if i == 0 || depth > 0 {
					depth++
				}
			case ']', '}':
				if depth > 0 {
					depth--
				}
			case '#':
				if i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
					return -1
				}
			case ':':
				if depth == 0 && (i+1 == len(s) || s[i+1] == ' ' || s[i+1] == '\t') {
					return i
				}
			}
		}
	}
	return -1
}

func isSeqEntry(s string) bool {
	return s == "-" || strings.HasPrefix(s, "- ") || strings.HasPrefix(s, "-\t")
}

// parseBlock parses a node whose content starts at the current line with indent > parent.
func (p *yamlParser) parseBlock(parent int) (any, error) {
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	ln := p.lines[p.pos]
	if ln.indent <= parent {
		return nil, nil
	}
	text := ln.text
	if isSeqEntry(text) {
		return p.parseSeq(ln.indent)
	}
	if strings.HasPrefix(text, "? ") || text == "?" {
		return p.parseMap(ln.indent)
	}
	// properties (anchor / tag) on their own line
	if props, rest, ok := splitProps(stripComment(text)); ok && rest == "" {
		p.pos++
		v, err := p.parseBlock(parent)
		if err != nil {
			return nil, err
		}
		return p.applyProps(props, v, true)
	}
	if findMapColon(text) >= 0 {
		return p.parseMap(ln.indent)
	}
	return p.parseScalarLines(parent)
}

type yamlProps struct {
	anchor string
	tag    string
}

// splitProps extracts leading anchor/tag properties.
func splitProps(s string) (yamlProps, string, bool) {
	var props yamlProps
	found := false
	for {
		s = strings.TrimLeft(s, " ")
		if strings.HasPrefix(s, "&") {
			end := strings.IndexAny(s, " \t")
			if end < 0 {
				end = len(s)
			}
			props.anchor = s[1:end]
			s = s[end:]
			found = true
			continue
		}
		if strings.HasPrefix(s, "!") {
			end := strings.IndexAny(s, " \t")
			if end < 0 {
				end = len(s)
			}
			props.tag = s[:end]
			s = s[end:]
			found = true
			continue
		}
		break
	}
	return props, strings.TrimLeft(s, " "), found
}

func (p *yamlParser) applyProps(props yamlProps, v any, hasValue bool) (any, error) {
	if props.anchor == "" && props.tag == "" {
		return v, nil
	}
	if props.anchor != "" && !hasValue {
		return nil, yamlErr("anchor without value")
	}
	if props.tag != "" {
		switch props.tag {
		case "!!str":
			if v == nil {
				v = ""
			} else if _, ok := v.(string); !ok {
				v = yamlScalarString(v)
			}
		case "!!int":
			if s, ok := v.(string); ok {
				if n, err := strconv.ParseInt(s, 0, 64); err == nil {
					v = n
				}
			}
		case "!!float":
			switch t := v.(type) {
			case int64:
				v = float64(t)
			case string:
				if f, err := strconv.ParseFloat(t, 64); err == nil {
					v = f
				}
			}
		case "!!null":
			v = nil
		}
	}
	if props.anchor != "" {
		p.anchors[props.anchor] = v
	}
	return v, nil
}

func yamlScalarString(v any) string {
	switch t := v.(type) {
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case float64:
		return strconv.FormatFloat(t, 'g', -1, 64)
	case bool:
		return strconv.FormatBool(t)
	case string:
		return t
	}
	return ""
}

func (p *yamlParser) parseSeq(indent int) (any, error) {
	arr := []any{}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		ln := p.lines[p.pos]
		if ln.indent != indent || !isSeqEntry(ln.text) {
			if ln.indent > indent {
				return nil, yamlErr("bad indentation of a sequence entry")
			}
			break
		}
		rest := strings.TrimLeft(ln.text[1:], " \t")
		if isBlankOrComment(rest) {
			p.pos++
			v, err := p.parseBlock(indent)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
			continue
		}
		// treat the rest as an inline node at a deeper indentation
		off := len(ln.text) - len(rest)
		p.lines[p.pos] = yamlLine{indent: indent + off, text: rest, num: ln.num}
		v, err := p.parseBlock(indent)
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
	}
	return arr, nil
}

func (p *yamlParser) parseMap(indent int) (any, error) {
	m := newOmap()
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		ln := p.lines[p.pos]
		if ln.indent != indent {
			if ln.indent > indent {
				return nil, yamlErr("bad indentation of a mapping entry")
			}
			break
		}
		text := ln.text
		if isSeqEntry(text) {
			break
		}
		var key any
		var err error
		if strings.HasPrefix(text, "? ") || text == "?" {
			// explicit key
			rest := strings.TrimLeft(text[1:], " ")
			if rest == "" {
				p.pos++
				key, err = p.parseBlock(indent)
			} else {
				p.lines[p.pos] = yamlLine{indent: indent + len(text) - len(rest), text: rest, num: ln.num}
				key, err = p.parseBlock(indent)
			}
			if err != nil {
				return nil, err
			}
			p.skipBlank()
			var val any
			if p.pos < len(p.lines) && p.lines[p.pos].indent == indent && (strings.HasPrefix(p.lines[p.pos].text, ": ") || p.lines[p.pos].text == ":") {
				l2 := p.lines[p.pos]
				rest := strings.TrimLeft(l2.text[1:], " ")
				if rest == "" {
					p.pos++
					val, err = p.parseBlock(indent)
				} else {
					p.lines[p.pos] = yamlLine{indent: indent + len(l2.text) - len(rest), text: rest, num: l2.num}
					val, err = p.parseBlock(indent)
				}
				if err != nil {
					return nil, err
				}
			}
			m.Set(yamlKeyString(key), val)
			continue
		}
		ci := findMapColon(text)
		if ci < 0 {
			return nil, yamlErr("could not find expected ':'")
		}
		keyText := strings.TrimRight(text[:ci], " \t")
		key, err = p.parseInlineScalar(keyText)
		if err != nil {
			return nil, err
		}
		rest := strings.TrimLeft(text[ci+1:], " \t")
		var val any
		restNC := stripComment(rest)
		if restNC == "" {
			p.pos++
			// value on following lines; sequences may be at the same indentation
			p.skipBlank()
			if p.pos < len(p.lines) && p.lines[p.pos].indent == indent && isSeqEntry(p.lines[p.pos].text) {
				val, err = p.parseSeq(indent)
			} else {
				val, err = p.parseBlock(indent)
			}
		} else {
			off := len(text) - len(rest)
			p.lines[p.pos] = yamlLine{indent: indent + off, text: rest, num: ln.num}
			val, err = p.parseValueInline(indent)
		}
		if err != nil {
			return nil, err
		}
		ks := yamlKeyString(key)
		if ks == "<<" {
			if mm, ok := val.(*omap); ok {
				for _, k := range mm.keys {
					if _, exists := m.vals[k]; !exists {
						m.Set(k, mm.vals[k])
					}
				}
				continue
			}
			if arr, ok := val.([]any); ok {
				for _, e := range arr {
					if mm, ok := e.(*omap); ok {
						for _, k := range mm.keys {
							if _, exists := m.vals[k]; !exists {
								m.Set(k, mm.vals[k])
							}
						}
					}
				}
				continue
			}
		}
		m.Set(ks, val)
	}
	return m, nil
}

// parseValueInline parses a value that starts in the middle of a line (after "key: " or "- ").
func (p *yamlParser) parseValueInline(parent int) (any, error) {
	ln := p.lines[p.pos]
	text := stripComment(ln.text)
	props, rest, has := splitProps(text)
	if has {
		if rest == "" {
			p.pos++
			p.skipBlank()
			var v any
			var err error
			if p.pos < len(p.lines) && p.lines[p.pos].indent > parent {
				v, err = p.parseBlock(parent)
			} else if p.pos < len(p.lines) && p.lines[p.pos].indent == parent && isSeqEntry(p.lines[p.pos].text) {
				v, err = p.parseSeq(parent)
			}
			if err != nil {
				return nil, err
			}
			return p.applyProps(props, v, props.tag != "" || v != nil)
		}
		p.lines[p.pos] = yamlLine{indent: ln.indent + len(ln.text) - len(rest), text: rest, num: ln.num}
		v, err := p.parseValueInline(parent)
		if err != nil {
			return nil, err
		}
		return p.applyProps(props, v, true)
	}
	if findMapColon(ln.text) >= 0 && !strings.HasPrefix(ln.text, "[") && !strings.HasPrefix(ln.text, "{") && !strings.HasPrefix(ln.text, "\"") && !strings.HasPrefix(ln.text, "'") {
		// "- key: value" style nested mapping, or "key: a: b" (invalid)
		return p.parseMap(ln.indent)
	}
	return p.parseScalarLines(parent)
}

func yamlKeyString(k any) string {
	switch t := k.(type) {
	case nil:
		return "null"
	case string:
		return t
	case []any, *omap:
		return marshalJSON(t)
	}
	return yamlScalarString(k)
}

// parseScalarLines parses a scalar (plain/quoted/flow/block) starting at the current line.
func (p *yamlParser) parseScalarLines(parent int) (any, error) {
	ln := p.lines[p.pos]
	text := ln.text
	switch {
	case strings.HasPrefix(text, "|") || strings.HasPrefix(text, ">"):
		return p.parseBlockScalar(parent)
	case strings.HasPrefix(text, "\"") || strings.HasPrefix(text, "'"):
		// quoted scalars may span lines
		q := text[0]
		full := text
		p.pos++
		for !quotedComplete(full, q) {
			if p.pos >= len(p.lines) {
				return nil, yamlErr("could not find end character of quoted string")
			}
			full += "\n" + p.lines[p.pos].text
			p.pos++
		}
		s, rest, err := parseQuoted(full, q)
		if err != nil {
			return nil, err
		}
		rest = stripComment(rest)
		if strings.TrimSpace(rest) != "" {
			return nil, yamlErr("unexpected content after quoted string")
		}
		return s, nil
	case strings.HasPrefix(text, "[") || strings.HasPrefix(text, "{"):
		full := stripComment(text)
		p.pos++
		for !flowComplete(full) {
			if p.pos >= len(p.lines) {
				return nil, yamlErr("unterminated flow collection")
			}
			full += " " + stripComment(p.lines[p.pos].text)
			p.pos++
		}
		fp := &flowParser{s: full, p: p}
		v, err := fp.parseValue()
		if err != nil {
			return nil, err
		}
		fp.skipSpace()
		if fp.i < len(fp.s) {
			return nil, yamlErr("unexpected content after flow collection")
		}
		return v, nil
	}
	// plain scalar, possibly multi-line
	parts := []string{stripComment(text)}
	commented := stripComment(text) != strings.TrimRight(text, " \t")
	p.pos++
	for !commented && p.pos < len(p.lines) {
		nl := p.lines[p.pos]
		if nl.indent <= parent {
			break
		}
		t := nl.text
		if strings.TrimSpace(t) == "" {
			parts = append(parts, "")
			p.pos++
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(t), "#") {
			break
		}
		if findMapColon(t) >= 0 || isSeqEntry(t) {
			return nil, yamlErr("mapping values are not allowed in this context")
		}
		c := stripComment(t)
		if c != strings.TrimRight(t, " \t") {
			commented = true
		}
		parts = append(parts, c)
		p.pos++
	}
	// drop trailing empty lines
	for len(parts) > 1 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	var sb strings.Builder
	for i, part := range parts {
		part = strings.TrimSpace(part)
		if i > 0 {
			if part == "" {
				sb.WriteString("\n")
				continue
			}
			prev := parts[i-1]
			if strings.TrimSpace(prev) != "" {
				sb.WriteString(" ")
			}
		}
		sb.WriteString(part)
	}
	s := sb.String()
	if len(parts) == 1 {
		return p.resolvePlain(s)
	}
	return strings.ReplaceAll(s, "\t", ""), nil
}

func quotedComplete(s string, q byte) bool {
	for i := 1; i < len(s); i++ {
		c := s[i]
		if q == '"' && c == '\\' {
			i++
			continue
		}
		if c == q {
			if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
				i++
				continue
			}
			return true
		}
	}
	return false
}

func flowComplete(s string) bool {
	depth := 0
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inD:
			if c == '\\' {
				i++
			} else if c == '"' {
				inD = false
			}
		case inS:
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
		default:
			switch c {
			case '"':
				inD = true
			case '\'':
				inS = true
			case '[', '{':
				depth++
			case ']', '}':
				depth--
				if depth == 0 {
					return true
				}
			}
		}
	}
	return depth <= 0
}

// parseQuoted parses a quoted scalar at the start of s; returns the value and the rest.
func parseQuoted(s string, q byte) (string, string, error) {
	var sb strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if q == '\'' {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					sb.WriteByte('\'')
					i += 2
					continue
				}
				return foldQuoted(sb.String()), s[i+1:], nil
			}
			sb.WriteByte(c)
			i++
			continue
		}
		switch c {
		case '"':
			return foldQuoted(sb.String()), s[i+1:], nil
		case '\\':
			if i+1 >= len(s) {
				return "", "", yamlErr("bad escape")
			}
			e := s[i+1]
			i += 2
			switch e {
			case 'n':
				sb.WriteString("\x00n")
			case 't', '\t':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 'e':
				sb.WriteByte(0x1b)
			case 'f':
				sb.WriteByte(0x0c)
			case 'v':
				sb.WriteByte(0x0b)
			case ' ':
				sb.WriteByte(' ')
			case '"':
				sb.WriteByte('"')
			case '/':
				sb.WriteByte('/')
			case '\\':
				sb.WriteByte('\\')
			case 'N':
				sb.WriteString("\u0085")
			case '_':
				sb.WriteString("\u00a0")
			case 'L':
				sb.WriteString("\u2028")
			case 'P':
				sb.WriteString("\u2029")
			case '\n':
				sb.WriteString("\x00c")
			case 'x', 'u', 'U':
				n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[e]
				if i+n > len(s) {
					return "", "", yamlErr("bad escape")
				}
				v, err := strconv.ParseUint(s[i:i+n], 16, 32)
				if err != nil {
					return "", "", yamlErr("bad escape")
				}
				sb.WriteRune(rune(v))
				i += n
			default:
				return "", "", yamlErr("bad escape")
			}
		default:
			sb.WriteByte(c)
			i++
		}
	}
	return "", "", yamlErr("could not find end character of quoted string")
}

// foldQuoted folds line breaks inside quoted scalars and resolves escape markers.
func foldQuoted(s string) string {
	if strings.Contains(s, "\n") {
		lines := strings.Split(s, "\n")
		var sb strings.Builder
		for i, l := range lines {
			if i > 0 {
				l = strings.TrimLeft(l, " \t")
			}
			if i < len(lines)-1 {
				l = strings.TrimRight(l, " \t")
			}
			if i > 0 {
				prevEsc := strings.HasSuffix(lines[i-1], "\x00c")
				if l == "" {
					sb.WriteString("\n")
					continue
				}
				if !prevEsc && strings.TrimSpace(lines[i-1]) != "" {
					sb.WriteString(" ")
				}
			}
			sb.WriteString(l)
		}
		s = sb.String()
	}
	s = strings.ReplaceAll(s, "\x00c", "")
	return strings.ReplaceAll(s, "\x00n", "\n")
}

func (p *yamlParser) parseBlockScalar(parent int) (any, error) {
	ln := p.lines[p.pos]
	header := stripComment(ln.text)
	literal := header[0] == '|'
	chomp := ""
	explicit := 0
	for _, c := range header[1:] {
		switch {
		case c == '-' || c == '+':
			chomp = string(c)
		case c >= '1' && c <= '9':
			explicit = int(c - '0')
		case c == ' ' || c == '\t':
		default:
			return nil, yamlErr("invalid block scalar header")
		}
	}
	p.pos++
	var body []string
	blockIndent := -1
	if explicit > 0 {
		base := parent
		if base < 0 {
			base = 0
		}
		blockIndent = base + explicit
	}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimSpace(l.text) == "" {
			body = append(body, "")
			if blockIndent >= 0 && l.indent > blockIndent {
				body[len(body)-1] = strings.Repeat(" ", l.indent-blockIndent) + l.text
			}
			p.pos++
			continue
		}
		if blockIndent < 0 {
			if l.indent <= parent {
				break
			}
			blockIndent = l.indent
		}
		if l.indent < blockIndent {
			break
		}
		body = append(body, strings.Repeat(" ", l.indent-blockIndent)+l.text)
		p.pos++
	}
	// trailing blank lines
	trailing := 0
	for len(body) > 0 && body[len(body)-1] == "" {
		body = body[:len(body)-1]
		trailing++
	}
	var content string
	if literal {
		content = strings.Join(body, "\n")
	} else {
		var sb strings.Builder
		for i, l := range body {
			if i > 0 {
				prev := body[i-1]
				switch {
				case l == "" || prev == "":
					sb.WriteString("\n")
				case strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " "):
					sb.WriteString("\n")
				default:
					sb.WriteString(" ")
				}
			}
			if l == "" {
				continue
			}
			sb.WriteString(l)
		}
		content = sb.String()
	}
	if len(body) == 0 {
		if chomp == "+" {
			return strings.Repeat("\n", trailing), nil
		}
		return "", nil
	}
	switch chomp {
	case "-":
	case "+":
		content += "\n" + strings.Repeat("\n", trailing)
	default:
		content += "\n"
	}
	return content, nil
}

// parseInlineScalar parses a single-line scalar/flow text (used for keys).
func (p *yamlParser) parseInlineScalar(s string) (any, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	props, rest, has := splitProps(s)
	if has {
		v, err := p.parseInlineScalar(rest)
		if err != nil {
			return nil, err
		}
		return p.applyProps(props, v, true)
	}
	switch s[0] {
	case '"', '\'':
		v, rest, err := parseQuoted(s, s[0])
		if err != nil {
			return nil, err
		}
		if strings.TrimSpace(rest) != "" {
			return nil, yamlErr("unexpected content")
		}
		return v, nil
	case '[', '{':
		fp := &flowParser{s: s, p: p}
		return fp.parseValue()
	}
	return p.resolvePlain(s)
}

// resolvePlain resolves a single-line plain scalar.
func (p *yamlParser) resolvePlain(s string) (any, error) {
	if s == "" {
		return nil, nil
	}
	switch s[0] {
	case '@', '`', '%':
		return nil, yamlErr("reserved indicator")
	case '*':
		name := s[1:]
		if v, ok := p.anchors[name]; ok {
			return v, nil
		}
		return nil, yamlErr("could not find alias %q", name)
	case '&':
		return nil, yamlErr("anchor without value")
	case '|', '>':
		return "", nil
	case ']', '}':
		return nil, yamlErr("unexpected flow end")
	case '[', '{':
		fp := &flowParser{s: s, p: p}
		return fp.parseValue()
	}
	v := resolveYAMLScalar(s)
	if str, ok := v.(string); ok {
		return strings.ReplaceAll(str, "\t", ""), nil
	}
	return v, nil
}

// resolveYAMLScalar resolves the type of a plain scalar.
func resolveYAMLScalar(s string) any {
	switch s {
	case "~", "null", "Null", "NULL":
		return nil
	case "true", "True", "TRUE":
		return true
	case "false", "False", "FALSE":
		return false
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return math.Inf(1)
	case "-.inf", "-.Inf", "-.INF":
		return math.Inf(-1)
	case ".nan", ".NaN", ".NAN":
		return math.NaN()
	}
	if v, ok := yamlNumber(s); ok {
		return v
	}
	return s
}

func yamlNumber(s string) (any, bool) {
	if s == "" {
		return nil, false
	}
	t := s
	neg := false
	if t[0] == '+' || t[0] == '-' {
		neg = t[0] == '-'
		t = t[1:]
	}
	if t == "" {
		return nil, false
	}
	clean := strings.ReplaceAll(t, "_", "")
	if strings.HasPrefix(t, "_") || clean == "" {
		return nil, false
	}
	base := 10
	digits := clean
	switch {
	case strings.HasPrefix(clean, "0x") || strings.HasPrefix(clean, "0X"):
		base, digits = 16, clean[2:]
	case strings.HasPrefix(clean, "0o") || strings.HasPrefix(clean, "0O"):
		base, digits = 8, clean[2:]
	case strings.HasPrefix(clean, "0b") || strings.HasPrefix(clean, "0B"):
		base, digits = 2, clean[2:]
	case len(clean) > 1 && clean[0] == '0' && isAllDigits(clean):
		base, digits = 8, clean[1:]
	}
	if digits != "" && isDigitsBase(digits, base) {
		u, err := strconv.ParseUint(digits, base, 64)
		if err == nil {
			if neg {
				if u <= 1<<63 {
					return -int64(u), true
				}
				return -float64(u), true
			}
			if u <= math.MaxInt64 {
				return int64(u), true
			}
			return u, true
		}
		if base == 10 {
			f, err := strconv.ParseFloat(digits, 64)
			if err == nil {
				if neg {
					f = -f
				}
				return f, true
			}
		}
		return nil, false
	}
	// float: requires a dot
	if base == 10 && strings.Contains(clean, ".") && isFloatText(clean) {
		f, err := strconv.ParseFloat(clean, 64)
		if err == nil {
			if neg {
				f = -f
			}
			return f, true
		}
	}
	return nil, false
}

func isAllDigits(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return s != ""
}

func isDigitsBase(s string, base int) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		default:
			return false
		}
		if d >= base {
			return false
		}
	}
	return true
}

func isFloatText(s string) bool {
	// [0-9]*\.[0-9]*([eE][-+]?[0-9]+)?
	i := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	intDigits := i
	if i >= len(s) || s[i] != '.' {
		return false
	}
	i++
	start := i
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if intDigits == 0 && i == start {
		return false
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i < len(s) && (s[i] == '+' || s[i] == '-') {
			i++
		}
		ds := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == ds {
			return false
		}
	}
	return i == len(s)
}

// ---- flow parser ----

type flowParser struct {
	s string
	i int
	p *yamlParser
}

func (f *flowParser) skipSpace() {
	for f.i < len(f.s) && (f.s[f.i] == ' ' || f.s[f.i] == '\t' || f.s[f.i] == '\n') {
		f.i++
	}
}

func (f *flowParser) parseValue() (any, error) {
	f.skipSpace()
	if f.i >= len(f.s) {
		return nil, yamlErr("unexpected end of flow")
	}
	switch f.s[f.i] {
	case '[':
		f.i++
		arr := []any{}
		for {
			f.skipSpace()
			if f.i >= len(f.s) {
				return nil, yamlErr("unterminated flow sequence")
			}
			if f.s[f.i] == ']' {
				f.i++
				return arr, nil
			}
			v, err := f.parseEntry(true)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
			f.skipSpace()
			if f.i < len(f.s) && f.s[f.i] == ',' {
				f.i++
				continue
			}
			if f.i < len(f.s) && f.s[f.i] == ']' {
				f.i++
				return arr, nil
			}
			return nil, yamlErr("unterminated flow sequence")
		}
	case '{':
		f.i++
		m := newOmap()
		for {
			f.skipSpace()
			if f.i >= len(f.s) {
				return nil, yamlErr("unterminated flow mapping")
			}
			if f.s[f.i] == '}' {
				f.i++
				return m, nil
			}
			k, err := f.parseScalar(true)
			if err != nil {
				return nil, err
			}
			f.skipSpace()
			var v any
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				f.skipSpace()
				if f.i < len(f.s) && (f.s[f.i] == ',' || f.s[f.i] == '}') {
					v = nil
				} else {
					v, err = f.parseValue()
					if err != nil {
						return nil, err
					}
				}
			}
			m.Set(yamlKeyString(k), v)
			f.skipSpace()
			if f.i < len(f.s) && f.s[f.i] == ',' {
				f.i++
				continue
			}
			if f.i < len(f.s) && f.s[f.i] == '}' {
				f.i++
				return m, nil
			}
			return nil, yamlErr("unterminated flow mapping")
		}
	}
	return f.parseScalar(false)
}

// parseEntry parses a flow sequence entry (which may be a single-pair mapping).
func (f *flowParser) parseEntry(inSeq bool) (any, error) {
	start := f.i
	v, err := f.parseValue()
	if err != nil {
		return nil, err
	}
	f.skipSpace()
	if f.i < len(f.s) && f.s[f.i] == ':' && inSeq {
		_ = start
		f.i++
		f.skipSpace()
		var val any
		if f.i < len(f.s) && f.s[f.i] != ',' && f.s[f.i] != ']' {
			val, err = f.parseValue()
			if err != nil {
				return nil, err
			}
		}
		m := newOmap()
		m.Set(yamlKeyString(v), val)
		return m, nil
	}
	return v, nil
}

func (f *flowParser) parseScalar(isKey bool) (any, error) {
	f.skipSpace()
	if f.i >= len(f.s) {
		return nil, nil
	}
	c := f.s[f.i]
	if c == '"' || c == '\'' {
		v, rest, err := parseQuoted(f.s[f.i:], c)
		if err != nil {
			return nil, err
		}
		f.i = len(f.s) - len(rest)
		return v, nil
	}
	if c == '[' || c == '{' {
		return f.parseValue()
	}
	start := f.i
	for f.i < len(f.s) {
		ch := f.s[f.i]
		if ch == ',' || ch == ']' || ch == '}' || ch == '[' || ch == '{' {
			break
		}
		if ch == ':' && (f.i+1 == len(f.s) || strings.ContainsRune(" ,]}\t", rune(f.s[f.i+1]))) {
			break
		}
		if ch == '#' && f.i > start && (f.s[f.i-1] == ' ') {
			break
		}
		f.i++
	}
	text := strings.TrimSpace(f.s[start:f.i])
	if text == "" {
		return nil, nil
	}
	props, rest, has := splitProps(text)
	if has {
		var v any
		var err error
		if rest != "" {
			v, err = f.p.resolvePlain(rest)
			if err != nil {
				return nil, err
			}
		}
		return f.p.applyProps(props, v, true)
	}
	return f.p.resolvePlain(text)
}
