// ---- YAML reader ----

type yamlSource struct {
	docs []any
	pos  int
	err  error
}

func (s *yamlSource) Next() (any, error) {
	if s.err != nil {
		e := s.err
		s.err = nil
		return nil, e
	}
	if s.pos >= len(s.docs) {
		return nil, io.EOF
	}
	v := s.docs[s.pos]
	s.pos++
	return v, nil
}

func (s *yamlSource) More() bool { return s.pos < len(s.docs) }

func newYAMLReader(r io.Reader, opts *ReadOpts, jq string) (Reader, error) {
	b, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	docs, err := parseYAMLDocuments(string(b))
	if err != nil {
		return nil, err
	}
	return newDocReader(&yamlSource{docs: docs}, opts, jq, yamlConv, false)
}

func yamlConv(v any) any {
	switch t := v.(type) {
	case nil:
		return nil
	case string:
		if strings.Contains(t, "\n") {
			return `"` + strings.ReplaceAll(strings.TrimRight(t, "\n"), "\n", " ") + `"`
		}
		return t
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case int:
		return strconv.Itoa(t)
	case float64:
		return strconv.FormatFloat(t, 'g', -1, 64)
	case bool:
		return strconv.FormatBool(t)
	case []any, *omap:
		var sb strings.Builder
		yamlFlowJSON(&sb, t)
		return sb.String()
	}
	return jsonConv(v)
}

func yamlFloatString(f float64) string {
	switch {
	case math.IsInf(f, 1):
		return ".inf"
	case math.IsInf(f, -1):
		return "-.inf"
	case math.IsNaN(f):
		return ".nan"
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

// yamlFlowJSON writes a JSON-like flow representation: {"a": 1, "b": [1, 2]}.
func yamlFlowJSON(sb *strings.Builder, v any) {
	switch t := v.(type) {
	case nil:
		sb.WriteString("null")
	case bool:
		sb.WriteString(strconv.FormatBool(t))
	case int64:
		sb.WriteString(strconv.FormatInt(t, 10))
	case uint64:
		sb.WriteString(strconv.FormatUint(t, 10))
	case float64:
		sb.WriteString(yamlFloatString(t))
	case string:
		sb.WriteString(jsonQuoteNoHTML(t))
	case []any:
		sb.WriteByte('[')
		for i, e := range t {
			if i > 0 {
				sb.WriteString(", ")
			}
			yamlFlowJSON(sb, e)
		}
		sb.WriteByte(']')
	case *omap:
		sb.WriteByte('{')
		keys := make([]string, len(t.keys))
		copy(keys, t.keys)
		sort.Strings(keys)
		for i, k := range keys {
			if i > 0 {
				sb.WriteString(", ")
			}
			sb.WriteString(jsonQuoteNoHTML(k))
			sb.WriteString(": ")
			yamlFlowJSON(sb, t.vals[k])
		}
		sb.WriteByte('}')
	default:
		sb.WriteString(jsonQuoteNoHTML(toString(v)))
	}
}

func jsonQuoteNoHTML(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				sb.WriteString(`\u00`)
				sb.WriteString(hex.EncodeToString([]byte{byte(r)}))
				continue
			}
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// ---- YAML writer ----

type yamlPair struct {
	key string
	val any
}

type yamlWriter struct {
	w    io.Writer
	o    *WriteOpts
	rows [][]yamlPair
}

func (y *yamlWriter) PreWrite(columns []string, types []string) error { return nil }

func (y *yamlWriter) WriteRow(values []any, columns []string) error {
	row := make([]yamlPair, len(values))
	for i, v := range values {
		row[i] = yamlPair{key: columns[i], val: y.toYAMLValue(v)}
	}
	y.rows = append(y.rows, row)
	return nil
}

func (y *yamlWriter) toYAMLValue(v any) any {
	switch t := v.(type) {
	case string:
		return yamlParseString(t)
	case []byte:
		return yamlParseString(string(t))
	}
	if y.o.OutNeedNULL {
		return y.o.OutNULL
	}
	switch t := v.(type) {
	case nil:
		return nil
	case int64:
		return t
	case float64:
		return t
	case bool:
		return t
	case time.Time:
		return yamlTime(t)
	}
	return toString(v)
}

type yamlTime string

func yamlTime_(t time.Time) yamlTime { return yamlTime(t.Format(time.RFC3339Nano)) }

func yamlParseString(s string) any {
	docs, err := parseYAMLDocuments(s)
	if err != nil {
		return sanitizeUTF8(s)
	}
	if len(docs) == 0 {
		return nil
	}
	return docs[0]
}

func (y *yamlWriter) PostWrite() error {
	var sb strings.Builder
	if len(y.rows) == 0 {
		sb.WriteString("[]\n")
	} else {
		for _, row := range y.rows {
			for i, p := range row {
				if i == 0 {
					sb.WriteString("- ")
				} else {
					sb.WriteString("  ")
				}
				yamlWriteKeyValue(&sb, p.key, p.val, 2)
			}
		}
	}
	_, err := io.WriteString(y.w, sb.String())
	return err
}

// yamlWriteKeyValue writes "key: value" where the key is already positioned; indent is
// the column of the key.
func yamlWriteKeyValue(sb *strings.Builder, key string, val any, indent int) {
	sb.WriteString(yamlScalarText(key))
	sb.WriteString(":")
	yamlWriteValueAfterIndicator(sb, val, indent, true)
}

func yamlIsEmptyCollection(v any) (string, bool) {
	switch t := v.(type) {
	case []any:
		if len(t) == 0 {
			return "[]", true
		}
	case *omap:
		if len(t.keys) == 0 {
			return "{}", true
		}
	}
	return "", false
}

// yamlWriteValueAfterIndicator writes the value after "key:" or "-".
func yamlWriteValueAfterIndicator(sb *strings.Builder, val any, indent int, afterKey bool) {
	if s, ok := yamlIsEmptyCollection(val); ok {
		sb.WriteString(" ")
		sb.WriteString(s)
		sb.WriteString("\n")
		return
	}
	switch t := val.(type) {
	case *omap:
		if afterKey {
			sb.WriteString("\n")
			yamlWriteMap(sb, t, indent+2)
		} else {
			sb.WriteString(" ")
			yamlWriteMapInline(sb, t, indent+2)
		}
		return
	case []any:
		if afterKey {
			sb.WriteString("\n")
			yamlWriteSeq(sb, t, indent)
		} else {
			sb.WriteString(" ")
			yamlWriteSeqInline(sb, t, indent+2)
		}
		return
	case string:
		if strings.Contains(t, "\n") {
			yamlWriteLiteral(sb, t, indent+2)
			return
		}
	}
	sb.WriteString(" ")
	sb.WriteString(yamlValueText(val))
	sb.WriteString("\n")
}

func yamlWriteMap(sb *strings.Builder, m *omap, indent int) {
	for _, k := range m.keys {
		sb.WriteString(strings.Repeat(" ", indent))
		yamlWriteKeyValue(sb, k, m.vals[k], indent)
	}
}

// yamlWriteMapInline writes a map whose first key follows "- " on the current line.
func yamlWriteMapInline(sb *strings.Builder, m *omap, indent int) {
	for i, k := range m.keys {
		if i > 0 {
			sb.WriteString(strings.Repeat(" ", indent))
		}
		yamlWriteKeyValue(sb, k, m.vals[k], indent)
	}
}

func yamlWriteSeq(sb *strings.Builder, arr []any, indent int) {
	for _, e := range arr {
		sb.WriteString(strings.Repeat(" ", indent))
		sb.WriteString("-")
		yamlWriteValueAfterIndicator(sb, e, indent, false)
	}
}

func yamlWriteSeqInline(sb *strings.Builder, arr []any, indent int) {
	for i, e := range arr {
		if i > 0 {
			sb.WriteString(strings.Repeat(" ", indent))
		}
		sb.WriteString("-")
		yamlWriteValueAfterIndicator(sb, e, indent, false)
	}
}

func yamlWriteLiteral(sb *strings.Builder, s string, indent int) {
	chomp := "-"
	body := s
	if strings.HasSuffix(s, "\n") {
		trimmed := strings.TrimRight(s, "\n")
		if len(s)-len(trimmed) == 1 {
			chomp = ""
		} else {
			chomp = "+"
		}
		body = trimmed
		if chomp == "+" {
			body = s[:len(s)-1]
		}
	}
	sb.WriteString(" |")
	sb.WriteString(chomp)
	sb.WriteString("\n")
	for _, line := range strings.Split(body, "\n") {
		if line == "" {
			sb.WriteString("\n")
			continue
		}
		sb.WriteString(strings.Repeat(" ", indent))
		sb.WriteString(line)
		sb.WriteString("\n")
	}
}

func yamlValueText(v any) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case bool:
		return strconv.FormatBool(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case int:
		return strconv.Itoa(t)
	case float64:
		return yamlFloatString(t)
	case yamlTime:
		return string(t)
	case string:
		return yamlScalarText(t)
	}
	return yamlScalarText(toString(v))
}

var yamlReserved = map[string]bool{
