	"2006-01-02t15:04:05.999999999Z07:00",
	"2006-01-02 15:04:05.999999999 -07:00",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02",
	"15:4",
	"15:04",
}

func yamlLooksLikeTime(s string) bool {
	for _, l := range yamlTimeLayouts {
		if _, err := time.Parse(l, s); err == nil {
			return true
		}
	}
	return false
}

func yamlNeedQuote(s string) bool {
	if s == "" {
		return true
	}
	if yamlReserved[s] {
		return true
	}
	if _, ok := yamlNumber(s); ok {
		return true
	}
	switch s[0] {
	case '*', '&', '[', '{', '}', ']', ',', '!', '|', '>', '%', '\'', '"', '@', ' ', '`', '#', '\t':
		return true
	}
	switch s[len(s)-1] {
	case ':', ' ', '\t':
		return true
	}
	if yamlLooksLikeTime(s) {
		return true
	}
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '#', '\\':
			return true
		case ':', '-':
			if i+1 < len(s) && s[i+1] == ' ' {
				return true
			}
		}
	}
	if s == "-" || s == "?" && false {
		return true
	}
	if strings.HasPrefix(s, "- ") || strings.HasPrefix(s, "? ") {
		return true
	}
	return false
}

func yamlScalarText(s string) string {
	if !yamlNeedQuote(s) {
		return s
	}
	return yamlDoubleQuote(s)
}

func yamlDoubleQuote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 || r == 0x7f {
				sb.WriteString(`\x`)
				sb.WriteString(hex.EncodeToString([]byte{byte(r)}))
				continue
			}
			if r == utf8.RuneError {
				sb.WriteRune(r)
				continue
			}
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}
