package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
	"unicode"
)

// guessWidth emulates column separation of printf-like output.
type guessWidth struct {
	reader   *bufio.Reader
	pos      []int
	preLines []string
	preCount int
	scanNum  int
	header   int
	minLines int
}

func (g *guessWidth) readLine() (string, error) {
	line, err := g.reader.ReadString('\n')
	if err != nil {
		if err == io.EOF && line != "" {
			return strings.TrimSuffix(line, "\r"), nil
		}
		return "", err
	}
	line = strings.TrimSuffix(line, "\n")
	return strings.TrimSuffix(line, "\r"), nil
}

func (g *guessWidth) scan(num int) {
	for i := 0; i < num; i++ {
		line, err := g.readLine()
		if err != nil {
			break
		}
		g.preLines = append(g.preLines, line)
	}
	g.pos = gwPositions(g.preLines, g.header, g.minLines)
}

func (g *guessWidth) read() ([]string, error) {
	var line string
	if g.preCount < len(g.preLines) {
		line = g.preLines[g.preCount]
		g.preCount++
	} else {
		l, err := g.readLine()
		if err != nil {
			return nil, err
		}
		line = l
	}
	return gwSplit(line, g.pos), nil
}

func gwPositions(lines []string, header int, minLines int) []int {
	var blanks []int
	for n, line := range lines {
		if n < header {
			continue
		}
		if n == header {
			blanks = gwLookupBlanks(strings.TrimSuffix(line, " "))
			continue
		}
		blanks = gwCountBlanks(blanks, strings.TrimSuffix(line, " "))
	}
	return gwPositionsFromBlanks(blanks, minLines)
}

func gwLookupBlanks(line string) []int {
	blanks := make([]int, 0, len(line))
	first := true
	for _, v := range line {
		if v == ' ' {
			if first {
				blanks = append(blanks, 0)
				continue
			}
			blanks = append(blanks, 1)
			continue
		}
		first = false
		blanks = append(blanks, 0)
		if runeWidth(v) == 2 {
			blanks = append(blanks, 0)
		}
	}
	return blanks
}

func gwCountBlanks(blanks []int, line string) []int {
	n := 0
	for _, v := range line {
		if n >= len(blanks) {
			break
		}
		if v == ' ' && blanks[n] > 0 {
			blanks[n]++
		}
		n++
		if runeWidth(v) == 2 {
			n++
		}
	}
	return blanks
}

func gwPositionsFromBlanks(blanks []int, minLines int) []int {
	max := 0
	p := 0
	var pos []int
	for i, v := range blanks {
		if v >= minLines {
			if v >= max {
				max = v
				p = i
			}
			continue
		}
		if v == 0 && max > 0 {
			pos = append(pos, p)
			max = 0
		}
	}
	return pos
}

func gwSeparatorPosition(lr []rune, p int, pos []int, n int) int {
	if unicode.IsSpace(lr[p]) {
		return p
	}
	f := p
	for f < len(lr) && !unicode.IsSpace(lr[f]) {
		f++
	}
	b := p
	for b > 0 && !unicode.IsSpace(lr[b]) {
		b--
	}
	if b == pos[n] {
		return f
	}
	if n < len(pos)-1 {
		if f == pos[n+1] {
			return b
		}
		if b == pos[n] {
			return f
		}
		if b > pos[n] && b < pos[n+1] {
			return b
		}
	}
	return f
}

func gwSplit(line string, pos []int) []string {
	n := 0
	start := 0
	columns := make([]string, len(pos)+1)
	lr := []rune(line)
	w := 0
	for p := 0; p < len(lr); p++ {
		if n > len(pos)-1 {
			start = p
			break
		}
		if pos[n] <= w {
			end := gwSeparatorPosition(lr, p, pos, n)
			if start > end {
				break
			}
			columns[n] = strings.TrimSpace(string(lr[start:end]))
			n++
			start = end
		}
		w += runeWidth(lr[p])
	}
	columns[n] = strings.TrimSpace(string(lr[start:]))
	return columns
}

type widthReader struct {
	gw      *guessWidth
	names   []string
	types   []string
	preRead [][]any
	opts    *ReadOpts
}

func newWidthReader(rd io.Reader, opts *ReadOpts) (Reader, error) {
	g := &guessWidth{reader: bufio.NewReaderSize(rd, 64*1024), scanNum: 100, header: opts.InSkip, minLines: 2}
	g.scan(g.scanNum)
	r := &widthReader{gw: g, opts: opts}
	for i := 0; i < opts.InSkip; i++ {
		if _, err := g.read(); err != nil {
			break
		}
	}
	header, err := g.read()
	if err != nil {
		if errors.Is(err, io.EOF) {
			return nil, errNoRows
		}
		return nil, err
	}
	r.names = make([]string, len(header))
	for i, h := range header {
		if h == "" {
			h = "c" + strconv.Itoa(i+1)
		}
		r.names[i] = h
	}
	r.types = textTypes(len(r.names))
	total := 0
	rows := 0
	for i := 0; i < opts.InPreRead; i++ {
		cols, err := g.read()
		if err != nil {
			if !errors.Is(err, io.EOF) {
				return nil, err
			}
			continue
		}
		rows++
		total += len(cols)
		row := make([]any, len(r.names))
		for j := range row {
			if j < len(cols) {
				row[j] = nullConv(opts, cols[j])
			}
		}
		r.preRead = append(r.preRead, row)
	}
	if rows < opts.InPreRead {
		limit := opts.InPreRead
		if opts.InLimitRead > 0 && opts.InLimitRead < limit {
			return r, nil
		}
		return nil, fmt.Errorf("sql: expected %d arguments, got %d", limit*len(r.names), total)
	}
	return r, nil
}

func (r *widthReader) Names() ([]string, error) { return r.names, nil }
func (r *widthReader) Types() ([]string, error) { return r.types, nil }
func (r *widthReader) PreReadRow() [][]any      { return r.preRead }
func (r *widthReader) ReadRow(row []any) ([]any, error) {
	cols, err := r.gw.read()
	if err != nil {
		return nil, err
	}
	out := make([]any, len(r.names))
	for j := range out {
		if j < len(cols) {
			out[j] = nullConv(r.opts, cols[j])
		}
	}
	return out, nil
}
