		v1 := seed + xxPrime32_1 + xxPrime32_2
		v2 := seed + xxPrime32_2
		v3 := seed
		v4 := seed - xxPrime32_1
		for ; p+16 <= n; p += 16 {
			v1 = bits.RotateLeft32(v1+binary.LittleEndian.Uint32(b[p:])*xxPrime32_2, 13) * xxPrime32_1
			v2 = bits.RotateLeft32(v2+binary.LittleEndian.Uint32(b[p+4:])*xxPrime32_2, 13) * xxPrime32_1
			v3 = bits.RotateLeft32(v3+binary.LittleEndian.Uint32(b[p+8:])*xxPrime32_2, 13) * xxPrime32_1
			v4 = bits.RotateLeft32(v4+binary.LittleEndian.Uint32(b[p+12:])*xxPrime32_2, 13) * xxPrime32_1
		}
		h = bits.RotateLeft32(v1, 1) + bits.RotateLeft32(v2, 7) + bits.RotateLeft32(v3, 12) + bits.RotateLeft32(v4, 18)
	} else {
		h = seed + xxPrime32_5
	}
	h += uint32(n)
	for ; p+4 <= n; p += 4 {
		h += binary.LittleEndian.Uint32(b[p:]) * xxPrime32_3
		h = bits.RotateLeft32(h, 17) * xxPrime32_4
	}
	for ; p < n; p++ {
		h += uint32(b[p]) * xxPrime32_5
		h = bits.RotateLeft32(h, 11) * xxPrime32_1
	}
	h ^= h >> 15
	h *= xxPrime32_2
	h ^= h >> 13
	h *= xxPrime32_3
	h ^= h >> 16
	return h
}

// ---- zstd (raw blocks) ----

func zstdStore(data []byte) []byte {
	var out bytes.Buffer
	out.Write([]byte{0x28, 0xb5, 0x2f, 0xfd})
	out.WriteByte(0x04) // checksum flag
	wlog := 10
	for (1<<wlog) < len(data) && wlog < 22 {
		wlog++
	}
	out.WriteByte(byte((wlog - 10) << 3))
	const maxBlock = 128 << 10
	rest := data
	for {
		n := len(rest)
		if n > maxBlock {
			n = maxBlock
		}
		last := 0
		if n == len(rest) {
			last = 1
		}
		hdr := uint32(n<<3) | uint32(last)
		out.Write([]byte{byte(hdr), byte(hdr >> 8), byte(hdr >> 16)})
		out.Write(rest[:n])
		rest = rest[n:]
		if last == 1 {
			break
		}
	}
	sum := uint32(xxhash64(data, 0))
	var b [4]byte
	binary.LittleEndian.PutUint32(b[:], sum)
	out.Write(b[:])
	return out.Bytes()
}

// ---- lz4 frame (uncompressed blocks) ----

func lz4Store(data []byte) []byte {
	var out bytes.Buffer
	out.Write([]byte{0x04, 0x22, 0x4d, 0x18})
	desc := []byte{0x64, 0x70}
	out.Write(desc)
	out.WriteByte(byte(xxhash32(desc, 0) >> 8))
	const maxBlock = 4 << 20
	rest := data
	var b [4]byte
	for len(rest) > 0 {
		n := len(rest)
		if n > maxBlock {
			n = maxBlock
		}
		binary.LittleEndian.PutUint32(b[:], uint32(n)|0x80000000)
		out.Write(b[:])
		out.Write(rest[:n])
		rest = rest[n:]
	}
	out.Write([]byte{0, 0, 0, 0})
	binary.LittleEndian.PutUint32(b[:], xxhash32(data, 0))
	out.Write(b[:])
	return out.Bytes()
}

// ---- xz (LZMA2 uncompressed chunks) ----

func xzVarint(buf *bytes.Buffer, v uint64) {
	for v >= 0x80 {
		buf.WriteByte(byte(v) | 0x80)
		v >>= 7
	}
	buf.WriteByte(byte(v))
}

func xzStore(data []byte) []byte {
	var out bytes.Buffer
	crcTab := crc64.MakeTable(crc64.ECMA)
	le32 := func(v uint32) []byte {
		var b [4]byte
		binary.LittleEndian.PutUint32(b[:], v)
		return b[:]
	}
	// stream header
	out.Write([]byte{0xfd, '7', 'z', 'X', 'Z', 0x00})
	flags := []byte{0x00, 0x04}
	out.Write(flags)
	out.Write(le32(crc32.ChecksumIEEE(flags)))
	// block header
	bh := []byte{0x02, 0x00, 0x21, 0x01, 0x16, 0x00, 0x00, 0x00}
	blockStart := out.Len()
	out.Write(bh)
	out.Write(le32(crc32.ChecksumIEEE(bh)))
	// LZMA2 chunks
	rest := data
	first := true
	for len(rest) > 0 {
		n := len(rest)
		if n > 1<<16 {
			n = 1 << 16
		}
		if first {
			out.WriteByte(0x01)
			first = false
		} else {
			out.WriteByte(0x02)
		}
		out.WriteByte(byte((n - 1) >> 8))
		out.WriteByte(byte(n - 1))
		out.Write(rest[:n])
		rest = rest[n:]
	}
	out.WriteByte(0x00)
	unpadded := out.Len() - blockStart
	for (out.Len()-blockStart)%4 != 0 {
		out.WriteByte(0)
	}
	var cb [8]byte
	binary.LittleEndian.PutUint64(cb[:], crc64.Checksum(data, crcTab))
	out.Write(cb[:])
	unpadded += 8
	// index
	var idx bytes.Buffer
	idx.WriteByte(0x00)
	xzVarint(&idx, 1)
	xzVarint(&idx, uint64(unpadded))
	xzVarint(&idx, uint64(len(data)))
	for idx.Len()%4 != 0 {
		idx.WriteByte(0)
	}
	idxBytes := idx.Bytes()
	out.Write(idxBytes)
	out.Write(le32(crc32.ChecksumIEEE(idxBytes)))
	// footer
	backward := uint32((len(idxBytes)+4)/4 - 1)
	foot := append(le32(backward), flags...)
	out.Write(le32(crc32.ChecksumIEEE(foot)))
	out.Write(foot)
	out.Write([]byte{'Y', 'Z'})
	return out.Bytes()
}
