		if magic&0xfffffff0 == 0x184d2a50 { // skippable frame
			if len(data) < 8 {
				return nil, errLz4
			}
			n := int(binary.LittleEndian.Uint32(data[4:]))
			if len(data) < 8+n {
				return nil, errLz4
			}
			data = data[8+n:]
			continue
		}
		if magic != 0x184d2204 {
			return nil, errLz4
		}
		data = data[4:]
		if len(data) < 3 {
			return nil, errLz4
		}
		flg := data[0]
		hdrLen := 3
		if flg&0x08 != 0 {
			hdrLen += 8
		}
		if flg&0x01 != 0 {
			hdrLen += 4
		}
		if len(data) < hdrLen {
			return nil, errLz4
		}
		blockChecksum := flg&0x10 != 0
		contentChecksum := flg&0x04 != 0
		data = data[hdrLen:]
		frameStart := out.Len()
		for {
			if len(data) < 4 {
				return nil, errLz4
			}
			bs := binary.LittleEndian.Uint32(data)
			data = data[4:]
			if bs == 0 {
				break
			}
			size := int(bs & 0x7fffffff)
			if len(data) < size {
				return nil, errLz4
			}
			block := data[:size]
			data = data[size:]
			if bs&0x80000000 != 0 {
				out.Write(block)
			} else {
				if err := lz4DecodeBlock(&out, block, frameStart); err != nil {
					return nil, err
				}
			}
			if blockChecksum {
				if len(data) < 4 {
					return nil, errLz4
				}
				data = data[4:]
			}
		}
		if contentChecksum {
			if len(data) < 4 {
				return nil, errLz4
			}
			data = data[4:]
		}
	}
	return bytes.NewReader(out.Bytes()), nil
}

func lz4DecodeBlock(out *bytes.Buffer, src []byte, frameStart int) error {
	i := 0
	for i < len(src) {
		token := src[i]
		i++
		lit := int(token >> 4)
		if lit == 15 {
			for {
				if i >= len(src) {
					return errLz4
				}
				b := src[i]
				i++
				lit += int(b)
				if b != 255 {
					break
				}
			}
		}
		if i+lit > len(src) {
			return errLz4
		}
		out.Write(src[i : i+lit])
		i += lit
		if i >= len(src) {
			break
		}
		if i+2 > len(src) {
			return errLz4
		}
		offset := int(src[i]) | int(src[i+1])<<8
		i += 2
		if offset == 0 {
			return errLz4
		}
		ml := int(token & 15)
		if ml == 15 {
			for {
				if i >= len(src) {
					return errLz4
				}
				b := src[i]
				i++
				ml += int(b)
				if b != 255 {
					break
				}
			}
		}
		ml += 4
		buf := out.Bytes()
		start := len(buf) - offset
		if start < 0 {
			return errLz4
		}
		for k := 0; k < ml; k++ {
			out.WriteByte(out.Bytes()[start+k])
		}
	}
	return nil
}
