package main

import (
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
)

func sqlText(v sqlValue) (string, bool) {
	switch t := v.(type) {
	case nil:
		return "", false
	case string:
		return t, true
	case []byte:
		return string(t), true
	case int64:
		return strconv.FormatInt(t, 10), true
	case float64:
		return sqliteFloatText(t), true
	}
	return "", false
}

// sqliteFloatText formats a float like SQLite's text conversion (%!.15g).
func sqliteFloatText(f float64) string {
	if math.IsInf(f, 1) {
		return "Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	s := strconv.FormatFloat(f, 'g', 15, 64)
	if strings.ContainsAny(s, "e") {
		mant, exp, _ := strings.Cut(s, "e")
		if !strings.Contains(mant, ".") {
			mant += ".0"
		}
		sign := exp[0]
		digits := strings.TrimLeft(exp[1:], "0")
		if len(digits) < 2 {
			digits = strings.Repeat("0", 2-len(digits)) + digits
		}
		return mant + "e" + string(sign) + digits
	}
	if !strings.Contains(s, ".") {
		s += ".0"
	}
	return s
}

func sqlFloat(v sqlValue) (float64, bool) {
	switch t := v.(type) {
	case int64:
		return float64(t), true
	case float64:
		return t, true
	case string:
		f, err := strconv.ParseFloat(strings.TrimSpace(t), 64)
		if err != nil {
			return 0, true
		}
		return f, true
	case []byte:
		f, err := strconv.ParseFloat(strings.TrimSpace(string(t)), 64)
		if err != nil {
			return 0, true
		}
		return f, true
	}
	return 0, false
}

// queryScalar runs a single-value query on the same connection.
func (d *DB) queryScalar(q string, args ...sqlValue) (sqlValue, error) {
	st, _, err := d.Prepare(q)
	if err != nil {
		return nil, err
	}
	if st == nil {
		return nil, nil
	}
	defer st.Finalize()
	for i, a := range args {
		if err := st.Bind(i+1, a); err != nil {
			return nil, err
		}
	}
	has, err := st.Step()
	if err != nil {
		return nil, err
	}
	if !has {
		return nil, nil
	}
	return st.Column(0), nil
}

func placeholders(n int) string {
	return strings.TrimSuffix(strings.Repeat("?,", n), ",")
}

func registerCompatFunctions(db *DB) {
	db.RegisterScalar("concat", -1, true, func(args []sqlValue) (sqlValue, error) {
		if len(args) == 0 {
			return nil, errors.New("wrong number of arguments to function concat()")
		}
		var sb strings.Builder
		for _, a := range args {
			if s, ok := sqlText(a); ok {
				sb.WriteString(s)
			}
		}
		return sb.String(), nil
	})
	db.RegisterScalar("concat_ws", -1, true, func(args []sqlValue) (sqlValue, error) {
		if len(args) < 2 {
			return nil, errors.New("wrong number of arguments to function concat_ws()")
		}
		sep, ok := sqlText(args[0])
		if !ok {
			return nil, nil
		}
		var parts []string
		for _, a := range args[1:] {
			if s, ok := sqlText(a); ok {
				parts = append(parts, s)
			}
		}
		return strings.Join(parts, sep), nil
	})
	db.RegisterScalar("unixepoch", -1, false, func(args []sqlValue) (sqlValue, error) {
		if len(args) == 0 {
			args = []sqlValue{"now"}
		}
		v, err := db.queryScalar("SELECT CAST(strftime('%s',"+placeholders(len(args))+") AS INTEGER)", args...)
		if err != nil {
			return nil, err
		}
		if s, ok := v.(int64); ok {
			return s, nil
		}
		return v, nil
	})
	db.RegisterScalar("format", -1, true, func(args []sqlValue) (sqlValue, error) {
		if len(args) == 0 {
			return nil, nil
		}
		return db.queryScalar("SELECT printf("+placeholders(len(args))+")", args...)
	})
	db.RegisterScalar("unhex", -1, true, func(args []sqlValue) (sqlValue, error) {
		if len(args) < 1 || len(args) > 2 {
			return nil, errors.New("wrong number of arguments to function unhex()")
		}
		s, ok := sqlText(args[0])
		if !ok {
			return nil, nil
		}
		ignore := ""
		if len(args) == 2 {
			ignore, _ = sqlText(args[1])
		}
		var clean strings.Builder
		for _, r := range s {
			if strings.ContainsRune(ignore, r) {
				continue
			}
			clean.WriteRune(r)
		}
		b, err := hex.DecodeString(clean.String())
		if err != nil {
			return nil, nil
		}
		return b, nil
	})
	db.RegisterScalar("octet_length", 1, true, func(args []sqlValue) (sqlValue, error) {
		switch t := args[0].(type) {
		case nil:
			return nil, nil
		case []byte:
			return int64(len(t)), nil
		}
		s, _ := sqlText(args[0])
		return int64(len(s)), nil
	})
	db.RegisterAggregate("string_agg", 2, func() aggState { return &stringAgg{} })
	db.RegisterScalar("soundex", 1, true, func(args []sqlValue) (sqlValue, error) {
		return nil, errors.New("no such function: soundex")
	})
}

type stringAgg struct {
	parts []string
	seps  []string
	any   bool
}

func (s *stringAgg) Step(args []sqlValue) {
	v, ok := sqlText(args[0])
	if !ok {
		return
	}
	sep, _ := sqlText(args[1])
	s.parts = append(s.parts, v)
	s.seps = append(s.seps, sep)
	s.any = true
}

func (s *stringAgg) Final() (sqlValue, error) {
	if !s.any {
		return nil, nil
	}
	var sb strings.Builder
	for i, p := range s.parts {
		if i > 0 {
			sb.WriteString(s.seps[i])
		}
		sb.WriteString(p)
	}
	return sb.String(), nil
}

// ---- sqlite3_ext functions ----

var regexpCache sync.Map

func compileRegexp(p string) (*regexp.Regexp, error) {
	if v, ok := regexpCache.Load(p); ok {
		return v.(*regexp.Regexp), nil
	}
	re, err := regexp.Compile(p)
	if err != nil {
		return nil, err
	}
	regexpCache.Store(p, re)
	return re, nil
}

type numAgg struct {
	vals []float64
	kind string
	p    float64
	pSet bool
