package main

import (
	"errors"
	"net"
	"net/url"
	"os"
	"strings"
	"time"
)

// dialRemote tries to connect to the database server and returns the connection error.
func dialRemote(driver, dsn string) error {
	var network, addr string
	switch driver {
	case "postgres":
		host, port := "localhost", "5432"
		if env := os.Getenv("PGHOST"); env != "" {
			host = env
		}
		if env := os.Getenv("PGPORT"); env != "" {
			port = env
		}
		if strings.HasPrefix(dsn, "postgres://") || strings.HasPrefix(dsn, "postgresql://") {
			if u, err := url.Parse(dsn); err == nil {
				if h := u.Hostname(); h != "" {
					host = h
				}
				if p := u.Port(); p != "" {
					port = p
				}
				if h := u.Query().Get("host"); h != "" {
					host = h
				}
			}
		} else {
			for _, kv := range strings.Fields(dsn) {
				k, v, ok := strings.Cut(kv, "=")
				if !ok {
					continue
				}
				v = strings.Trim(v, "'")
				switch k {
				case "host":
					host = v
				case "port":
					port = v
				}
			}
		}
		if strings.HasPrefix(host, "/") {
			network, addr = "unix", host+"/.s.PGSQL."+port
		} else {
			network, addr = "tcp", net.JoinHostPort(host, port)
		}
	case "mysql":
		network, addr = "tcp", "127.0.0.1:3306"
		if i := strings.Index(dsn, "@"); i >= 0 {
			rest := dsn[i+1:]
			if j := strings.Index(rest, "("); j >= 0 {
				proto := rest[:j]
				if k := strings.Index(rest[j:], ")"); k >= 0 {
					a := rest[j+1 : j+k]
					if proto != "" {
						network = proto
					}
					if a != "" {
						addr = a
						if network == "tcp" && !strings.Contains(addr, ":") {
							addr += ":3306"
						}
					}
				}
			}
		}
	default:
		return errors.New("unknown driver")
	}
	conn, err := net.DialTimeout(network, addr, 5*time.Second)
	if err != nil {
		return err
	}
	conn.Close()
	return errors.New("unexpected server response")
}
