var errXz = errors.New("xz: invalid data")

// ---- LZMA decoder ----

type rangeDecoder struct {
	data []byte
	pos  int
	rng  uint32
	code uint32
	err  bool
}

func (rd *rangeDecoder) init(data []byte) bool {
	rd.data = data
	rd.pos = 0
	rd.rng = 0xFFFFFFFF
	rd.code = 0
	if len(data) < 5 || data[0] != 0 {
		return false
	}
	for i := 1; i < 5; i++ {
		rd.code = rd.code<<8 | uint32(data[i])
	}
	rd.pos = 5
	return rd.code != rd.rng
}

func (rd *rangeDecoder) next() byte {
	if rd.pos >= len(rd.data) {
		rd.err = true
		return 0
	}
	b := rd.data[rd.pos]
	rd.pos++
	return b
}

func (rd *rangeDecoder) normalize() {
	if rd.rng < 1<<24 {
		rd.rng <<= 8
		rd.code = rd.code<<8 | uint32(rd.next())
	}
}

func (rd *rangeDecoder) bit(prob *uint16) uint32 {
	bound := (rd.rng >> 11) * uint32(*prob)
	var b uint32
	if rd.code < bound {
		*prob += (2048 - *prob) >> 5
		rd.rng = bound
		b = 0
	} else {
		*prob -= *prob >> 5
		rd.code -= bound
		rd.rng -= bound
		b = 1
	}
	rd.normalize()
	return b
}

func (rd *rangeDecoder) direct(n int) uint32 {
	var res uint32
	for ; n > 0; n-- {
		rd.rng >>= 1
		rd.code -= rd.rng
		t := 0 - (rd.code >> 31)
		rd.code += rd.rng & t
		res = res<<1 + (t + 1)
		rd.normalize()
	}
	return res
}

func initProbs(p []uint16) {
	for i := range p {
		p[i] = 1024
	}
}

func bitTree(rd *rangeDecoder, probs []uint16, numBits int) uint32 {
	m := uint32(1)
	for i := 0; i < numBits; i++ {
		m = m<<1 + rd.bit(&probs[m])
	}
	return m - (1 << numBits)
}

func bitTreeReverse(rd *rangeDecoder, probs []uint16, numBits int) uint32 {
	m := uint32(1)
	var sym uint32
	for i := 0; i < numBits; i++ {
		b := rd.bit(&probs[m])
		m = m<<1 + b
		sym |= b << i
	}
	return sym
}

type lenDecoder struct {
	choice, choice2 uint16
	low             [16][8]uint16
	mid             [16][8]uint16
	high            [256]uint16
}

func (l *lenDecoder) init() {
	l.choice, l.choice2 = 1024, 1024
	for i := range l.low {
		initProbs(l.low[i][:])
		initProbs(l.mid[i][:])
	}
	initProbs(l.high[:])
}

func (l *lenDecoder) decode(rd *rangeDecoder, posState uint32) uint32 {
	if rd.bit(&l.choice) == 0 {
		return bitTree(rd, l.low[posState][:], 3)
	}
	if rd.bit(&l.choice2) == 0 {
		return 8 + bitTree(rd, l.mid[posState][:], 3)
	}
	return 16 + bitTree(rd, l.high[:], 8)
}

type lzmaState struct {
	lc, lp, pb   uint
	literal      []uint16
	isMatch      [12 << 4]uint16
	isRep        [12]uint16
	isRepG0      [12]uint16
	isRepG1      [12]uint16
	isRepG2      [12]uint16
	isRep0Long   [12 << 4]uint16
	posSlot      [4][64]uint16
	posDecoders  [115]uint16
	align        [16]uint16
	lenDec       lenDecoder
	repLenDec    lenDecoder
	state        uint32
	rep          [4]uint32
	out          []byte // whole output (dictionary = all output since dict reset)
	dictStart    int
	pendingLen   int
}

func (s *lzmaState) setProps(b byte) bool {
	if b >= 9*5*5 {
		return false
	}
	d := uint(b)
	s.lc = d % 9
	d /= 9
	s.lp = d % 5
	s.pb = d / 5
	return true
}

func (s *lzmaState) reset() {
	s.literal = make([]uint16, 0x300<<(s.lc+s.lp))
	initProbs(s.literal)
	initProbs(s.isMatch[:])
	initProbs(s.isRep[:])
	initProbs(s.isRepG0[:])
	initProbs(s.isRepG1[:])
	initProbs(s.isRepG2[:])
	initProbs(s.isRep0Long[:])
	for i := range s.posSlot {
		initProbs(s.posSlot[i][:])
	}
	initProbs(s.posDecoders[:])
	initProbs(s.align[:])
	s.lenDec.init()
	s.repLenDec.init()
	s.state = 0
	s.rep = [4]uint32{}
}

func (s *lzmaState) getByte(dist uint32) byte {
	return s.out[len(s.out)-int(dist)]
}

// decode decodes up to unpacked bytes from rd. If unpacked < 0, decode until end marker or data end.
func (s *lzmaState) decode(rd *rangeDecoder, unpacked int, allowEOS bool) error {
	target := len(s.out) + unpacked
	pbMask := uint32(1)<<s.pb - 1
	lpMask := uint32(1)<<s.lp - 1
	for unpacked < 0 || len(s.out) < target {
		if rd.err {
			return errXz
		}
		posState := uint32(len(s.out)-s.dictStart) & pbMask
		if rd.bit(&s.isMatch[s.state<<4+posState]) == 0 {
			prev := uint32(0)
			if len(s.out) > s.dictStart {
				prev = uint32(s.out[len(s.out)-1])
			}
			litState := ((uint32(len(s.out)-s.dictStart) & lpMask) << s.lc) + (prev >> (8 - s.lc))
			probs := s.literal[0x300*litState:]
			sym := uint32(1)
			if s.state >= 7 {
				matchByte := uint32(s.getByte(s.rep[0] + 1))
				for sym < 0x100 {
					matchBit := (matchByte >> 7) & 1
					matchByte <<= 1
					b := rd.bit(&probs[((1+matchBit)<<8)+sym])
					sym = sym<<1 | b
					if matchBit != b {
						break
					}
				}
			}
			for sym < 0x100 {
				sym = sym<<1 | rd.bit(&probs[sym])
			}
			s.out = append(s.out, byte(sym-0x100))
			switch {
			case s.state < 4:
				s.state = 0
			case s.state < 10:
				s.state -= 3
			default:
				s.state -= 6
			}
			continue
		}
		var length uint32
		if rd.bit(&s.isRep[s.state]) != 0 {
			if len(s.out) == s.dictStart {
				return errXz
			}
			if rd.bit(&s.isRepG0[s.state]) == 0 {
				if rd.bit(&s.isRep0Long[s.state<<4+posState]) == 0 {
					if s.state < 7 {
						s.state = 9
					} else {
						s.state = 11
					}
					s.out = append(s.out, s.getByte(s.rep[0]+1))
					continue
				}
			} else {
				var dist uint32
				if rd.bit(&s.isRepG1[s.state]) == 0 {
					dist = s.rep[1]
				} else {
					if rd.bit(&s.isRepG2[s.state]) == 0 {
						dist = s.rep[2]
					} else {
						dist = s.rep[3]
						s.rep[3] = s.rep[2]
					}
					s.rep[2] = s.rep[1]
				}
				s.rep[1] = s.rep[0]
				s.rep[0] = dist
			}
			length = s.repLenDec.decode(rd, posState)
			if s.state < 7 {
				s.state = 8
			} else {
				s.state = 11
			}
		} else {
			s.rep[3] = s.rep[2]
			s.rep[2] = s.rep[1]
			s.rep[1] = s.rep[0]
			length = s.lenDec.decode(rd, posState)
			if s.state < 7 {
				s.state = 7
			} else {
				s.state = 10
			}
			lenState := length
			if lenState > 3 {
				lenState = 3
			}
			posSlot := bitTree(rd, s.posSlot[lenState][:], 6)
			var dist uint32
			if posSlot < 4 {
				dist = posSlot
			} else {
				numDirect := int(posSlot>>1) - 1
				dist = (2 | (posSlot & 1)) << numDirect
				if posSlot < 14 {
					dist += bitTreeReverse(rd, s.posDecoders[dist-posSlot:], numDirect)
				} else {
					dist += rd.direct(numDirect-4) << 4
					dist += bitTreeReverse(rd, s.align[:], 4)
				}
				if dist == 0xFFFFFFFF {
					if allowEOS {
						return nil
					}
					return errXz
				}
			}
			s.rep[0] = dist
		}
		length += 2
		if int(s.rep[0]) >= len(s.out)-s.dictStart {
			return errXz
		}
		start := len(s.out) - int(s.rep[0]) - 1
		for i := 0; i < int(length); i++ {
			if unpacked >= 0 && len(s.out) >= target {
				return errXz
			}
			s.out = append(s.out, s.out[start+i])
		}
	}
	return nil
}

// decodeLZMA2 decodes LZMA2 data, appending to out.
func decodeLZMA2(data []byte, out []byte) ([]byte, int, error) {
	s := &lzmaState{out: out, dictStart: len(out)}
	pos := 0
	needProps := true
	for {
		if pos >= len(data) {
			return nil, 0, errXz
		}
		ctrl := data[pos]
		pos++
		if ctrl == 0 {
			return s.out, pos, nil
		}
		if ctrl == 1 || ctrl == 2 {
			if pos+2 > len(data) {
				return nil, 0, errXz
			}
			size := int(data[pos])<<8 | int(data[pos+1]) + 1
			pos += 2
			if pos+size > len(data) {
				return nil, 0, errXz
			}
			if ctrl == 1 {
				s.dictStart = len(s.out)
			}
			s.out = append(s.out, data[pos:pos+size]...)
			pos += size
			continue
		}
		if ctrl < 0x80 {
			return nil, 0, errXz
		}
		if pos+4 > len(data) {
			return nil, 0, errXz
		}
		unpacked := int(ctrl&0x1F)<<16 | int(data[pos])<<8 | int(data[pos+1]) + 1
		packed := int(data[pos+2])<<8 | int(data[pos+3]) + 1
		pos += 4
		mode := (ctrl >> 5) & 3
		if mode == 3 {
			s.dictStart = len(s.out)
		}
		if mode >= 2 {
			if pos >= len(data) || !s.setProps(data[pos]) {
				return nil, 0, errXz
			}
			pos++
			needProps = false
		} else if needProps {
			return nil, 0, errXz
		}
		if mode >= 1 {
			s.reset()
		}
		if pos+packed > len(data) {
			return nil, 0, errXz
		}
		rd := &rangeDecoder{}
		if !rd.init(data[pos : pos+packed]) && packed >= 5 && data[pos] != 0 {
			return nil, 0, errXz
		}
		if err := s.decode(rd, unpacked, false); err != nil {
			return nil, 0, err
		}
		pos += packed
	}
}

func readXzVarint(b []byte) (uint64, int) {
	var v uint64
	for i := 0; i < len(b) && i < 9; i++ {
		v |= uint64(b[i]&0x7f) << (7 * i)
		if b[i]&0x80 == 0 {
			return v, i + 1
		}
	}
	return 0, -1
}

func newXzReader(r io.Reader) (io.Reader, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	var out []byte
	pos := 0
	for pos < len(data) {
		// stream padding
		if data[pos] == 0 {
			pos++
			continue
		}
		if pos+12 > len(data) || !bytes.Equal(data[pos:pos+6], []byte{0xfd, '7', 'z', 'X', 'Z', 0}) {
			return nil, errXz
		}
		checkType := data[pos+7] & 0x0f
		checkSize := map[byte]int{0: 0, 1: 4, 4: 8, 10: 32}[checkType]
		if checkType != 0 && checkSize == 0 {
			checkSize = 4 << ((checkType - 1) / 3)
		}
		pos += 12
		for {
			if pos >= len(data) {
				return nil, errXz
			}
			if data[pos] == 0 {
				// index
				p := pos + 1
				n, l := readXzVarint(data[p:])
				if l < 0 {
					return nil, errXz
				}
				p += l
				for i := uint64(0); i < n; i++ {
					_, l1 := readXzVarint(data[p:])
					if l1 < 0 {
						return nil, errXz
					}
					p += l1
					_, l2 := readXzVarint(data[p:])
					if l2 < 0 {
						return nil, errXz
					}
					p += l2
				}
				for (p-pos)%4 != 0 {
					p++
				}
				p += 4  // crc32
				p += 12 // footer
				pos = p
				break
			}
			hsize := (int(data[pos]) + 1) * 4
			if pos+hsize > len(data) {
				return nil, errXz
			}
			hdr := data[pos : pos+hsize]
			flags := hdr[1]
			nfilters := int(flags&3) + 1
			p := 2
			if flags&0x40 != 0 {
				_, l := readXzVarint(hdr[p:])
				if l < 0 {
					return nil, errXz
				}
				p += l
			}
			if flags&0x80 != 0 {
				_, l := readXzVarint(hdr[p:])
				if l < 0 {
					return nil, errXz
				}
				p += l
			}
			var filterIDs []uint64
			var deltaDist int
			for f := 0; f < nfilters; f++ {
				id, l := readXzVarint(hdr[p:])
				if l < 0 {
					return nil, errXz
				}
				p += l
				psz, l2 := readXzVarint(hdr[p:])
				if l2 < 0 {
					return nil, errXz
				}
				p += l2
				if id == 0x03 && psz >= 1 {
					deltaDist = int(hdr[p]) + 1
				}
				p += int(psz)
				filterIDs = append(filterIDs, id)
			}
			if filterIDs[len(filterIDs)-1] != 0x21 {
				return nil, errXz
			}
			pos += hsize
			start := len(out)
			res, used, err := decodeLZMA2(data[pos:], out)
			if err != nil {
				return nil, err
			}
			out = res
			for i := len(filterIDs) - 2; i >= 0; i-- {
				switch filterIDs[i] {
				case 0x03:
					blk := out[start:]
					for j := deltaDist; j < len(blk); j++ {
						blk[j] += blk[j-deltaDist]
					}
				default:
					return nil, errXz
				}
			}
			pos += used
			for (pos)%4 != 0 {
				pos++
			}
			pos += checkSize
		}
	}
	_ = binary.LittleEndian
	return bytes.NewReader(out), nil
}
