// ---- forward bit reader (for FSE table descriptions) ----

type fwdBits struct {
	data []byte
	pos  int // bit position
}

func (f *fwdBits) peek(n int) uint32 {
	var v uint32
	for i := 0; i < n; i++ {
		p := f.pos + i
		if p/8 < len(f.data) && f.data[p/8]&(1<<(p%8)) != 0 {
			v |= 1 << i
		}
	}
	return v
}

func (f *fwdBits) read(n int) uint32 {
	v := f.peek(n)
	f.pos += n
	return v
}

// ---- backward bit reader ----

type bwdBits struct {
	data     []byte
	pos      int // number of unread bits
	overflow bool
}

func newBwdBits(data []byte) (*bwdBits, error) {
	if len(data) == 0 {
		return nil, errZstd
	}
	last := data[len(data)-1]
	if last == 0 {
		return nil, errZstd
	}
	hb := 7 - bits.LeadingZeros8(last)
	return &bwdBits{data: data, pos: (len(data)-1)*8 + hb}, nil
}

func (b *bwdBits) bit(p int) uint32 {
	if p < 0 {
		return 0
	}
	if b.data[p/8]&(1<<(p%8)) != 0 {
		return 1
	}
	return 0
}

func (b *bwdBits) read(n int) uint32 {
	if n == 0 {
		return 0
	}
	var v uint32
	start := b.pos - n
	for k := 0; k < n; k++ {
		v |= b.bit(start+k) << k
	}
	b.pos -= n
	if b.pos < 0 {
		b.overflow = true
	}
	return v
}

func (b *bwdBits) peek(n int) uint32 {
	var v uint32
	start := b.pos - n
	for k := 0; k < n; k++ {
		v |= b.bit(start+k) << k
	}
	return v
