// ---- FSE ----

type fseEntry struct {
	sym      uint16
	nbBits   uint8
	baseline uint16
}

type fseTable struct {
	accuracy int
	entries  []fseEntry
}

func buildFSE(counts []int16, accuracy int) (*fseTable, error) {
	size := 1 << accuracy
	t := &fseTable{accuracy: accuracy, entries: make([]fseEntry, size)}
	high := size - 1
	next := make([]int, len(counts))
	for s, c := range counts {
		if c == -1 {
			t.entries[high].sym = uint16(s)
			high--
			next[s] = 1
		} else {
			next[s] = int(c)
		}
	}
	step := (size >> 1) + (size >> 3) + 3
	mask := size - 1
	pos := 0
	for s, c := range counts {
		for i := 0; i < int(c); i++ {
			t.entries[pos].sym = uint16(s)
			pos = (pos + step) & mask
			for pos > high {
				pos = (pos + step) & mask
			}
		}
	}
	if pos != 0 {
		return nil, errZstd
	}
	for u := 0; u < size; u++ {
		s := t.entries[u].sym
		ns := next[s]
		next[s]++
		nb := accuracy - (bits.Len(uint(ns)) - 1)
		t.entries[u].nbBits = uint8(nb)
		t.entries[u].baseline = uint16((ns << nb) - size)
	}
	return t, nil
}

func readFSETable(data []byte, maxSym int, maxAccuracy int) (*fseTable, int, error) {
	f := &fwdBits{data: data}
	accuracy := int(f.read(4)) + 5
	if accuracy > maxAccuracy {
		return nil, 0, errZstd
	}
	remaining := (1 << accuracy) + 1
	threshold := 1 << accuracy
	nbBits := accuracy + 1
	var counts []int16
	for remaining > 1 && len(counts) <= maxSym {
		max := (2*threshold - 1) - remaining
		var count int
		low := int(f.peek(nbBits - 1))
		if low < max {
			count = low
			f.pos += nbBits - 1
		} else {
			count = int(f.peek(nbBits))
			if count >= threshold {
				count -= max
			}
			f.pos += nbBits
		}
		count--
		if count < 0 {
			remaining--
		} else {
			remaining -= count
		}
		counts = append(counts, int16(count))
		if count == 0 {
			for {
				r := int(f.read(2))
				for i := 0; i < r; i++ {
					counts = append(counts, 0)
				}
				if r != 3 {
					break
				}
			}
		}
		for remaining < threshold && threshold > 1 {
			nbBits--
			threshold >>= 1
		}
		if f.pos > len(data)*8 {
			return nil, 0, errZstd
		}
	}
	if remaining != 1 || len(counts) > maxSym+1 {
		return nil, 0, errZstd
	}
	t, err := buildFSE(counts, accuracy)
	if err != nil {
		return nil, 0, err
	}
	return t, (f.pos + 7) / 8, nil
}

