func buildHuffman(weights []uint8) (*hufTable, error) {
	total := 0
	for _, w := range weights {
		if w > 0 {
			total += 1 << (w - 1)
		}
	}
	if total == 0 {
		return nil, errZstd
	}
	maxBits := bits.Len(uint(total))
	rest := (1 << maxBits) - total
	if rest <= 0 || rest&(rest-1) != 0 {
		return nil, errZstd
	}
	lastW := uint8(bits.Len(uint(rest)))
	weights = append(weights, lastW)
	if maxBits > 11 {
		return nil, errZstd
	}
	size := 1 << maxBits
	h := &hufTable{maxBits: maxBits, sym: make([]byte, size), nb: make([]uint8, size)}
	// assign codes: process by weight ascending (longest codes first)
	pos := 0
	for w := uint8(1); w <= uint8(maxBits); w++ {
		for s, sw := range weights {
			if sw != w {
				continue
			}
			nb := maxBits + 1 - int(w)
			n := 1 << (maxBits - nb)
			for i := 0; i < n; i++ {
				h.sym[pos+i] = byte(s)
				h.nb[pos+i] = uint8(nb)
			}
			pos += n
		}
	}
	if pos != size {
		return nil, errZstd
	}
	return h, nil
}

func readHuffmanTree(data []byte) (*hufTable, int, error) {
	if len(data) == 0 {
		return nil, 0, errZstd
