	hb := int(data[0])
	var weights []uint8
	used := 0
	if hb >= 128 {
		n := hb - 127
		nbytes := (n + 1) / 2
		if 1+nbytes > len(data) {
			return nil, 0, errZstd
		}
		for i := 0; i < n; i++ {
			b := data[1+i/2]
			if i%2 == 0 {
				weights = append(weights, b>>4)
			} else {
				weights = append(weights, b&15)
			}
		}
		used = 1 + nbytes
	} else {
		if 1+hb > len(data) {
			return nil, 0, errZstd
		}
		src := data[1 : 1+hb]
		t, n, err := readFSETable(src, 255, 6)
		if err != nil {
			return nil, 0, err
		}
		br, err := newBwdBits(src[n:])
		if err != nil {
			return nil, 0, err
		}
		s1 := br.read(t.accuracy)
		s2 := br.read(t.accuracy)
		for len(weights) < 255 {
			e := t.entries[s1]
			weights = append(weights, uint8(e.sym))
			s1 = uint32(e.baseline) + br.read(int(e.nbBits))
			if br.overflow {
				weights = append(weights, uint8(t.entries[s2].sym))
				break
			}
			e = t.entries[s2]
			weights = append(weights, uint8(e.sym))
			s2 = uint32(e.baseline) + br.read(int(e.nbBits))
			if br.overflow {
				weights = append(weights, uint8(t.entries[s1].sym))
				break
			}
		}
		used = 1 + hb
	}
	h, err := buildHuffman(weights)
	if err != nil {
		return nil, 0, err
	}
	return h, used, nil
}

func hufDecodeStream(h *hufTable, data []byte, n int, out []byte) ([]byte, error) {
	br, err := newBwdBits(data)
	if err != nil {
		return nil, err
	}
	for i := 0; i < n; i++ {
		v := br.peek(h.maxBits)
		// peek reads bits MSB-aligned: index = top maxBits bits
		idx := reverseLow(v, h.maxBits)
		_ = idx
		code := uint32(0)
		for k := 0; k < h.maxBits; k++ {
			code = code<<1 | br.bit(br.pos-1-k)
		}
		out = append(out, h.sym[code])
		br.pos -= int(h.nb[code])
	}
	return out, nil
}

func reverseLow(v uint32, n int) uint32 { return v }

// ---- decoder ----

type zstdDecoder struct {
	out      []byte
	frameBeg int
	huf      *hufTable
	llT      *fseTable
	ofT      *fseTable
	mlT      *fseTable
	rep      [3]uint32
