func newZstdReader(r io.Reader) (io.Reader, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	d := &zstdDecoder{}
	pos := 0
	for pos < len(data) {
		if len(data)-pos < 4 {
			return nil, errZstd
		}
		magic := binary.LittleEndian.Uint32(data[pos:])
		if magic&0xFFFFFFF0 == 0x184D2A50 {
			if len(data)-pos < 8 {
				return nil, errZstd
			}
			n := int(binary.LittleEndian.Uint32(data[pos+4:]))
			pos += 8 + n
			continue
		}
		if magic != 0xFD2FB528 {
			return nil, errZstd
		}
		n, err := d.decodeFrame(data[pos+4:])
		if err != nil {
			return nil, err
		}
		pos += 4 + n
	}
	return bytes.NewReader(d.out), nil
}

func (d *zstdDecoder) decodeFrame(data []byte) (int, error) {
	if len(data) < 1 {
		return 0, errZstd
	}
	fhd := data[0]
	pos := 1
	single := fhd&0x20 != 0
	checksum := fhd&0x04 != 0
	dictFlag := fhd & 3
	fcsFlag := fhd >> 6
	if !single {
		pos++
	}
	pos += []int{0, 1, 2, 4}[dictFlag]
	fcsSize := []int{0, 2, 4, 8}[fcsFlag]
	if fcsFlag == 0 && single {
		fcsSize = 1
	}
	pos += fcsSize
	if pos > len(data) {
		return 0, errZstd
	}
	d.frameBeg = len(d.out)
	d.rep = [3]uint32{1, 4, 8}
	d.huf = nil
	d.llT, d.ofT, d.mlT = nil, nil, nil
	for {
		if pos+3 > len(data) {
			return 0, errZstd
		}
		bh := uint32(data[pos]) | uint32(data[pos+1])<<8 | uint32(data[pos+2])<<16
		pos += 3
		last := bh&1 != 0
		btype := (bh >> 1) & 3
		bsize := int(bh >> 3)
		switch btype {
		case 0:
			if pos+bsize > len(data) {
				return 0, errZstd
			}
			d.out = append(d.out, data[pos:pos+bsize]...)
			pos += bsize
		case 1:
			if pos+1 > len(data) {
				return 0, errZstd
			}
			for i := 0; i < bsize; i++ {
				d.out = append(d.out, data[pos])
			}
			pos++
		case 2:
			if pos+bsize > len(data) {
				return 0, errZstd
			}
			if err := d.decodeBlock(data[pos : pos+bsize]); err != nil {
				return 0, err
			}
			pos += bsize
		default:
			return 0, errZstd
		}
		if last {
			break
		}
	}
	if checksum {
		pos += 4
	}
	if pos > len(data) {
		return 0, errZstd
	}
	return pos, nil
}

func (d *zstdDecoder) decodeBlock(blk []byte) error {
	if len(blk) < 1 {
		return errZstd
	}
	// literals
	b0 := blk[0]
	ltype := b0 & 3
	sf := (b0 >> 2) & 3
	var lits []byte
	pos := 0
	switch ltype {
	case 0, 1:
		var size int
		switch sf {
		case 0, 2:
			size = int(b0 >> 3)
			pos = 1
		case 1:
			if len(blk) < 2 {
				return errZstd
			}
			size = int(b0>>4) | int(blk[1])<<4
			pos = 2
		case 3:
			if len(blk) < 3 {
				return errZstd
			}
			size = int(b0>>4) | int(blk[1])<<4 | int(blk[2])<<12
			pos = 3
		}
		if ltype == 0 {
			if pos+size > len(blk) {
				return errZstd
			}
			lits = blk[pos : pos+size]
			pos += size
		} else {
			if pos+1 > len(blk) {
				return errZstd
			}
			lits = bytes.Repeat([]byte{blk[pos]}, size)
			pos++
		}
	case 2, 3:
		var regen, comp, hlen int
		streams := 4
		switch sf {
		case 0, 1:
			if len(blk) < 3 {
				return errZstd
			}
			v := uint32(blk[0]) | uint32(blk[1])<<8 | uint32(blk[2])<<16
			regen = int(v>>4) & 0x3FF
			comp = int(v>>14) & 0x3FF
			hlen = 3
			if sf == 0 {
				streams = 1
			}
		case 2:
			if len(blk) < 4 {
				return errZstd
			}
			v := binary.LittleEndian.Uint32(blk)
			regen = int(v>>4) & 0x3FFF
			comp = int(v>>18) & 0x3FFF
			hlen = 4
		case 3:
			if len(blk) < 5 {
				return errZstd
			}
			v := uint64(binary.LittleEndian.Uint32(blk)) | uint64(blk[4])<<32
			regen = int(v>>4) & 0x3FFFF
			comp = int(v>>22) & 0x3FFFF
			hlen = 5
		}
		pos = hlen
		if pos+comp > len(blk) {
			return errZstd
		}
		src := blk[pos : pos+comp]
		pos += comp
		if ltype == 2 {
			h, n, err := readHuffmanTree(src)
			if err != nil {
				return err
			}
			d.huf = h
			src = src[n:]
		} else if d.huf == nil {
			return errZstd
		}
		lits = make([]byte, 0, regen)
		var err error
		if streams == 1 {
			lits, err = hufDecodeStream(d.huf, src, regen, lits)
			if err != nil {
				return err
			}
		} else {
			if len(src) < 6 {
				return errZstd
			}
			s1 := int(binary.LittleEndian.Uint16(src))
			s2 := int(binary.LittleEndian.Uint16(src[2:]))
			s3 := int(binary.LittleEndian.Uint16(src[4:]))
			src = src[6:]
			if s1+s2+s3 > len(src) {
				return errZstd
			}
			parts := [][]byte{src[:s1], src[s1 : s1+s2], src[s1+s2 : s1+s2+s3], src[s1+s2+s3:]}
			per := (regen + 3) / 4
			for i, p := range parts {
				n := per
				if i == 3 {
					n = regen - 3*per
				}
				lits, err = hufDecodeStream(d.huf, p, n, lits)
				if err != nil {
					return err
				}
			}
		}
	}
	// sequences
	if pos >= len(blk) {
		d.out = append(d.out, lits...)
		return nil
	}
	nseq := int(blk[pos])
	pos++
	if nseq >= 128 {
		if nseq < 255 {
			if pos >= len(blk) {
				return errZstd
			}
			nseq = ((nseq - 128) << 8) + int(blk[pos])
			pos++
		} else {
			if pos+2 > len(blk) {
				return errZstd
			}
			nseq = int(blk[pos]) + int(blk[pos+1])<<8 + 0x7F00
			pos += 2
		}
	}
	if nseq == 0 {
		d.out = append(d.out, lits...)
		return nil
	}
	if pos >= len(blk) {
		return errZstd
	}
	modes := blk[pos]
	pos++
	var err error
	readTable := func(mode byte, predef []int16, predefAcc int, maxSym int, maxAcc int, cur *fseTable) (*fseTable, error) {
		switch mode {
		case 0:
			return buildFSE(predef, predefAcc)
		case 1:
			if pos >= len(blk) {
				return nil, errZstd
			}
			t := rleFSE(blk[pos])
			pos++
			return t, nil
		case 2:
			t, n, err := readFSETable(blk[pos:], maxSym, maxAcc)
			if err != nil {
				return nil, err
			}
			pos += n
			return t, nil
		default:
			if cur == nil {
				return nil, errZstd
			}
			return cur, nil
		}
	}
	if d.llT, err = readTable(modes>>6, predefLL, 6, 35, 9, d.llT); err != nil {
		return err
	}
	if d.ofT, err = readTable((modes>>4)&3, predefOF, 5, 31, 8, d.ofT); err != nil {
		return err
	}
	if d.mlT, err = readTable((modes>>2)&3, predefML, 6, 52, 9, d.mlT); err != nil {
		return err
	}
	br, err := newBwdBits(blk[pos:])
	if err != nil {
		return err
	}
	llS := br.read(d.llT.accuracy)
	ofS := br.read(d.ofT.accuracy)
	mlS := br.read(d.mlT.accuracy)
	litPos := 0
	for i := 0; i < nseq; i++ {
		llE := d.llT.entries[llS]
		ofE := d.ofT.entries[ofS]
		mlE := d.mlT.entries[mlS]
		ofCode := int(ofE.sym)
		if ofCode > 31 || int(llE.sym) >= len(llBase) || int(mlE.sym) >= len(mlBase) {
			return errZstd
		}
		ofVal := uint32(1)<<ofCode + br.read(ofCode)
		ml := mlBase[mlE.sym] + br.read(int(mlBits[mlE.sym]))
		ll := llBase[llE.sym] + br.read(int(llBits[llE.sym]))
		var offset uint32
		if ofVal > 3 {
			offset = ofVal - 3
			d.rep[2], d.rep[1], d.rep[0] = d.rep[1], d.rep[0], offset
		} else {
			idx := int(ofVal)
			if ll == 0 {
				idx++
			}
			switch idx {
			case 1:
				offset = d.rep[0]
			case 2:
				offset = d.rep[1]
				d.rep[1] = d.rep[0]
				d.rep[0] = offset
			case 3:
				offset = d.rep[2]
				d.rep[2] = d.rep[1]
				d.rep[1] = d.rep[0]
				d.rep[0] = offset
			case 4:
				offset = d.rep[0] - 1
				if offset == 0 {
					offset = 1
				}
				d.rep[2] = d.rep[1]
				d.rep[1] = d.rep[0]
				d.rep[0] = offset
			}
		}
		if litPos+int(ll) > len(lits) {
			return errZstd
		}
		d.out = append(d.out, lits[litPos:litPos+int(ll)]...)
		litPos += int(ll)
		if int(offset) > len(d.out)-d.frameBeg || offset == 0 {
			return errZstd
		}
		start := len(d.out) - int(offset)
		for k := 0; k < int(ml); k++ {
			d.out = append(d.out, d.out[start+k])
		}
		if i < nseq-1 {
			llS = uint32(llE.baseline) + br.read(int(llE.nbBits))
			mlS = uint32(mlE.baseline) + br.read(int(mlE.nbBits))
			ofS = uint32(ofE.baseline) + br.read(int(ofE.nbBits))
		}
	}
	d.out = append(d.out, lits[litPos:]...)
	return nil
}
