package main

import (
	"io"
	"sort"
)

// bzip2 encoder (block size level 6).

type bitWriter struct {
	out   []byte
	acc   uint64
	nbits uint
}

func (b *bitWriter) write(v uint64, n uint) {
	for n > 0 {
		take := n
		if take > 32 {
			take = 32
		}
		n -= take
		b.acc = b.acc<<take | (v>>n)&(1<<take-1)
		b.nbits += take
		for b.nbits >= 8 {
			b.nbits -= 8
			b.out = append(b.out, byte(b.acc>>b.nbits))
		}
	}
}

func (b *bitWriter) flush() {
	if b.nbits > 0 {
		b.out = append(b.out, byte(b.acc<<(8-b.nbits)))
		b.nbits = 0
	}
}

var bzCRCTable [256]uint32

func init() {
	for i := 0; i < 256; i++ {
		c := uint32(i) << 24
		for j := 0; j < 8; j++ {
			if c&0x80000000 != 0 {
				c = c<<1 ^ 0x04c11db7
			} else {
				c <<= 1
			}
		}
		bzCRCTable[i] = c
	}
}

func bzCRC(crc uint32, data []byte) uint32 {
	crc = ^crc
	for _, b := range data {
		crc = crc<<8 ^ bzCRCTable[byte(crc>>24)^b]
	}
	return ^crc
}

type bzip2Writer struct {
	w        io.Writer
	buf      []byte
	level    int
	bw       bitWriter
	combined uint32
	started  bool
}

func newBzip2Writer(w io.Writer) io.WriteCloser {
	return &bzip2Writer{w: w, level: 6}
}

func (z *bzip2Writer) Write(p []byte) (int, error) {
	z.buf = append(z.buf, p...)
	return len(p), nil
}

func (z *bzip2Writer) Close() error {
	z.bw.write('B', 8)
	z.bw.write('Z', 8)
	z.bw.write('h', 8)
	z.bw.write(uint64('0'+z.level), 8)
	maxBlock := 100000*z.level - 19
	data := z.buf
	for len(data) > 0 {
		// RLE1 until the block is full
		var rle []byte
		consumed := 0
		for consumed < len(data) && len(rle) < maxBlock-5 {
			c := data[consumed]
			run := 1
			for consumed+run < len(data) && data[consumed+run] == c && run < 255 {
				run++
			}
			if run >= 4 {
				rle = append(rle, c, c, c, c, byte(run-4))
			} else {
				for i := 0; i < run; i++ {
					rle = append(rle, c)
				}
			}
			consumed += run
		}
