// cyclicSuffixArray sorts the cyclic rotations of s.
func cyclicSuffixArray(s []byte) []int {
	n := len(s)
	sa := make([]int, n)
	rank := make([]int, n)
	tmp := make([]int, n)
	for i := range sa {
		sa[i] = i
		rank[i] = int(s[i])
	}
	sort.SliceStable(sa, func(a, b int) bool { return s[sa[a]] < s[sa[b]] })
	for k := 1; k < n; k <<= 1 {
		// sort by (rank[i], rank[i+k]) using counting sort on second then first key
		key2 := func(i int) int { return rank[(i+k)%n] }
		maxR := 0
		for _, r := range rank {
			if r > maxR {
				maxR = r
			}
		}
		cnt := make([]int, maxR+2)
		sa2 := make([]int, n)
		for i := 0; i < n; i++ {
			cnt[key2(i)+1]++
		}
		for i := 1; i < len(cnt); i++ {
			cnt[i] += cnt[i-1]
		}
		order := make([]int, n)
		for i := 0; i < n; i++ {
			order[cnt[key2(i)]] = i
			cnt[key2(i)]++
		}
		cnt = make([]int, maxR+2)
		for i := 0; i < n; i++ {
			cnt[rank[i]+1]++
		}
		for i := 1; i < len(cnt); i++ {
			cnt[i] += cnt[i-1]
		}
		for _, i := range order {
			sa2[cnt[rank[i]]] = i
			cnt[rank[i]]++
		}
		sa = sa2
		tmp[sa[0]] = 0
		classes := 1
		for i := 1; i < n; i++ {
			a, b := sa[i-1], sa[i]
			if rank[a] != rank[b] || key2(a) != key2(b) {
				classes++
			}
			tmp[b] = classes - 1
		}
		copy(rank, tmp)
		if classes == n {
			break
		}
	}
	return sa
}

func (z *bzip2Writer) encodeBlock(block []byte, crc uint32) {
	bw := &z.bw
	n := len(block)
	sa := cyclicSuffixArray(block)
	last := make([]byte, n)
	origPtr := 0
	for i, p := range sa {
		if p == 0 {
			origPtr = i
			last[i] = block[n-1]
		} else {
			last[i] = block[p-1]
		}
	}
	// symbol map
	var inUse [256]bool
	for _, c := range block {
		inUse[c] = true
	}
	var seqToUnseq []byte
	var unseqToSeq [256]int
	for i := 0; i < 256; i++ {
		if inUse[i] {
			unseqToSeq[i] = len(seqToUnseq)
			seqToUnseq = append(seqToUnseq, byte(i))
		}
	}
	nInUse := len(seqToUnseq)
	alpha := nInUse + 2
	// MTF + RLE2
	mtf := make([]byte, nInUse)
	for i := range mtf {
		mtf[i] = byte(i)
	}
	var syms []uint16
	zrun := 0
	flushRun := func() {
		if zrun == 0 {
			return
		}
		zp := zrun - 1
		for {
			if zp&1 != 0 {
				syms = append(syms, 1)
			} else {
				syms = append(syms, 0)
			}
			if zp < 2 {
				break
			}
			zp = (zp - 2) / 2
		}
		zrun = 0
	}
	for _, c := range last {
		v := byte(unseqToSeq[c])
		j := 0
		for mtf[j] != v {
			j++
		}
		if j == 0 {
			zrun++
			continue
		}
		flushRun()
		copy(mtf[1:j+1], mtf[:j])
		mtf[0] = v
		syms = append(syms, uint16(j+1))
	}
	flushRun()
	syms = append(syms, uint16(nInUse+1))

	numTrees := 6
	for i, lim := range []int{200, 600, 1200, 2400} {
		if len(syms) < lim {
			numTrees = 2 + i
			break
		}
	}
	numSels := (len(syms) + 49) / 50
	treeSels := make([]int, numSels)
	for i := range treeSels {
		treeSels[i] = i % numTrees
	}
	lens := make([][]int, numTrees)
	codes := make([][]uint32, numTrees)
	for t := 0; t < numTrees; t++ {
		cnt := make([]int, alpha)
		for i, s := range syms {
			if treeSels[i/50] == t {
				cnt[s]++
			}
		}
		lens[t] = bzGenerateLengths(cnt, 17)
		codes[t] = bzCanonicalCodes(lens[t])
	}

	bw.write(0x314159265359, 48)
	bw.write(uint64(crc), 32)
	bw.write(0, 1)
	bw.write(uint64(origPtr), 24)
