	for i := 0; i < 16; i++ {
		for j := 0; j < 16; j++ {
			if inUse[i*16+j] {
				used16 |= 1 << (15 - i)
				break
			}
		}
	}
	bw.write(used16, 16)
	for i := 0; i < 16; i++ {
		if used16&(1<<(15-i)) == 0 {
			continue
		}
		var m uint64
		for j := 0; j < 16; j++ {
			if inUse[i*16+j] {
				m |= 1 << (15 - j)
			}
		}
		bw.write(m, 16)
	}
	bw.write(uint64(numTrees), 3)
	bw.write(uint64(numSels), 15)
	selMTF := make([]int, numTrees)
	for i := range selMTF {
		selMTF[i] = i
	}
	for _, s := range treeSels {
		j := 0
		for selMTF[j] != s {
			j++
		}
		copy(selMTF[1:j+1], selMTF[:j])
		selMTF[0] = s
		for k := 0; k < j; k++ {
			bw.write(1, 1)
		}
		bw.write(0, 1)
	}
	for t := 0; t < numTrees; t++ {
		cur := lens[t][0]
		bw.write(uint64(cur), 5)
		for _, l := range lens[t] {
			for cur < l {
				bw.write(2, 2)
				cur++
			}
			for cur > l {
				bw.write(3, 2)
				cur--
			}
			bw.write(0, 1)
		}
	}
	for i, s := range syms {
		t := treeSels[i/50]
		bw.write(uint64(codes[t][s]), uint(lens[t][s]))
	}
}

// bzGenerateLengths computes Huffman code lengths (Moffat-Katajainen on sorted counts).
func bzGenerateLengths(cnt []int, maxBits int) []int {
	n := len(cnt)
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool { return cnt[order[a]] < cnt[order[b]] })
	work := make([]int, n)
	for i, o := range order {
		work[i] = cnt[o]
	}
	for {
		L := moffatKatajainen(work)
		max := 0
		for _, l := range L {
			if l > max {
				max = l
			}
		}
		if max <= maxBits {
			lens := make([]int, n)
			for i, o := range order {
				lens[o] = L[i]
			}
			return lens
		}
		for i := range work {
			work[i] = 1 + work[i]/2
		}
	}
}

func moffatKatajainen(w []int) []int {
	n := len(w)
	A := append([]int{}, w...)
	if n == 1 {
		return []int{1}
	}
	s, r := 0, 0
	for t := 0; t < n-1; t++ {
		if s >= n || (r < t && A[r] < A[s]) {
			A[t] = A[r]
			A[r] = t
			r++
		} else {
			A[t] = A[s]
			s++
		}
		if s >= n || (r < t && A[r] < A[s]) {
			A[t] += A[r]
			A[r] = t
			r++
		} else {
			A[t] += A[s]
			s++
		}
	}
	A[n-2] = 0
	for t := n - 3; t >= 0; t-- {
		A[t] = A[A[t]] + 1
	}
	a, u, d, t, x := 1, 0, 0, n-2, n-1
	for a > 0 {
		for t >= 0 && A[t] == d {
			u++
			t--
		}
		for a > u {
			A[x] = d
			x--
			a--
		}
		a = 2 * u
		d++
		u = 0
	}
	return A
}

func bzCanonicalCodes(lens []int) []uint32 {
	codes := make([]uint32, len(lens))
	minL, maxL := 32, 0
	for _, l := range lens {
		if l < minL {
			minL = l
		}
		if l > maxL {
			maxL = l
		}
	}
	code := uint32(0)
	for l := minL; l <= maxL; l++ {
		for s, sl := range lens {
			if sl == l {
				codes[s] = code
				code++
			}
		}
		code <<= 1
	}
	return codes
}
