// bzGenerateLengths computes Huffman code lengths (Moffat-Katajainen on sorted counts).
func bzGenerateLengths(cnt []int, maxBits int) []int {
	n := len(cnt)
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool { return cnt[order[a]] < cnt[order[b]] })
	work := make([]int, n)
	for i, o := range order {
		work[i] = cnt[o]
	}
	for {
		L := moffatKatajainen(work)
		max := 0
		for _, l := range L {
			if l > max {
				max = l
			}
		}
		if max <= maxBits {
			lens := make([]int, n)
			for i, o := range order {
				lens[o] = L[i]
			}
			return lens
		}
		for i := range work {
			work[i] = 1 + work[i]/2
		}
	}
}

func moffatKatajainen(w []int) []int {
	n := len(w)
	A := append([]int{}, w...)
	if n == 1 {
		return []int{1}
	}
	s, r := 0, 0
	for t := 0; t < n-1; t++ {
		if s >= n || (r < t && A[r] < A[s]) {
			A[t] = A[r]
			A[r] = t
			r++
		} else {
			A[t] = A[s]
			s++
		}
		if s >= n || (r < t && A[r] < A[s]) {
			A[t] += A[r]
			A[r] = t
			r++
		} else {
			A[t] += A[s]
			s++
		}
	}
	A[n-2] = 0
	for t := n - 3; t >= 0; t-- {
		A[t] = A[A[t]] + 1
	}
	a, u, d, t, x := 1, 0, 0, n-2, n-1
	for a > 0 {
		for t >= 0 && A[t] == d {
			u++
			t--
		}
		for a > u {
			A[x] = d
			x--
			a--
		}
		a = 2 * u
		d++
		u = 0
	}
	return A
}

func bzCanonicalCodes(lens []int) []uint32 {
	codes := make([]uint32, len(lens))
	minL, maxL := 32, 0
	for _, l := range lens {
		if l < minL {
			minL = l
		}
		if l > maxL {
			maxL = l
		}
	}
	code := uint32(0)
	for l := minL; l <= maxL; l++ {
		for s, sl := range lens {
			if sl == l {
				codes[s] = code
				code++
			}
		}
		code <<= 1
	}
	return codes
}
