package main

import (
	"strconv"
	"strings"
)

// Rewriting of the JSON arrow operators (-> and ->>) for older SQLite versions.

type sqlTok struct {
	kind string // ws, str, ident, num, op, punct, comment
	s    string
}

func lexSQL(q string) []sqlTok {
	var toks []sqlTok
	i := 0
	for i < len(q) {
		c := q[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v':
			j := i
			for j < len(q) && strings.IndexByte(" \t\n\r\f\v", q[j]) >= 0 {
				j++
			}
			toks = append(toks, sqlTok{"ws", q[i:j]})
			i = j
		case c == '-' && i+1 < len(q) && q[i+1] == '-':
			j := strings.IndexByte(q[i:], '\n')
			if j < 0 {
				j = len(q) - i
			}
			toks = append(toks, sqlTok{"comment", q[i : i+j]})
			i += j
		case c == '/' && i+1 < len(q) && q[i+1] == '*':
			j := strings.Index(q[i+2:], "*/")
			if j < 0 {
				j = len(q) - i
			} else {
				j += 4
			}
			toks = append(toks, sqlTok{"comment", q[i : i+j]})
			i += j
		case c == '\'' || c == '"' || c == '`' || c == '[':
			end := c
			if c == '[' {
				end = ']'
			}
			j := i + 1
			for j < len(q) {
				if q[j] == end {
					if end != ']' && j+1 < len(q) && q[j+1] == end {
						j += 2
						continue
					}
					break
				}
				j++
			}
			if j < len(q) {
				j++
			}
			kind := "ident"
			if c == '\'' {
				kind = "str"
			}
			toks = append(toks, sqlTok{kind, q[i:j]})
			i = j
		case c == '-' && i+1 < len(q) && q[i+1] == '>':
			if i+2 < len(q) && q[i+2] == '>' {
				toks = append(toks, sqlTok{"op", "->>"})
				i += 3
			} else {
				toks = append(toks, sqlTok{"op", "->"})
				i += 2
			}
		case (c >= '0' && c <= '9') || (c == '.' && i+1 < len(q) && q[i+1] >= '0' && q[i+1] <= '9'):
			j := i
			for j < len(q) && (isIdentChar(q[j]) || q[j] == '.') {
				j++
			}
			toks = append(toks, sqlTok{"num", q[i:j]})
			i = j
		case isIdentStart(c) || c >= 0x80 || c == '$' || c == '@' || c == ':' || c == '?' || c == '#':
			j := i + 1
			for j < len(q) && (isIdentChar(q[j]) || q[j] >= 0x80 || q[j] == '$') {
				j++
			}
			toks = append(toks, sqlTok{"ident", q[i:j]})
			i = j
		case c == '(' || c == ')' || c == ',' || c == ';' || c == '.':
			toks = append(toks, sqlTok{"punct", string(c)})
			i++
		default:
			toks = append(toks, sqlTok{"op", string(c)})
			i++
		}
	}
	return toks
}

func joinToks(toks []sqlTok) string {
	var sb strings.Builder
	for _, t := range toks {
		sb.WriteString(t.s)
	}
	return sb.String()
}

func skipBack(toks []sqlTok, i int) int {
	for i >= 0 && (toks[i].kind == "ws" || toks[i].kind == "comment") {
		i--
	}
	return i
}

func skipFwd(toks []sqlTok, i int) int {
	for i < len(toks) && (toks[i].kind == "ws" || toks[i].kind == "comment") {
		i++
	}
	return i
}

// leftOperand returns the start index of the operand ending at index e.
func leftOperand(toks []sqlTok, e int) int {
	if e < 0 {
		return -1
	}
	t := toks[e]
	start := e
	if t.kind == "punct" && t.s == ")" {
		depth := 0
		k := e
		for ; k >= 0; k-- {
			if toks[k].kind == "punct" && toks[k].s == ")" {
				depth++
			} else if toks[k].kind == "punct" && toks[k].s == "(" {
				depth--
				if depth == 0 {
					break
				}
			}
		}
		if k < 0 {
			return -1
		}
		start = k
		p := skipBack(toks, k-1)
		if p >= 0 && toks[p].kind == "ident" {
			start = p
		}
		return start
	}
	if t.kind == "ident" || t.kind == "str" || t.kind == "num" {
		for {
			p := skipBack(toks, start-1)
			if p >= 0 && toks[p].kind == "punct" && toks[p].s == "." {
				q := skipBack(toks, p-1)
				if q >= 0 && toks[q].kind == "ident" {
					start = q
					continue
				}
			}
			break
		}
		return start
	}
	return -1
}

// rightOperand returns the end index (inclusive) of the operand starting at s.
func rightOperand(toks []sqlTok, s int) int {
	if s >= len(toks) {
		return -1
	}
	t := toks[s]
	if t.kind == "punct" && t.s == "(" {
		depth := 0
		for k := s; k < len(toks); k++ {
			if toks[k].kind == "punct" && toks[k].s == "(" {
				depth++
			} else if toks[k].kind == "punct" && toks[k].s == ")" {
				depth--
				if depth == 0 {
					return k
				}
			}
		}
		return -1
	}
	if t.kind == "op" && t.s == "-" {
		n := skipFwd(toks, s+1)
		if n < len(toks) && toks[n].kind == "num" {
			return n
		}
		return -1
	}
	if t.kind == "str" || t.kind == "num" || t.kind == "ident" {
		end := s
		if t.kind == "ident" {
			for {
				p := skipFwd(toks, end+1)
				if p < len(toks) && toks[p].kind == "punct" && toks[p].s == "." {
					q := skipFwd(toks, p+1)
					if q < len(toks) && toks[q].kind == "ident" {
						end = q
						continue
					}
				}
				break
			}
		}
		return end
	}
	return -1
}

// rewriteArrows rewrites X->Y and X->>Y into function calls.
func rewriteArrows(q string) string {
	if !strings.Contains(q, "->") {
		return q
	}
	for iter := 0; iter < 1000; iter++ {
		toks := lexSQL(q)
		idx := -1
		for i, t := range toks {
			if t.kind == "op" && (t.s == "->" || t.s == "->>") {
				idx = i
				break
			}
		}
		if idx < 0 {
			return q
		}
		le := skipBack(toks, idx-1)
		ls := leftOperand(toks, le)
		rs := skipFwd(toks, idx+1)
		re := rightOperand(toks, rs)
		if ls < 0 || re < 0 {
			return q
		}
		left := joinToks(toks[ls : le+1])
		right := joinToks(toks[rs : re+1])
		var repl string
		if toks[idx].s == "->>" {
			repl = "json_extract(" + left + ", trd_jpath(" + right + "))"
		} else {
			repl = "trd_jarrow(" + left + ", trd_jpath(" + right + "))"
		}
		q = joinToks(toks[:ls]) + repl + joinToks(toks[re+1:])
	}
	return q
}

func registerArrowFunctions(db *DB) {
	db.RegisterScalar("trd_jpath", 1, true, func(args []sqlValue) (sqlValue, error) {
		switch t := args[0].(type) {
		case int64:
			if t < 0 {
				return "$[#" + strconv.FormatInt(t, 10) + "]", nil
			}
			return "$[" + strconv.FormatInt(t, 10) + "]", nil
		case float64:
			return "$[" + strconv.FormatInt(int64(t), 10) + "]", nil
		case nil:
			return nil, nil
		}
		s, _ := sqlText(args[0])
		if strings.HasPrefix(s, "$") {
			return s, nil
		}
		return "$." + s, nil
	})
	db.RegisterScalar("trd_jarrow", 2, true, func(args []sqlValue) (sqlValue, error) {
		if args[0] == nil || args[1] == nil {
			return nil, nil
		}
		typ, err := db.queryScalar("SELECT json_type(?, ?)", args[0], args[1])
		if err != nil {
			return nil, err
		}
		if typ == nil {
			return nil, nil
		}
		return db.queryScalar("SELECT json_quote(json_extract(?, ?))", args[0], args[1])
	})
}
