s=open(p).read()
s=s.replace('''func main() {
	os.Exit(run(os.Args))
}''','''func main() {
	defer func() {
		if r := recover(); r != nil {
			log.Printf("ERROR: %v", r)
			os.Exit(1)
		}
	}()
	os.Exit(run(os.Args))
}''')
open(p,'w').write(s)
EOF
gofmt -w *.go && go build -o /tmp/trd . && git add -A && git commit -qm "jq string interpolation, panic guard" && echo ok

